/**
 * @script            spelling.test
 * @category          validator
 * @purpose           qa:content-quality
 * @scope             tests
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement Spelling check — validates content against custom dictionary with en-GB rules
 * @pipeline          P1, P3
 * @usage             node tests/unit/spelling.test.js [flags]
 */
/**
 * UK English spelling validation tests
 */

const { execSync } = require('child_process');
const { getMdxFiles, getStagedDocsPageFiles } = require('../utils/file-walker');
const { checkMultipleFiles, resolveCspellBinary, resolveCspellConfig } = require('../utils/spell-checker');

let errors = [];

/**
 * Extract text content from MDX (excluding code blocks and frontmatter)
 */
function extractTextContent(content) {
  // Remove frontmatter
  let text = content.replace(/^---\s*\n[\s\S]*?\n---\s*\n/, '');

  // Remove code blocks
  text = text.replace(/```[\s\S]*?```/g, '');

  // Remove inline code
  text = text.replace(/`[^`]+`/g, '');

  // Remove JSX tags (keep text content)
  text = text.replace(/<[^>]+>/g, ' ');

  return text;
}

/**
 * Run spelling tests
 */
async function runTests(options = {}) {
  errors = [];

  const { files = null, stagedOnly = false } = options;

  let testFiles = files;
  if (!testFiles) {
    if (stagedOnly) {
      testFiles = getStagedDocsPageFiles().filter(f => f.endsWith('.mdx'));
    } else {
      testFiles = getMdxFiles();
    }
  }

  // Check if cspell is available
  const cspell = resolveCspellBinary();
  try {
    if (cspell.viaNpx) {
      execSync('npx cspell --version', { stdio: 'ignore' });
    } else {
      execSync(`"${cspell.bin}" --version`, { stdio: 'ignore' });
    }
  } catch (error) {
    console.warn('⚠️  cspell not available. Install with: npm install');
    return { errors: [], warnings: ['cspell not available'], passed: true, total: testFiles.length };
  }

  const cspellConfig = resolveCspellConfig();
  const results = checkMultipleFiles(testFiles, cspellConfig);

  results.forEach(result => {
    if (result.errors.length > 0) {
      errors.push({
        file: result.file,
        errors: result.errors
      });
    }
  });

  return {
    errors,
    passed: errors.length === 0,
    total: testFiles.length
  };
}

// Run if called directly
if (require.main === module) {
  const args = process.argv.slice(2);
  const stagedOnly = args.includes('--staged');

  runTests({ stagedOnly }).then(result => {
    if (result.errors.length > 0) {
      console.error('\n❌ Spelling Errors:\n');
      result.errors.forEach(fileError => {
        console.error(`  ${fileError.file}:`);
        fileError.errors.forEach(err => {
          console.error(`    Line ${err.line}:${err.column} - Unknown word: "${err.word}"`);
        });
      });
    }

    if (result.passed) {
      console.log(`\n✅ Spelling checks passed (${result.total} files checked)`);
      process.exit(0);
    } else {
      const totalErrors = result.errors.reduce((sum, e) => sum + e.errors.length, 0);
      console.error(`\n❌ ${totalErrors} spelling error(s) found`);
      process.exit(1);
    }
  }).catch(error => {
    console.error('Spelling test error:', error);
    process.exit(1);
  });
}

module.exports = { runTests };

#!/usr/bin/env node
/**
 * @script            style-guide.test
 * @category          validator
 * @purpose           qa:content-quality
 * @scope             tests
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement Style guide compliance — checks en-GB conventions, heading case, formatting rules
 * @pipeline          P1, P3
 * @usage             node tests/unit/style-guide.test.js [flags]
 */
/**
 * Style guide rule validation tests
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { getMdxFiles, getJsxFiles, getStagedDocsPageFiles, readFile } = require('../utils/file-walker');

const REPO_ROOT = process.cwd();
let errors = [];
let warnings = [];
let changedLineMap = null;

function toPosix(filePath) {
  return String(filePath || '').split(path.sep).join('/');
}

function getChangedLineSetFromDiff(filePath, diffArgs) {
  const relPath = toPosix(path.relative(REPO_ROOT, filePath));
  if (!relPath) {
    return null;
  }

  try {
    const diff = execSync(`git ${diffArgs.join(' ')} -- "${relPath}"`, {
      encoding: 'utf8',
      cwd: REPO_ROOT
    });
    const changedLines = new Set();
    const hunkRegex = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/;

    diff.split('\n').forEach((line) => {
      const match = line.match(hunkRegex);
      if (!match) return;

      const start = Number(match[1]);
      const count = match[2] ? Number(match[2]) : 1;
      if (!Number.isFinite(start) || !Number.isFinite(count) || count <= 0) return;

      for (let i = 0; i < count; i++) {
        changedLines.add(start + i);
      }
    });

    return changedLines;
  } catch (_error) {
    return null;
  }
}

function getStagedChangedLineSet(filePath) {
  return getChangedLineSetFromDiff(filePath, ['diff', '--cached', '--unified=0']);
}

function getBaseRefChangedLineSet(filePath, baseRef) {
  if (!baseRef) {
    return null;
  }

  return getChangedLineSetFromDiff(filePath, ['diff', '--unified=0', `origin/${baseRef}...HEAD`]);
}

function shouldCheckLine(file, line, changedOnly) {
  if (!changedOnly || !changedLineMap) {
    return true;
  }

  const changedLines = changedLineMap.get(file);
  if (!changedLines || changedLines.size === 0) {
    return false;
  }

  return changedLines.has(line);
}

/**
 * Check for ThemeData usage (deprecated)
 */
function checkThemeData(files, stagedOnly = false) {
  files.forEach(file => {
    if (file.includes('style-guide.mdx')) return; // Skip style guide itself

    const content = readFile(file);
    if (!content) return;

    const lines = content.split('\n');
    lines.forEach((line, index) => {
      if (!line.includes('ThemeData') && !line.includes('themeStyles.jsx')) {
        return;
      }
      const lineNumber = index + 1;
      if (!shouldCheckLine(file, lineNumber, stagedOnly)) {
        return;
      }
      errors.push({
        file,
        rule: 'ThemeData usage',
        message: 'Uses deprecated ThemeData - use CSS Custom Properties instead',
        line: lineNumber
      });
    });
  });
}

/**
 * Check for hardcoded colors
 */
function checkHardcodedColors(files, stagedOnly = false) {
  const livepeerColors = ['#3CB540', '#2b9a66', '#18794E', '#181C18', '#E0E4E0', '#717571', '#A0A4A0'];

  files.forEach(file => {
    if (file.includes('style-guide.mdx')) return;

    const content = readFile(file);
    if (!content) return;

    // Skip code blocks and markdown tables
    const lines = content.split('\n');
    let inCodeBlock = false;
    let inTable = false;

    lines.forEach((line, index) => {
      if (line.trim().startsWith('```')) inCodeBlock = !inCodeBlock;
      if (line.includes('|') && line.includes('---')) inTable = true;
      if (line.trim() === '') inTable = false;

      if (!inCodeBlock && !inTable) {
        const lineNumber = index + 1;
        if (!shouldCheckLine(file, lineNumber, stagedOnly)) {
          return;
        }
        livepeerColors.forEach(color => {
          if (line.includes(color) && !line.includes('var(--') && !line.includes('CSS Custom Properties')) {
            errors.push({
              file,
              rule: 'Hardcoded colors',
              message: `Contains hardcoded theme color ${color} - use CSS Custom Properties (var(--accent), etc.)`,
              line: lineNumber
            });
          }
        });
      }
    });
  });
}

/**
 * Check for inline styles in MDX
 */
function checkInlineStylesInMdx(files, stagedOnly = false) {
  files.filter(f => f.endsWith('.mdx')).forEach(file => {
    if (file.includes('style-guide.mdx') || file.includes('component-library')) return;

    const content = readFile(file);
    if (!content) return;

    // Check for style={{}} in MDX (should use components instead)
    const styleRegex = /style\s*=\s*\{\{/g;
    const lines = content.split('\n');

    lines.forEach((line, index) => {
      const lineNumber = index + 1;
      if (!shouldCheckLine(file, lineNumber, stagedOnly)) {
        return;
      }
      if (styleRegex.test(line) && !line.includes('//') && !line.includes('{/*')) {
        errors.push({
          file,
          rule: 'No inline styles in MDX',
          message: 'Inline styles in MDX files - use component primitives instead',
          line: lineNumber
        });
      }
    });
  });
}

/**
 * Check for Tailwind classes
 */
function checkTailwindClasses(files, stagedOnly = false) {
  files.filter(f => f.endsWith('.mdx')).forEach(file => {
    const content = readFile(file);
    if (!content) return;

    // Common Tailwind patterns
    const tailwindPatterns = [
      /\b(flex|grid|gap-\d+|items-center|justify-center|p-\d+|m-\d+|w-\d+|h-\d+)\b/
    ];

    const lines = content.split('\n');
    lines.forEach((line, index) => {
      const lineNumber = index + 1;
      if (!shouldCheckLine(file, lineNumber, stagedOnly)) {
        return;
      }
      if (line.includes('className=')) {
        tailwindPatterns.forEach(pattern => {
          if (pattern.test(line)) {
            warnings.push({
              file,
              rule: 'No Tailwind classes',
              message: 'Tailwind classes detected - use component primitives instead',
              line: lineNumber
            });
          }
        });

#!/usr/bin/env node
/**
 * @script            repair-mdx-safe-markdown
 * @category          remediator
 * @purpose           qa:content-quality
 * @scope             tools/scripts/remediators/content, first-party markdown/mdx files
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement Auto-repairs deterministic MDX-unsafe markdown patterns across first-party markdown and MDX content.
 * @pipeline          P1
 * @dualmode          --dry-run (validator) | --write (remediator)
 * @usage             node tools/scripts/remediators/content/repair-mdx-safe-markdown.js --dry-run [--staged|--files a,b]
 */

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const {
  REPO_ROOT,
  collectTargetMarkdownFiles,
  normalizeRepoPath,
  readFileSafe,
  repairMarkdownContent
} = require('../../../lib/mdx-safe-markdown');

function printHelp() {
  console.log(
    [
      'Usage:',
      '  node tools/scripts/remediators/content/repair-mdx-safe-markdown.js [--dry-run|--write] [--staged|--files a,b] [--stage]',
      '',
      'Modes:',
      '  --dry-run   Report deterministic MDX-safe markdown repairs without writing files (default).',
      '  --write     Apply deterministic MDX-safe markdown repairs.',
      '',
      'Scope:',
      '  --staged    Limit repairs to staged first-party .md/.mdx files.',
      '  --files     Limit repairs to explicit repo-relative files or directories (comma-separated, repeatable).',
      '',
      'Staging:',
      '  --stage     Re-stage files changed by --write.',
      '',
      'Safety:',
      '  - Repairs HTML comments, raw <br> table breaks, raw comparison operators, code-like table cells, and angle-bracket placeholders.',
      '  - Skips fenced code blocks and inline code spans.',
      '  - Leaves ambiguous prose rewrites untouched.'
    ].join('\n')
  );
}

function parseArgs(argv) {
  const args = {
    mode: 'dry-run',
    stagedOnly: false,
    files: [],
    stage: false,
    help: false
  };

  let explicitModeCount = 0;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--help' || token === '-h') {
      args.help = true;
      continue;
    }

    if (token === '--dry-run') {
      args.mode = 'dry-run';
      explicitModeCount += 1;
      continue;
    }

    if (token === '--write') {
      args.mode = 'write';
      explicitModeCount += 1;
      continue;
    }

    if (token === '--staged') {
      args.stagedOnly = true;
      continue;
    }

    if (token === '--stage') {
      args.stage = true;
      continue;
    }

    if (token === '--files') {
      const raw = String(argv[index + 1] || '').trim();
      if (!raw) {
        throw new Error('Missing value for --files');
      }
      raw
        .split(',')
        .map((entry) => entry.trim())
        .filter(Boolean)
        .forEach((entry) => args.files.push(entry));
      index += 1;
      continue;
    }

    if (token.startsWith('--files=')) {
      token
        .slice('--files='.length)
        .split(',')
        .map((entry) => entry.trim())
        .filter(Boolean)
        .forEach((entry) => args.files.push(entry));
      continue;
    }

    throw new Error(`Unknown argument: ${token}`);
  }

  if (explicitModeCount > 1) {
    throw new Error('Choose only one mode: --dry-run or --write');
  }

  if (args.stagedOnly && args.files.length > 0) {
    throw new Error('Use either --staged or --files, not both');
  }

  if (args.stage && args.mode !== 'write') {
    throw new Error('--stage requires --write');
  }

  args.files = [...new Set(args.files)];
  return args;
}

function stageFiles(files) {
  if (!files.length) return;
  const relFiles = files.map((filePath) => normalizeRepoPath(path.relative(REPO_ROOT, filePath)));
  const result = spawnSync('git', ['add', '--', ...relFiles], {
    cwd: REPO_ROOT,
    encoding: 'utf8'
  });

  if (result.status !== 0) {
    throw new Error(result.stderr || result.stdout || 'Failed to stage repaired files');
  }
}

function summariseRepairsByRule(repairs) {
  return repairs.reduce((accumulator, repair) => {
    repair.changes.forEach((change) => {
      accumulator[change.rule] = (accumulator[change.rule] || 0) + 1;
    });
    return accumulator;
  }, {});
}

function run(options = {}) {
  const args = options.args || parseArgs([]);
  const quiet = options.quiet === true;
  const files = Array.isArray(options.files) && options.files.length > 0
    ? options.files
    : collectTargetMarkdownFiles({
        rootDir: REPO_ROOT,
        stagedOnly: args.stagedOnly,
        files: args.files
      });

  const repairs = [];
  const changedFiles = [];

  files.forEach((filePath) => {
    const content = readFileSafe(filePath);
    if (!content) return;

    const result = repairMarkdownContent(content, normalizeRepoPath(path.relative(REPO_ROOT, filePath)));
    if (!result.changed) return;

    repairs.push({
      file: filePath,
      changes: result.changes,
      nextContent: result.content
    });

    if (args.mode === 'write') {
      fs.writeFileSync(filePath, result.content, 'utf8');
      changedFiles.push(filePath);
    }
  });

  if (args.mode === 'write' && args.stage && changedFiles.length > 0) {
    stageFiles(changedFiles);
  }

  const byRule = summariseRepairsByRule(repairs);
  const summary = {
    mode: args.mode,
    scannedFiles: files.length,
    changedFiles: repairs.length,
    stagedFiles: changedFiles.length,
    proposedRepairs: repairs.reduce((total, repair) => total + repair.changes.length, 0),
    byRule,
    repairs
  };

  if (!quiet) {
    const verb = args.mode === 'write' ? 'Applied' : 'Proposed';
    console.log(`\n${verb} ${summary.proposedRepairs} MDX-safe markdown repair(s) across ${summary.changedFiles} file(s) (${summary.scannedFiles} scanned).`);
    Object.entries(byRule)
      .sort((left, right) => left[0].localeCompare(right[0]))
      .forEach(([rule, count]) => {
        console.log(`  - ${rule}: ${count}`);
      });
    repairs.forEach((repair) => {
      console.log(`  ${normalizeRepoPath(path.relative(REPO_ROOT, repair.file))}`);
      repair.changes.forEach((change) => {
        console.log(`    line ${change.line}: ${change.rule}`);
      });
    });
  }

#!/usr/bin/env node
/**
 * @script            check-mdx-safe-markdown
 * @category          validator
 * @purpose           qa:content-quality
 * @scope             tools/scripts/validators/content, first-party markdown/mdx files
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement Validates first-party markdown and MDX content for repo-wide MDX-safe syntax, including parse failures and deterministic unsafe patterns.
 * @pipeline          P1, P3
 * @dualmode          --staged (changed-file scope) | --files (explicit scope) | default full-repo
 * @usage             node tools/scripts/validators/content/check-mdx-safe-markdown.js [--staged|--files a,b] [--json]
 */

const path = require('path');
const {
  REPO_ROOT,
  collectTargetMarkdownFiles,
  normalizeRepoPath,
  readFileSafe,
  validateMarkdownContent
} = require('../../../lib/mdx-safe-markdown');

function printHelp() {
  console.log(
    [
      'Usage:',
      '  node tools/scripts/validators/content/check-mdx-safe-markdown.js [--staged|--files a,b] [--json]',
      '',
      'Scope:',
      '  --staged    Validate staged first-party .md/.mdx files only.',
      '  --files     Validate explicit repo-relative files or directories (comma-separated, repeatable).',
      '',
      'Output:',
      '  --json      Emit machine-readable JSON findings.'
    ].join('\n')
  );
}

function parseArgs(argv) {
  const args = {
    stagedOnly: false,
    files: [],
    json: false,
    help: false
  };

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--help' || token === '-h') {
      args.help = true;
      continue;
    }

    if (token === '--staged') {
      args.stagedOnly = true;
      continue;
    }

    if (token === '--json') {
      args.json = true;
      continue;
    }

    if (token === '--files') {
      const raw = String(argv[index + 1] || '').trim();
      if (!raw) throw new Error('Missing value for --files');
      raw
        .split(',')
        .map((entry) => entry.trim())
        .filter(Boolean)
        .forEach((entry) => args.files.push(entry));
      index += 1;
      continue;
    }

    if (token.startsWith('--files=')) {
      token
        .slice('--files='.length)
        .split(',')
        .map((entry) => entry.trim())
        .filter(Boolean)
        .forEach((entry) => args.files.push(entry));
      continue;
    }

    throw new Error(`Unknown argument: ${token}`);
  }

  if (args.stagedOnly && args.files.length > 0) {
    throw new Error('Use either --staged or --files, not both');
  }

  args.files = [...new Set(args.files)];
  return args;
}

function run(options = {}) {
  const args = options.args || parseArgs([]);
  const files = Array.isArray(options.files) && options.files.length > 0
    ? options.files
    : collectTargetMarkdownFiles({
        rootDir: REPO_ROOT,
        stagedOnly: args.stagedOnly,
        files: args.files
      });

  const findings = [];

  files.forEach((filePath) => {
    const content = readFileSafe(filePath);
    if (!content) return;

    const relPath = normalizeRepoPath(path.relative(REPO_ROOT, filePath));
    const result = validateMarkdownContent(content, relPath);
    result.findings.forEach((finding) => {
      findings.push({
        file: relPath,
        line: finding.line || 1,
        column: finding.column || 1,
        rule: finding.rule || 'mdx-safe-markdown',
        message: finding.message || 'Unknown MDX-safe markdown violation'
      });
    });
  });

  return {
    files,
    findings,
    errors: findings,
    warnings: [],
    passed: findings.length === 0,
    total: files.length
  };
}

if (require.main === module) {
  try {
    const args = parseArgs(process.argv.slice(2));
    if (args.help) {
      printHelp();
      process.exit(0);
    }

    const result = run({ args });
    if (args.json) {
      process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    } else if (result.findings.length > 0) {
      console.error('\n❌ MDX-safe Markdown Violations:\n');
      result.findings.forEach((finding) => {
        console.error(`  ${finding.file}:${finding.line}:${finding.column} - ${finding.rule}: ${finding.message}`);
      });
      console.error(`\n❌ ${result.findings.length} violation(s) found across ${result.total} file(s)`);
    } else {
      console.log(`\n✅ MDX-safe markdown validation passed (${result.total} files checked)`);
    }

    process.exit(result.passed ? 0 : 1);
  } catch (error) {
    console.error(`❌ ${error.message}`);
    process.exit(1);
  }
}

module.exports = {
  parseArgs,
  run
};

