  }

  console.log('🚀 Starting browser tests...\n');

  const browser = await puppeteer.launch(BROWSER_LAUNCH_OPTIONS);

  const results = [];
  let passed = 0;
  let failed = 0;

  for (let i = 0; i < pages.length; i++) {
