/**
 * @script            provider-openrouter
 * @category          utility
 * @purpose           feature:translation
 * @scope             tools/scripts
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement OpenRouter translation provider — calls OpenRouter API for actual translations
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/scripts/i18n/lib/provider-openrouter.js [flags]
 */
const { chunkArray } = require('./common');

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function assertOpenRouterConfig(config) {
  if (!config || typeof config !== 'object') throw new Error('Missing OpenRouter config');
  const models = config.modelCandidates || [];
  if (!Array.isArray(models) || models.length === 0) {
    throw new Error('OpenRouter modelCandidates must be a non-empty array');
  }
}

function getOpenRouterAuthHeaders(config = {}) {
  const apiKey = process.env.OPENROUTER_API_KEY || '';
  if (!apiKey) {
    throw new Error('OPENROUTER_API_KEY is required');
  }
  const headers = {
    Authorization: `Bearer ${apiKey}`,
    'Content-Type': 'application/json'
  };
  const referer = process.env.OPENROUTER_HTTP_REFERER || process.env.GITHUB_SERVER_URL || '';
  if (referer) headers['HTTP-Referer'] = referer;
  const title = process.env.OPENROUTER_APP_NAME || 'livepeer-docs-i18n';
  if (title) headers['X-Title'] = title;
  return headers;
}

function buildPromptMessages({ language, kind, segments, rules }) {
  const preserveTerms = (rules?.preserveBrandTerms || []).join(', ');
  const system = [
    'You translate documentation text while preserving Markdown/MDX syntax and placeholders.',
    'Return strict JSON only.',
    'Do not translate URLs, routes, code syntax, placeholders, or brand/product names that must be preserved.',
    preserveTerms ? `Preserve these exact terms: ${preserveTerms}` : ''
  ]
    .filter(Boolean)
    .join(' ');

  const userPayload = {
    task: 'translate_segments',
    language,
    kind,
    instructions: [
      'Return a JSON object with key "segments".',
      'segments must be an array of objects with keys: id, text.',
      'Preserve ids exactly and keep segment count unchanged.',
      'Preserve placeholders like __I18N_PH_#__ exactly.'
    ],
    segments: segments.map((segment) => ({ id: segment.id, text: segment.text }))
  };

  return [
    { role: 'system', content: system },
    { role: 'user', content: JSON.stringify(userPayload) }
  ];
}

function parseJsonFromModelContent(content) {
  const raw = String(content || '').trim();
  if (!raw) throw new Error('OpenRouter response content was empty');
  try {
    return JSON.parse(raw);
  } catch (_err) {
    const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
    if (fenced) {
      return JSON.parse(fenced[1]);
    }
    const objectStart = raw.indexOf('{');
    const objectEnd = raw.lastIndexOf('}');
    if (objectStart >= 0 && objectEnd > objectStart) {
      return JSON.parse(raw.slice(objectStart, objectEnd + 1));
    }
    throw new Error('OpenRouter response was not valid JSON');
  }
}

function validateSegmentResponse(payload, requestSegments) {
  const responseSegments = payload?.segments;
  if (!Array.isArray(responseSegments)) {
    throw new Error('OpenRouter JSON response missing segments array');
  }
  if (responseSegments.length !== requestSegments.length) {
    throw new Error(`Segment count mismatch: expected ${requestSegments.length}, received ${responseSegments.length}`);
  }

  const byId = new Map();
  responseSegments.forEach((segment) => {
    byId.set(String(segment?.id), String(segment?.text ?? ''));
  });

  return requestSegments.map((segment) => {
    const key = String(segment.id);
    if (!byId.has(key)) {
      throw new Error(`Missing translated segment id "${key}"`);
    }
    return { id: segment.id, text: byId.get(key) };
  });
}

async function requestCompletion({ config, model, messages }) {
  const controller = new AbortController();
  const timeoutMs = Number(config.requestTimeoutMs) || 60000;
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${config.baseUrl || 'https://openrouter.ai/api/v1'}/chat/completions`, {
      method: 'POST',
      headers: getOpenRouterAuthHeaders(config),
      signal: controller.signal,
      body: JSON.stringify({
        model,
        temperature: Number.isFinite(config.temperature) ? config.temperature : 0.1,
        messages,
        response_format: { type: 'json_object' }
      })
    });

    if (!response.ok) {
      const body = await response.text();
      const error = new Error(`OpenRouter request failed (${response.status}): ${body.slice(0, 500)}`);
      error.status = response.status;
      error.headers =
        response.headers && typeof response.headers.entries === 'function'
          ? Object.fromEntries(response.headers.entries())
          : {};
      throw error;
    }

    const data = await response.json();
    const content = data?.choices?.[0]?.message?.content;
    return { data, content };
  } finally {
    clearTimeout(timer);
  }
}

function parseResetEpochMsFromError(error) {
  if (!error) return 0;
  const headers = error.headers || {};
  const headerReset = Number(headers['x-ratelimit-reset'] || headers['X-RateLimit-Reset'] || 0);
  if (Number.isFinite(headerReset) && headerReset > 0) {
    return headerReset > 1e12 ? headerReset : headerReset * 1000;
  }

  const message = String(error.message || '');
  const headerMatch = message.match(/X-RateLimit-Reset\\?":\\?"?(\d{10,13})"?/i);
  if (headerMatch) {
    const parsed = Number(headerMatch[1]);
    if (Number.isFinite(parsed) && parsed > 0) {
      return parsed > 1e12 ? parsed : parsed * 1000;
    }
  }
  return 0;
}

function getRetryDelayMs(error, attempt) {
  const status = Number(error?.status);
  const baseDelay = Math.min(30000, 2000 * 2 ** Math.max(0, attempt - 1));
  if (status !== 429) return baseDelay;

  const resetEpochMs = parseResetEpochMsFromError(error);
  if (resetEpochMs > 0) {
    const now = Date.now();
    const untilReset = resetEpochMs - now;
    if (untilReset > 0) {
      return Math.min(70000, untilReset + 750);
    }
  }
  return Math.min(60000, Math.max(baseDelay, 10000));
}

function isRetryableError(error) {
  if (!error) return false;
  if (error.name === 'AbortError') return true;
  const status = Number(error.status);
  const message = String(error.message || '');
  if (/OpenRouter response (content was empty|was not valid JSON)/i.test(message)) {
    return true;
  }
  if (/Segment count mismatch|Missing translated segment id/i.test(message)) {
    return true;
  }
  return status === 429 || (status >= 500 && status < 600);
}

function isModelFailoverError(error) {
  if (!error) return false;
  const status = Number(error.status);
  const message = String(error.message || '');
  if (/OpenRouter response (content was empty|was not valid JSON)/i.test(message)) {
    return true;
  }
  if (/Segment count mismatch|Missing translated segment id/i.test(message)) {
    return true;
  }
  if (
    status === 400 &&
    /(Developer instruction is not enabled|INVALID_ARGUMENT|response_format)/i.test(message)
  ) {
    return true;
  }
  // OpenRouter/provider-specific capacity or billing responses can be model/provider dependent.
  return status === 402 || status === 403 || status === 429 || (status >= 500 && status < 600);
}

function createOpenRouterTranslator(providerConfig, translationRules = {}) {
  assertOpenRouterConfig(providerConfig);

/**
 * @script            providers
 * @category          utility
 * @purpose           feature:translation
 * @scope             tools/scripts
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement Provider registry — selects translation provider (OpenRouter or mock) based on configuration
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/scripts/i18n/lib/providers.js [flags]
 */
const { createOpenRouterTranslator } = require('./provider-openrouter');
const { createMockTranslator } = require('./provider-mock');

function createTranslator({ config, providerNameOverride = '' }) {
  const providerConfig = { ...(config.provider || {}) };
  const name = String(providerNameOverride || providerConfig.name || '').trim().toLowerCase();

  if (name === 'mock') {
    return createMockTranslator();
  }
  if (name === 'openrouter' || !name) {
    return createOpenRouterTranslator(providerConfig, config.translationRules || {});
  }

  throw new Error(`Unsupported i18n provider: ${name}`);
}

module.exports = { createTranslator };

#!/usr/bin/env node
/**
 * @script            codex/task-preflight
 * @category          generator
 * @purpose           governance:agent-governance
 * @scope             tools/scripts/codex, .codex/task-contract.yaml, .codex/locks-local
 * @owner             docs
 * @needs             R-R27, R-R30
 * @purpose-statement Codex task preflight — generates task setup files and validates preconditions
 * @pipeline          manual — codex setup tool referenced by .githooks/pre-commit guidance, not auto-executed
 * @usage             node tools/scripts/codex/task-preflight.js [flags]
 */

const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawnSync } = require('child_process');

const DEFAULT_BASE = 'docs-v2';
const DEFAULT_CONTRACT = '.codex/task-contract.yaml';
const LOCK_DIR_REL = '.codex/locks-local';

const REPO_ROOT = getRepoRoot();

function getRepoRoot() {
  const result = spawnSync('git', ['rev-parse', '--show-toplevel'], { encoding: 'utf8' });
  if (result.status === 0 && String(result.stdout || '').trim()) {
    return String(result.stdout || '').trim();
  }
  return process.cwd();
}

function toPosix(value) {
  return String(value || '').split(path.sep).join('/');
}

function slugify(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^-+|-+$/g, '');
}

function runGit(args, options = {}) {
  const result = spawnSync('git', args, { cwd: REPO_ROOT, encoding: 'utf8', ...options });
  if (result.status !== 0) {
    const stderr = String(result.stderr || '').trim();
    const stdout = String(result.stdout || '').trim();
    throw new Error(stderr || stdout || `git ${args.join(' ')} failed`);
  }
  return String(result.stdout || '').trim();
}

function tryRunGit(args) {
  try {
    return runGit(args);
  } catch (_error) {
    return '';
  }
}

function parseArgs(argv) {
  const args = {
    taskId: null,
    slug: '',
    base: DEFAULT_BASE,
    scope: [],
    scopeFile: '',
    owner: `${process.env.USER || 'unknown'}@${os.hostname()}`,
    worktree: '',
    expiresHours: 8,
    contractPath: DEFAULT_CONTRACT,
    dryRun: false
  };

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];

    if (token === '--task') {
      args.taskId = Number(argv[i + 1]);
      i += 1;
      continue;
    }
    if (token.startsWith('--task=')) {
      args.taskId = Number(token.slice('--task='.length));
      continue;
    }
    if (token === '--slug') {
      args.slug = String(argv[i + 1] || '').trim();
      i += 1;
      continue;
    }
    if (token.startsWith('--slug=')) {
      args.slug = token.slice('--slug='.length).trim();
      continue;
    }
    if (token === '--base') {
      args.base = String(argv[i + 1] || '').trim();
      i += 1;
      continue;
    }
    if (token.startsWith('--base=')) {
      args.base = token.slice('--base='.length).trim();
      continue;
    }
    if (token === '--scope') {
      args.scope = String(argv[i + 1] || '')
        .split(',')
        .map((entry) => toPosix(entry.trim()))
        .filter(Boolean);
      i += 1;
      continue;
    }
    if (token.startsWith('--scope=')) {
      args.scope = token
        .slice('--scope='.length)
        .split(',')
        .map((entry) => toPosix(entry.trim()))
        .filter(Boolean);
      continue;
    }
    if (token === '--scope-file') {
      args.scopeFile = String(argv[i + 1] || '').trim();
      i += 1;
      continue;
    }
    if (token.startsWith('--scope-file=')) {
      args.scopeFile = token.slice('--scope-file='.length).trim();
      continue;
    }
    if (token === '--owner') {
      args.owner = String(argv[i + 1] || '').trim();
      i += 1;
      continue;
    }
    if (token.startsWith('--owner=')) {
      args.owner = token.slice('--owner='.length).trim();
      continue;
    }
    if (token === '--worktree') {
      args.worktree = String(argv[i + 1] || '').trim();
      i += 1;
      continue;
    }
    if (token.startsWith('--worktree=')) {
      args.worktree = token.slice('--worktree='.length).trim();
      continue;
    }
    if (token === '--expires-hours') {
      args.expiresHours = Number(argv[i + 1]);
      i += 1;
      continue;
    }
    if (token.startsWith('--expires-hours=')) {
      args.expiresHours = Number(token.slice('--expires-hours='.length));
      continue;
    }
    if (token === '--contract') {
      args.contractPath = String(argv[i + 1] || '').trim();
      i += 1;
      continue;
    }
    if (token.startsWith('--contract=')) {
      args.contractPath = token.slice('--contract='.length).trim();
      continue;
    }
    if (token === '--dry-run') {
      args.dryRun = true;
      continue;
    }
    if (token === '--help' || token === '-h') {
      args.help = true;
      continue;
    }

    throw new Error(`Unknown argument: ${token}`);
  }

  return args;
}

function usage() {
  console.log('Usage: node tools/scripts/codex/task-preflight.js --task <id> --slug <slug> (--scope <a,b,c> | --scope-file <path>) [--base docs-v2] [--worktree <path>] [--dry-run]');
}

function readScopeFromFile(scopeFile) {
  if (!scopeFile) return [];
  const abs = path.resolve(REPO_ROOT, scopeFile);
  if (!fs.existsSync(abs)) {
    throw new Error(`Scope file not found: ${toPosix(path.relative(REPO_ROOT, abs))}`);
  }
  return fs
    .readFileSync(abs, 'utf8')
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith('#'))
    .map((line) => toPosix(line));
}

function writeYamlContract(contractAbs, data) {
  const content = [
    `task_id: ${data.taskId}`,
    `branch: ${data.branch}`,
    `base_branch: ${data.base}`,
    'scope_in:',
    ...data.scope.map((entry) => `  - ${entry}`),
    'scope_out: []',
    'allowed_generated:',
    '  - .codex/pr-body.generated.md',
    'acceptance_checks:',
    `  - node tests/run-pr-checks.js --base-ref ${data.base}`,
    'risk_flags:',
    '  - workflow-governance',
    'follow_up_issues: []',
    ''
  ].join('\n');

  fs.mkdirSync(path.dirname(contractAbs), { recursive: true });

#!/usr/bin/env node
/**
 * @script            docs-index-utils
 * @category          utility
 * @purpose           governance:index-management
 * @scope             tools/lib, tools/scripts, v2
 * @owner             docs
 * @needs             R-R16, R-R17
 * @purpose-statement Shared utilities for docs-index.json generation — path resolution, frontmatter extraction, index merging
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/lib/docs-index-utils.js [flags]
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const yaml = require('js-yaml');

const DOMAIN_RENAME_MAP = {
  '00_home': 'home',
  '010_products': 'solutions',
  '01_about': 'about',
  '02_community': 'community',
  '03_developers': 'developers',
  '04_gateways': 'gateways',
  '05_orchestrators': 'orchestrators',
  '06_lptoken': 'lpt',
  '07_resources': 'resources',
  '09_internal': 'internal',
  deprecated: 'deprecated',
  experimental: 'experimental',
  notes: 'notes'
};

const DOMAIN_REVERSE_MAP = Object.fromEntries(
  Object.entries(DOMAIN_RENAME_MAP).map(([legacy, modern]) => [modern, legacy])
);

const DIFFICULTY_BEGINNER = ['quickstart', 'getting-started', 'overview', 'intro', 'primer'];
const DIFFICULTY_ADVANCED = ['advanced', 'architecture', 'reference', 'api-reference', 'cli', 'sdk'];

function getRepoRoot() {
  try {
    return execSync('git rev-parse --show-toplevel', { encoding: 'utf8' }).trim();
  } catch (_err) {
    return process.cwd();
  }
}

function toPosix(value) {
  return String(value || '').split(path.sep).join('/');
}

function normalizeRel(relPath) {
  return toPosix(relPath).replace(/^\.\//, '').replace(/^\//, '');
}

function normalizeDocPathForUrl(relPath) {
  let normalized = normalizeRel(relPath);
  normalized = normalized.replace(/\.(md|mdx)$/i, '');
  normalized = normalized.replace(/\/index$/i, '');
  normalized = normalized.replace(/\/+$/, '');
  return normalized;
}

function mapLegacyRepoPathToModern(repoRelPath) {
  const normalized = normalizeRel(repoRelPath);
  if (!normalized.startsWith('v2/pages/')) return normalized;
  const rest = normalized.slice('v2/pages/'.length);
  const [legacyDomain, ...tail] = rest.split('/').filter(Boolean);
  const modernDomain = DOMAIN_RENAME_MAP[legacyDomain] || legacyDomain;
  return normalizeRel(path.posix.join('v2', modernDomain, ...tail));
}

function mapModernRepoPathToLegacy(repoRelPath) {
  const normalized = normalizeRel(repoRelPath);
  if (!normalized.startsWith('v2/') || normalized.startsWith('v2/pages/')) return normalized;
  const rest = normalized.slice('v2/'.length);
  const [modernDomain, ...tail] = rest.split('/').filter(Boolean);
  const legacyDomain = DOMAIN_REVERSE_MAP[modernDomain];
  if (!legacyDomain) return normalized;
  return normalizeRel(path.posix.join('v2/pages', legacyDomain, ...tail));
}

function resolveDocPathCandidates(pagePath) {
  const normalized = normalizeRel(pagePath);
  const candidates = [];

  function pushVariants(p) {
    candidates.push(`${p}.mdx`);
    candidates.push(`${p}.md`);
    candidates.push(path.posix.join(p, 'index.mdx'));
    candidates.push(path.posix.join(p, 'index.md'));
  }

  pushVariants(normalized);
  const modern = mapLegacyRepoPathToModern(normalized);
  if (modern !== normalized) pushVariants(modern);
  const legacy = mapModernRepoPathToLegacy(normalized);
  if (legacy !== normalized) pushVariants(legacy);

  return [...new Set(candidates.map((candidate) => normalizeRel(candidate)))];
}

function resolveDocPath(pagePath, repoRoot) {
  const root = repoRoot || getRepoRoot();
  const candidates = resolveDocPathCandidates(pagePath);
  for (const candidate of candidates) {
    const absPath = path.join(root, candidate);
    if (fs.existsSync(absPath) && fs.statSync(absPath).isFile()) {
      return candidate;
    }
  }
  return null;
}

function extractFrontmatter(content) {
  const rawContent = String(content || '');
  const match = rawContent.match(/^---\s*\n([\s\S]*?)\n---\s*\n?/);
  if (!match) {
    return { exists: false, data: null, raw: null, body: rawContent };
  }
  try {
    return {
      exists: true,
      data: yaml.load(match[1]) || {},
      raw: match[1],
      body: rawContent.slice(match[0].length)
    };
  } catch (error) {
    return {
      exists: true,
      data: null,
      raw: match[1],
      error: error.message,
      body: rawContent.slice(match[0].length)
    };
  }
}

function stripCodeFences(lines) {
  const result = [];
  let inFence = false;
  let fenceToken = null;
  for (const line of lines) {
    const fenceMatch = line.match(/^(```|~~~)/);
    if (fenceMatch) {
      const token = fenceMatch[1];
      if (!inFence) {
        inFence = true;
        fenceToken = token;
      } else if (token === fenceToken) {
        inFence = false;
        fenceToken = null;
      }
      continue;
    }
    if (!inFence) result.push(line);
  }
  return result;
}

function extractHeadings(body) {
  const lines = stripCodeFences(String(body || '').split('\n'));
  return lines
    .map((line) => line.match(/^(#{1,6})\s+(.+)$/))
    .filter(Boolean)
    .map((match) => ({ level: match[1].length, text: match[2].trim() }));
}

function extractCodeLanguages(content) {
  const lines = String(content || '').split('\n');
  const languages = new Set();
  let inFence = false;
  let fenceToken = null;

  for (const line of lines) {
    const fenceMatch = line.match(/^(\s*)(```|~~~)([^\s]*)/);
    if (fenceMatch) {
      const token = fenceMatch[2];
      const lang = fenceMatch[3] ? fenceMatch[3].trim() : '';
      if (!inFence) {
        inFence = true;
        fenceToken = token;
        if (lang) languages.add(lang);
      } else if (token === fenceToken) {
        inFence = false;
        fenceToken = null;
      }
    }
  }

  return [...languages];
}

function stripForWordCount(body) {
  return String(body || '')
    .replace(/^import\s.+$/gm, ' ')
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/~~~[\s\S]*?~~~/g, ' ')
    .replace(/`[^`]+`/g, ' ')
    .replace(/\{\/\*[\s\S]*?\*\/\}/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\[[^\]]+\]\([^)]+\)/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function countWords(text) {
  return String(text || '')
    .split(/\s+/)
    .filter(Boolean).length;
}

function buildGitLastModifiedMap(repoRoot) {
  const root = repoRoot || getRepoRoot();
  const trackedRoots = ['v2/', 'docs-guide/', 'contribute/'];
  try {
    const output = execSync('git log --name-only --format=%cI -- v2 docs-guide contribute', {
