/**
 * @script            generated-file-banners
 * @category          utility
 * @purpose           governance:index-management
 * @scope             full-repo
 * @owner             docs
 * @needs             R-R16, R-R17
 * @purpose-statement Generated file banner template — provides standard banner text for auto-generated files
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/lib/generated-file-banners.js [flags]
 */
const GENERATED_HIDDEN_MARKER = 'generated-file-banner:v1';

function normalizeInline(value) {
  return String(value || '')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function escapeYamlSingle(value) {
  return String(value || '').replace(/'/g, "''");
}

function asQuotedYaml(value) {
  return `'${escapeYamlSingle(value)}'`;
}

function parseFrontmatter(content) {
  const raw = String(content || '');
  if (!raw.startsWith('---')) {
    return {
      hasFrontmatter: false,
      frontmatter: '',
      body: raw
    };
  }

  const lineBreak = raw.includes('\r\n') ? '\r\n' : '\n';
  const marker = `${lineBreak}---`;
  const markerIndex = raw.indexOf(marker, 3);
  if (markerIndex < 0) {
    return {
      hasFrontmatter: false,
      frontmatter: '',
      body: raw
    };
  }

  const frontmatter = raw.slice(0, markerIndex + marker.length);
  let body = raw.slice(markerIndex + marker.length);
  if (body.startsWith(lineBreak)) body = body.slice(lineBreak.length);

  return {
    hasFrontmatter: true,
    frontmatter,
    body
  };
}

function buildGeneratedFrontmatterLines(options = {}) {
  const title = normalizeInline(options.title);
  const sidebarTitle = normalizeInline(options.sidebarTitle);
  const description = normalizeInline(options.description);
  const pageType = normalizeInline(options.pageType);
  const keywords = Array.isArray(options.keywords) ? options.keywords.map((item) => normalizeInline(item)).filter(Boolean) : [];
  const keywordsStyle = options.keywordsStyle === 'multiline' ? 'multiline' : 'inline';
  const lines = ['---'];

  if (title) lines.push(`title: ${asQuotedYaml(title)}`);
  if (sidebarTitle) lines.push(`sidebarTitle: ${asQuotedYaml(sidebarTitle)}`);
  if (description) lines.push(`description: ${asQuotedYaml(description)}`);
  if (pageType) lines.push(`pageType: ${pageType}`);

  if (keywords.length > 0) {
    if (keywordsStyle === 'multiline') {
      lines.push('keywords:');
      lines.push('  [');
      keywords.forEach((keyword) => {
        lines.push(`    ${asQuotedYaml(keyword)},`);
      });
      lines.push('  ]');
    } else {
      lines.push(`keywords: [${keywords.map((keyword) => asQuotedYaml(keyword)).join(', ')}]`);
    }
  }

  lines.push('---');
  return lines;
}

function buildGeneratedHiddenBannerLines(details = {}) {
  const marker = normalizeInline(details.marker) || GENERATED_HIDDEN_MARKER;
  return [
    '{/*',
    `generated-file-banner: ${marker}`,
    `Generation Script: ${normalizeInline(details.script)}`,
    `Purpose: ${normalizeInline(details.purpose)}`,
    `Run when: ${normalizeInline(details.runWhen)}`,
    `Run command: ${normalizeInline(details.runCommand)}`,
    '*/}'
  ];
}

function buildGeneratedNoteLines(details = {}) {
  return [
    '<Note>',
    `**Generation Script**: This file is generated from script(s): \`${normalizeInline(details.script)}\`. <br/>`,
    `**Purpose**: ${normalizeInline(details.purpose)} <br/>`,
    `**Run when**: ${normalizeInline(details.runWhen)} <br/>`,
    `**Important**: Do not manually edit this file; run \`${normalizeInline(details.runCommand)}\`. <br/>`,
    '</Note>'
  ];
}

function parseGeneratedHiddenBanner(content) {
  const parsed = parseFrontmatter(content);
  const body = String(parsed.body || '');
  const commentRe = /\{\/\*([\s\S]*?)\*\/\}/g;
  let match;
  while ((match = commentRe.exec(body)) !== null) {
    const lines = match[1]
      .split('\n')
      .map((line) => line.trim())
      .filter(Boolean);
    const map = new Map();
    lines.forEach((line) => {
      const idx = line.indexOf(':');
      if (idx < 0) return;
      const key = line.slice(0, idx).trim().toLowerCase();
      const value = line.slice(idx + 1).trim();
      map.set(key, value);
    });

    if (!map.has('generated-file-banner')) continue;

    return {
      found: true,
      marker: map.get('generated-file-banner') || '',
      script: map.get('generation script') || '',
      purpose: map.get('purpose') || '',
      runWhen: map.get('run when') || '',
      runCommand: map.get('run command') || '',
      raw: match[0]
    };
  }

  return {
    found: false,
    marker: '',
    script: '',
    purpose: '',
    runWhen: '',
    runCommand: '',
    raw: ''
  };
}

function hasGeneratedNote(content) {
  return /<Note>[\s\S]*?\*\*Generation Script\*\*:[\s\S]*?<\/Note>/m.test(String(content || ''));
}

function extractGeneratedNote(content) {
  const match = String(content || '').match(/<Note>[\s\S]*?\*\*Generation Script\*\*:[\s\S]*?<\/Note>/m);
  return match ? match[0] : '';
}

function removeGeneratedNotes(content) {
  return String(content || '').replace(/<Note>[\s\S]*?\*\*Generation Script\*\*:[\s\S]*?<\/Note>\s*/gm, '');
}

function hasFrontmatterKey(content, key) {
  const parsed = parseFrontmatter(content);
  if (!parsed.hasFrontmatter) return false;
  const re = new RegExp(`^\\s*${key}\\s*:`, 'm');
  return re.test(parsed.frontmatter);
}

module.exports = {
  GENERATED_HIDDEN_MARKER,
  buildGeneratedFrontmatterLines,
  buildGeneratedHiddenBannerLines,
  buildGeneratedNoteLines,
  parseFrontmatter,
  parseGeneratedHiddenBanner,
  hasGeneratedNote,
  extractGeneratedNote,
  removeGeneratedNotes,
  hasFrontmatterKey
};

#!/usr/bin/env node
/**
 * @script           generate-component-docs
 * @category         generator
 * @purpose          governance:index-management
 * @scope            generated-output
 * @owner            docs
 * @needs            R-R10
 * @purpose-statement Generates published component library MDX pages from the registry.
 * @pipeline         manual
 * @usage            node tools/scripts/generate-component-docs.js [--template-only] [--category <name>]
 */

const fs = require('fs');
const path = require('path');
const { VALID_CATEGORIES } = require('../lib/component-governance-utils');
const {
  buildGeneratedHiddenBannerLines,
  buildGeneratedNoteLines
} = require('../lib/generated-file-banners');

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const REGISTRY_PATH = path.join(REPO_ROOT, 'docs-guide', 'component-registry.json');
const ENGLISH_OUTPUT_DIR = path.join(
  REPO_ROOT,
  'v2',
  'resources',
  'documentation-guide',
  'component-library'
);
const LOCALE_DIRS = [
  path.join(REPO_ROOT, 'v2', 'es', 'resources', 'documentation-guide', 'component-library'),
  path.join(REPO_ROOT, 'v2', 'fr', 'resources', 'documentation-guide', 'component-library'),
  path.join(REPO_ROOT, 'v2', 'cn', 'resources', 'documentation-guide', 'component-library')
];

const CATEGORY_LABELS = {
  primitives: 'Primitives',
  layout: 'Layout',
  content: 'Content',
  data: 'Data',
  'page-structure': 'Page Structure'
};

const CATEGORY_DESCRIPTIONS = {
  primitives: 'Standalone visual atoms used across authored documentation.',
  layout: 'Containers and arrangements that define spacing, grouping, and page flow.',
  content: 'Renderers for reader-facing media, code, quotations, and structured content.',
  data: 'Components that are coupled to feeds, release data, or other external sources.',
  'page-structure': 'Portal and frame-mode scaffolding components that shape whole sections.'
};

function usage() {
  console.log(
    [
      'Usage: node tools/scripts/generate-component-docs.js [options]',
      '',
      'Options:',
      '  --template-only        Use template prose only (default for this phase)',
      '  --category <name>      Regenerate one category page only',
      '  --help, -h             Show this help message'
    ].join('\n')
  );
}

function parseArgs(argv) {
  const args = {
    templateOnly: true,
    category: '',
    help: false
  };

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === '--template-only') {
      args.templateOnly = true;
      continue;
    }
    if (token === '--category') {
      args.category = String(argv[index + 1] || '').trim();
      index += 1;
      continue;
    }
    if (token.startsWith('--category=')) {
      args.category = token.slice('--category='.length).trim();
      continue;
    }
    if (token === '--help' || token === '-h') {
      args.help = true;
      continue;
    }
    throw new Error(`Unknown argument: ${token}`);
  }

  if (args.category && !VALID_CATEGORIES.includes(args.category)) {
    throw new Error(`Unknown category: ${args.category}`);
  }

  return args;
}

function loadRegistry() {
  if (!fs.existsSync(REGISTRY_PATH)) {
    throw new Error('Missing docs-guide/component-registry.json. Run generate-component-registry first.');
  }

  return JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
}

function escapePipes(value) {
  return String(value || '').replace(/\|/g, '\\|');
}

function renderGeneratedNote(scriptPath, runCommand) {
  const details = {
    script: scriptPath,
    purpose: 'Generated component-library MDX pages derived from docs-guide/component-registry.json.',
    runWhen: 'Component governance metadata, registry outputs, or published component-library templates change.',
    runCommand
  };

  return [...buildGeneratedHiddenBannerLines(details), '', ...buildGeneratedNoteLines(details), ''].join('\n');
}

function renderDecisionTree() {
  return [
    '1. Bound to an external data source or automation pipeline? `data/`',
    '2. Only makes sense on frame-mode or portal pages? `page-structure/`',
    '3. Accepts children and arranges them spatially? `layout/`',
    '4. Formats or renders content for the reader? `content/`',
    '5. Otherwise: `primitives/`'
  ].join('\n');
}

function renderPropsTable(params) {
  if (!params.length) {
    return 'No documented props.\n';
  }

  const lines = [
    '| Prop | Type | Required | Default | Description |',
    '| --- | --- | --- | --- | --- |'
  ];

  params.forEach((param) => {
    lines.push(
      `| \`${escapePipes(param.name)}\` | \`${escapePipes(param.type || 'any')}\` | ${
        param.required ? 'Yes' : 'No'
      } | \`${escapePipes(param.defaultValue || '')}\` | ${escapePipes(param.description || '')} |`
    );
  });

  return `${lines.join('\n')}\n`;
}

function renderExample(example) {
  if (!example) return '';
  return ['```jsx', example.trim(), '```', ''].join('\n');
}

function renderUsageSummary(component) {
  if (!component.usedIn.length) {
    return '`@usedIn`: none';
  }

  const preview = component.usedIn.slice(0, 6).map((entry) => `\`${entry}\``).join(', ');
  if (component.usedIn.length <= 6) {
    return `\`@usedIn\`: ${preview}`;
  }

  return `\`@usedIn\`: ${preview}, and ${component.usedIn.length - 6} more page(s)`;
}

function renderComponentSection(component) {
  return [
    `### ${component.name}`,
    '',
    component.description,
    '',
    `- File: \`/${component.file}\``,
    `- Tier: \`${component.tier}\``,
    `- Status: \`${component.status}\``,
    `- Risk: \`${component.breakingChangeRisk}\``,
    `- Decision: \`${component.decision}\``,
