/**
 * @script            mintignore
 * @category          validator
 * @purpose           tooling:dev-tools
 * @scope             tests
 * @owner             docs
 * @needs             E-C6, F-C1
 * @purpose-statement Mintignore utility — reads .mintignore patterns and filters file lists
 * @pipeline          indirect — library module
 * @usage             node tests/utils/mintignore.js [flags]
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const tempRepoCache = new Map();
const trackedTempRepos = new Set();
const GIT_ENV_STRIP_KEYS = ['GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'GIT_PREFIX'];

function getSanitizedGitEnv(overrides = {}) {
  const env = { ...process.env, ...overrides };
  GIT_ENV_STRIP_KEYS.forEach((key) => {
    delete env[key];
  });
  return env;
}

function toPosix(filePath) {
  return String(filePath || '').split(path.sep).join('/');
}

function getRepoRoot(rootDir = process.cwd()) {
  try {
    return execFileSync('git', ['rev-parse', '--show-toplevel'], {
      cwd: rootDir,
      encoding: 'utf8',
      env: getSanitizedGitEnv()
    }).trim();
  } catch (_error) {
    return rootDir;
  }
}

function normalizeRepoRelativePath(filePath, repoRoot) {
  if (!filePath) return '';
  const raw = String(filePath).trim();
  if (!raw) return '';

  const absolutePath = path.isAbsolute(raw)
    ? path.resolve(raw)
    : path.resolve(repoRoot, raw);

  let rel = toPosix(path.relative(repoRoot, absolutePath));
  if (!rel) return '';
  rel = rel.replace(/^\.\//, '');
  rel = rel.replace(/^\/+/, '');
  return rel;
}

function getMintIgnorePath(rootDir = null) {
  const repoRoot = getRepoRoot(rootDir || process.cwd());
  const mintIgnorePath = path.join(repoRoot, '.mintignore');
  return fs.existsSync(mintIgnorePath) ? mintIgnorePath : '';
}

function ensureTempGitRepo(repoRoot) {
  const cached = tempRepoCache.get(repoRoot);
  if (cached && fs.existsSync(cached)) {
    return cached;
  }

  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'mintignore-check-'));
  execFileSync('git', ['init', '-q'], { cwd: tempDir, env: getSanitizedGitEnv() });
  tempRepoCache.set(repoRoot, tempDir);
  trackedTempRepos.add(tempDir);
  return tempDir;
}

function parseCheckIgnoreOutput(output, mintIgnorePath) {
  const ignored = new Set();
  if (!output) return ignored;

  const mintIgnoreAbs = path.resolve(mintIgnorePath);
  const lines = output.split('\n').filter(Boolean);

  lines.forEach((line) => {
    const tabIndex = line.indexOf('\t');
    if (tabIndex < 0) return;

    const meta = line.slice(0, tabIndex);
    const relPath = toPosix(line.slice(tabIndex + 1).trim())
      .replace(/^\.\//, '')
      .replace(/^\/+/, '');

    if (!relPath || meta === '::') return;

    const sourceMatch = meta.match(/^(.*):(\d+):([^\t]*)$/);
    if (!sourceMatch) return;

    const sourceFile = path.resolve(sourceMatch[1]);
    const pattern = String(sourceMatch[3] || '').trim();

    if (sourceFile === mintIgnoreAbs && !pattern.startsWith('!')) {
      ignored.add(relPath);
    } else {
      ignored.delete(relPath);
    }
  });

  return ignored;
}

function listMintIgnoredRepoPaths(paths, options = {}) {
  const { rootDir = null } = options;
  const repoRoot = getRepoRoot(rootDir || process.cwd());
  const mintIgnorePath = getMintIgnorePath(repoRoot);
  if (!mintIgnorePath) return new Set();

  const uniqueRelPaths = [...new Set(
    (paths || [])
      .map((entry) => normalizeRepoRelativePath(entry, repoRoot))
      .filter(Boolean)
  )];

  if (!uniqueRelPaths.length) {
    return new Set();
  }

  try {
    const checkerRepo = ensureTempGitRepo(repoRoot);
    const output = execFileSync(
      'git',
      [
        '-c',
        `core.excludesfile=${mintIgnorePath}`,
        'check-ignore',
        '--verbose',
        '--non-matching',
        '--no-index',
        '--stdin'
      ],
      {
        cwd: checkerRepo,
        encoding: 'utf8',
        input: `${uniqueRelPaths.join('\n')}\n`,
        maxBuffer: 64 * 1024 * 1024,
        env: getSanitizedGitEnv()
      }
    );

    return parseCheckIgnoreOutput(output, mintIgnorePath);
  } catch (_error) {
    return new Set();
  }
}

function filterPathsByMintIgnore(paths, options = {}) {
  const { rootDir = null, respectMintIgnore = true } = options;
  if (!respectMintIgnore) {
    return [...(paths || [])];
  }

  const repoRoot = getRepoRoot(rootDir || process.cwd());
  const rows = (paths || []).map((entry) => ({
    original: entry,
    rel: normalizeRepoRelativePath(entry, repoRoot)
  }));

  const ignored = listMintIgnoredRepoPaths(rows.map((row) => row.rel), {
    rootDir: repoRoot
  });

  return rows
    .filter((row) => !row.rel || !ignored.has(row.rel))
    .map((row) => row.original);
}

process.on('exit', () => {
  trackedTempRepos.forEach((tempDir) => {
    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch (_error) {
      // Best-effort cleanup only.
    }
  });
});

module.exports = {
  toPosix,
  getRepoRoot,
  normalizeRepoRelativePath,
  getMintIgnorePath,
  listMintIgnoredRepoPaths,
  filterPathsByMintIgnore
};

/**
 * @script            1-read-notion-to-csv
 * @category          automation
 * @purpose           tooling:dev-tools
 * @scope             external
 * @owner             docs
 * @needs             node, @notionhq/client, dotenv, NOTION_API_KEY, NOTION_DATABASE_ID
 * @purpose-statement Reads the Notion pages database, filters v2 rows, and writes CSV/JSON exports for downstream sync steps.
 * @pipeline          manual
 * @usage             node tools/notion/1-read-notion-to-csv.js [flags]
 */

require("dotenv").config();
const { Client } = require("@notionhq/client");
const fs = require("fs");

async function readNotionToCSV() {
  const notion = new Client({ auth: process.env.NOTION_API_KEY });
  const databaseId = process.env.NOTION_DATABASE_ID;

  console.log("Fetching all pages from Notion database...");

  const allPages = [];
  let hasMore = true;
  let startCursor = undefined;

  while (hasMore) {
    const response = await notion.databases.query({
      database_id: databaseId,
      start_cursor: startCursor,
    });

    response.results.forEach((page) => {
      const pageName =
        page.properties["Page Name"]?.title?.[0]?.plain_text || "";
      const tabGroup = page.properties["Tab Group"]?.select?.name || "";
      const sectionGroup = page.properties["Section Group"]?.select?.name || "";
      const subGroup = page.properties["Sub Section"]?.select?.name || "";
      const pageStatus =
        page.properties["Page Status"]?.multi_select?.[0]?.plain_text || "";
      const notes = page.properties["Notes"]?.rich_text?.[0]?.plain_text || "";
      const relativePath = page.properties["Relative path URL"]?.url || "";

      // ONLY INCLUDE V2 PAGES
      if (relativePath && relativePath.startsWith("v2/")) {
        allPages.push({
          id: page.id,
          pageName,
          tabGroup,
          sectionGroup,
          subGroup,
          pageStatus,
          notes,
          relativePath,
        });
      }
    });

    hasMore = response.has_more;
    startCursor = response.next_cursor;
    console.log(`Fetched ${allPages.length} pages...`);
  }

  console.log(`\nTotal pages fetched: ${allPages.length}`);

  // Write to CSV
  const csvHeader =
    "ID,Page Name,Tab Group,Section Group,Sub Group,Page Status,Notes,Relative Path URL\n";
  const csvRows = allPages.map(
    (p) =>
      `"${p.id}","${p.pageName}","${p.tabGroup}","${p.sectionGroup}","${p.subGroup}","${p.pageStatus}","${p.notes}","${p.relativePath}"`
  );
  const csvContent = csvHeader + csvRows.join("\n");

  // Create data directory if it doesn't exist
  const dataDir = __dirname + "/data";
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  const outputPath = dataDir + "/notion-read.csv";
  fs.writeFileSync(outputPath, csvContent);
  console.log(`\nCSV exported to: ${outputPath}`);

  // Also write JSON for easier processing
  const jsonPath = dataDir + "/notion-read.json";
  fs.writeFileSync(jsonPath, JSON.stringify(allPages, null, 2));
  console.log(`JSON exported to: ${jsonPath}`);
}

readNotionToCSV().catch(console.error);

