    // Handle string pages (direct page paths)
    if (typeof item === "string") {
      const pageName = path.basename(item, ".mdx");
      const relativePath = item;
      const pageStatus = "Active";
      const notes = "";

      // ONLY INCLUDE V2 PAGES
      // EXCLUDE redirect pages (these are navigation hacks, not real content)
      if (
        relativePath &&
        relativePath.startsWith("v2/") &&
        !relativePath.includes("/redirect")
      ) {
        pages.push({
          pageName,
          tabGroup,
          sectionGroup,
          subGroup,
          pageStatus,
          notes,
          relativePath,
        });
      }
      return;
    }

    // Handle arrays
    if (Array.isArray(item)) {
      item.forEach((subItem) =>
        processItem(subItem, tabGroup, sectionGroup, subGroup, depth)
      );
      return;
    }

    // Handle groups
    if (item.group) {
      // depth 0 = top-level group under anchor (Section Group)
      // depth 1+ = nested group (Sub Group)
      if (depth === 0) {
        // This is a Section Group (top-level)
        const newSectionGroup = item.group;
        if (!sectionGroupColors.has(newSectionGroup)) {
          sectionGroupColors.set(
            newSectionGroup,
            getColorForIndex(sectionGroupColors.size)
          );
        }
        item.pages?.forEach((page) =>
          processItem(page, tabGroup, newSectionGroup, "", depth + 1)
        );
      } else {
        // This is a Sub Group (nested)
        const newSubGroup = item.group;
        item.pages?.forEach((page) =>
          processItem(page, tabGroup, sectionGroup, newSubGroup, depth + 1)
        );
      }
      return;
    }

    // Handle tabs
    if (item.tab) {
      const newTabGroup = item.tab;
      item.anchors?.forEach((anchor) =>
        processItem(anchor, newTabGroup, sectionGroup)
      );
    }

    // Handle anchors
    if (item.anchor) {
      // If anchor has groups, process groups (which will handle pages)
      // Groups under anchors are depth 0 (Section Groups)
      if (item.groups && item.groups.length > 0) {
        item.groups.forEach((group) => processItem(group, tabGroup, "", "", 0));
      } else {
        // Only process pages directly if there are no groups
        item.pages?.forEach((page) => processItem(page, tabGroup, "", "", 0));
      }
    }
  }

  // Navigate through the nested structure
  if (docsJson.navigation?.versions) {
    docsJson.navigation.versions.forEach((version) => {
      if (version.languages) {
        version.languages.forEach((language) => {
          if (language.tabs) {
            language.tabs.forEach((tab) => processItem(tab));
          }
        });
      }
    });
  }

  console.log(`Found ${pages.length} pages`);
  console.log(`Assigned colors to ${sectionGroupColors.size} section groups`);

  // Create data directory if it doesn't exist
  const dataDir = path.join(__dirname, "data");
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  // Write to CSV
  const csvHeader =
    "Page Name,Tab Group,Section Group,Sub Group,Page Status,Notes,Relative Path URL\n";
  const csvRows = pages.map(
    (p) =>
      `"${p.pageName}","${p.tabGroup}","${p.sectionGroup}","${p.subGroup}","${p.pageStatus}","${p.notes}","${p.relativePath}"`
  );
  const csvContent = csvHeader + csvRows.join("\n");

  const csvPath = path.join(dataDir, "docs-read.csv");
  fs.writeFileSync(csvPath, csvContent);
  console.log(`CSV exported to: ${csvPath}`);

  // Write JSON with colors
  const jsonPath = path.join(dataDir, "docs-read.json");
  const jsonData = {
    pages,
    sectionGroupColors: Object.fromEntries(sectionGroupColors),
  };
  fs.writeFileSync(jsonPath, JSON.stringify(jsonData, null, 2));
  console.log(`JSON exported to: ${jsonPath}`);
}

function getColorForIndex(index) {
  const colors = [
    "blue",
    "brown",
    "default",
    "gray",
    "green",
    "orange",
    "pink",
    "purple",
    "red",
    "yellow",
  ];
  return colors[index % colors.length];
}

readDocsToCSV();

/**
 * @script            3-check-duplicates
 * @category          validator
 * @purpose           tooling:dev-tools
 * @scope             external
 * @owner             docs
 * @needs             node
 * @purpose-statement Analyzes the exported Notion snapshot for duplicate page keys and writes JSON and Markdown reports.
 * @pipeline          manual
 * @usage             node tools/notion/3-check-duplicates.js [flags]
 */

const fs = require("fs");
const path = require("path");

function checkDuplicates() {
  console.log("Checking for duplicates in Notion database...\n");

  const notionJsonPath = path.join(__dirname, "data", "notion-read.json");

  if (!fs.existsSync(notionJsonPath)) {
    console.error("ERROR: data/notion-read.json not found!");
    console.error("Please run: node 1-read-notion-to-csv.js first");
    process.exit(1);
  }

  const notionPages = JSON.parse(fs.readFileSync(notionJsonPath, "utf8"));

  console.log(`Total pages in Notion: ${notionPages.length}`);

  // Group by unique key: Page Name + Tab Group + Section Group
  const pageGroups = new Map();

  notionPages.forEach((page) => {
    const uniqueKey = `${page.pageName}|||${page.tabGroup}|||${page.sectionGroup}`;

    if (!pageGroups.has(uniqueKey)) {
      pageGroups.set(uniqueKey, []);
    }
    pageGroups.get(uniqueKey).push(page);
  });

  // Find duplicates
  const duplicates = [];
  pageGroups.forEach((pages, key) => {
    if (pages.length > 1) {
      duplicates.push({ key, pages });
    }
  });

  console.log(`\nUnique page combinations: ${pageGroups.size}`);
  console.log(`Duplicate groups found: ${duplicates.length}\n`);

  if (duplicates.length > 0) {
    // Report duplicates
    console.log("DUPLICATES FOUND:\n");
    duplicates.forEach((dup, index) => {
      const [pageName, tabGroup, sectionGroup] = dup.key.split("|||");
      console.log(
        `${
          index + 1
        }. "${pageName}" | Tab: "${tabGroup}" | Section: "${sectionGroup}"`
      );
      console.log(`   Found ${dup.pages.length} copies:`);
      dup.pages.forEach((page, i) => {
        console.log(`   ${i + 1}. ID: ${page.id} | Path: ${page.relativePath}`);
      });
      console.log();
    });
  } else {
    console.log("✓ No duplicates found!");
  }

  // Create reports directory if it doesn't exist
  const reportsDir = path.join(__dirname, "reports");
  if (!fs.existsSync(reportsDir)) {
    fs.mkdirSync(reportsDir, { recursive: true });
  }

  // Write duplicates report as JSON
  const jsonReportPath = path.join(reportsDir, "duplicates-report.json");
  fs.writeFileSync(jsonReportPath, JSON.stringify(duplicates, null, 2));

  // Write duplicates report as Markdown
  let mdReport = `# Duplicates Report\n\n`;
  mdReport += `**Generated:** ${new Date().toISOString()}\n\n`;
  mdReport += `**Total pages in Notion:** ${notionPages.length}\n`;
  mdReport += `**Unique page combinations:** ${pageGroups.size}\n`;
  mdReport += `**Duplicate groups found:** ${duplicates.length}\n\n`;

  if (duplicates.length === 0) {
    mdReport += `✓ **No duplicates found!**\n`;
  } else {
    mdReport += `## Duplicates Found\n\n`;
    duplicates.forEach((dup, index) => {
      const [pageName, tabGroup, sectionGroup] = dup.key.split("|||");
      mdReport += `### ${index + 1}. "${pageName}"\n\n`;
      mdReport += `- **Tab Group:** "${tabGroup}"\n`;
      mdReport += `- **Section Group:** "${sectionGroup}"\n`;
      mdReport += `- **Copies found:** ${dup.pages.length}\n\n`;
      mdReport += `| # | Notion ID | Relative Path |\n`;
      mdReport += `|---|-----------|---------------|\n`;
      dup.pages.forEach((page, i) => {
        mdReport += `| ${i + 1} | \`${page.id}\` | ${
          page.relativePath || "(empty)"
        } |\n`;
      });
      mdReport += `\n`;
    });
  }

  const mdReportPath = path.join(reportsDir, "Duplicates.md");
  fs.writeFileSync(mdReportPath, mdReport);

  console.log(`\nJSON report saved to: ${jsonReportPath}`);
  console.log(`Markdown report saved to: ${mdReportPath}`);

  if (duplicates.length > 0) {
    console.log(`\nTo remove duplicates, run: node 4-remove-duplicates.js`);
  }
}

checkDuplicates();

/**
 * @script            4-remove-duplicates
 * @category          remediator
 * @purpose           tooling:dev-tools
 * @scope             external
 * @owner             docs
 * @needs             node, @notionhq/client, dotenv, NOTION_API_KEY
 * @purpose-statement Archives duplicate Notion pages from the duplicate report while keeping the first record in each group.
 * @pipeline          manual
 * @usage             node tools/notion/4-remove-duplicates.js [flags]
 */

require("dotenv").config();
const { Client } = require("@notionhq/client");
const fs = require("fs");
const path = require("path");

async function removeDuplicates() {
  const reportPath = path.join(__dirname, "reports", "duplicates-report.json");

  if (!fs.existsSync(reportPath)) {
    console.error("ERROR: reports/duplicates-report.json not found!");
    console.error("Please run: node 3-check-duplicates.js first");
    process.exit(1);
  }

  const duplicates = JSON.parse(fs.readFileSync(reportPath, "utf8"));

  if (duplicates.length === 0) {
    console.log("No duplicates to remove!");
    return;
  }

  console.log(`Found ${duplicates.length} duplicate groups`);
  console.log("Strategy: Keep the FIRST entry, delete the rest\n");

  const notion = new Client({ auth: process.env.NOTION_API_KEY });

  let deletedCount = 0;
  let errorCount = 0;

  for (const dup of duplicates) {
    const [pageName, tabGroup, sectionGroup] = dup.key.split("|||");
    console.log(
      `Processing: "${pageName}" | Tab: "${tabGroup}" | Section: "${sectionGroup}"`
    );
    console.log(`  Keeping: ${dup.pages[0].id}`);

    // Delete all except the first one
    for (let i = 1; i < dup.pages.length; i++) {
      const pageToDelete = dup.pages[i];
      try {
        await notion.pages.update({
          page_id: pageToDelete.id,
          archived: true,
        });
        console.log(`  ✓ Deleted: ${pageToDelete.id}`);
        deletedCount++;
      } catch (error) {
        console.error(
          `  ✗ Failed to delete ${pageToDelete.id}:`,
          error.message
        );
        errorCount++;
      }
    }
    console.log();
  }

  console.log(`\nDeletion complete:`);
  console.log(`  Deleted: ${deletedCount}`);
  console.log(`  Errors: ${errorCount}`);

  // Write cleanup report
  const reportsDir = path.join(__dirname, "reports");
  if (!fs.existsSync(reportsDir)) {
    fs.mkdirSync(reportsDir, { recursive: true });
  }

  const cleanupReport = {
    timestamp: new Date().toISOString(),
    duplicateGroupsProcessed: duplicates.length,
    pagesDeleted: deletedCount,
    errors: errorCount,
  };

  const cleanupReportPath = path.join(reportsDir, "notion-clean.json");
  fs.writeFileSync(cleanupReportPath, JSON.stringify(cleanupReport, null, 2));
  console.log(`\nCleanup report saved to: ${cleanupReportPath}`);
  console.log(`\nRun 'node 1-read-notion-to-csv.js' to verify the cleanup.`);
}

removeDuplicates().catch(console.error);

#!/usr/bin/env bash
# @script            ensure-mint-watcher-patch
# @category          utility
# @purpose           tooling:dev-tools
# @scope             tools/scripts
# @owner             docs
# @needs             E-C6, F-C1
# @purpose-statement Mint watcher patcher — applies patch to fix Mintlify file watcher issues in dev mode
# @pipeline          manual — interactive developer tool, not suited for automated pipelines
# @usage             bash tools/scripts/dev/ensure-mint-watcher-patch.sh [flags]
set -euo pipefail

MODE="apply"
if [ "${1:-}" = "--check" ]; then
    MODE="check"
elif [ "${1:-}" = "--apply" ] || [ "${1:-}" = "" ]; then
    MODE="apply"
elif [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
    cat <<'EOF'
Usage:
  bash tools/scripts/dev/ensure-mint-watcher-patch.sh --check
  bash tools/scripts/dev/ensure-mint-watcher-patch.sh --apply
EOF
    exit 0
else
    echo "Error: Unknown option: $1" >&2
    exit 2
fi

if ! command -v mint >/dev/null 2>&1; then
    echo "Error: mint CLI not found in PATH." >&2
    exit 2
fi

MINT_BIN="$(command -v mint)"
MINT_ENTRY_REALPATH="$(node -e 'const fs=require("fs"); console.log(fs.realpathSync(process.argv[1]));' "$MINT_BIN")"
MINT_ROOT="$(cd "$(dirname "$MINT_ENTRY_REALPATH")" && pwd)"
LISTENER_PATH="$MINT_ROOT/node_modules/@mintlify/previewing/dist/local-preview/listener/index.js"

if [ ! -f "$LISTENER_PATH" ]; then
    echo "Error: Mint listener file not found at: $LISTENER_PATH" >&2
    exit 2
fi

if rg -q "disableGlobbing:\\s*true" "$LISTENER_PATH"; then
    echo "Mint watcher patch present: $LISTENER_PATH"
    exit 0
fi

if [ "$MODE" = "check" ]; then
    echo "Mint watcher patch missing: $LISTENER_PATH" >&2
    exit 1
fi

if ! rg -q "^\\s*ignoreInitial:\\s*true," "$LISTENER_PATH"; then
    echo "Error: Could not find expected watcher option in listener file." >&2
    exit 2
fi

if ! node -e '
const fs = require("fs");
const path = process.argv[1];
const src = fs.readFileSync(path, "utf8");
if (src.includes("disableGlobbing: true")) {
  process.exit(0);
}
const needle = "        ignoreInitial: true,\n";
const injected = "        ignoreInitial: true,\n        disableGlobbing: true,\n";
if (!src.includes(needle)) {
  console.error("Unsupported listener format: ignoreInitial block not found.");
  process.exit(2);
}
const next = src.replace(needle, injected);
if (next === src) {
  console.error("Patch was not applied.");
  process.exit(2);
}
try {
  fs.writeFileSync(path, next, "utf8");
} catch (err) {
  console.error(err && err.message ? err.message : String(err));
  process.exit(3);
}
' "$LISTENER_PATH"; then
    echo "Error: Failed to apply Mint watcher patch at: $LISTENER_PATH" >&2
    exit 3
fi

echo "Mint watcher patch applied: $LISTENER_PATH"
exit 0

