test('validateSegmentResponse preserves ordering by request ids and rejects count mismatch', () => {
  const request = [
    { id: 'b', text: 'beta' },
    { id: 'a', text: 'alpha' }
  ];
  const response = {
    segments: [
      { id: 'a', text: 'A' },
