    const sourceDir = path.join(root, 'source');
    const destDir = path.join(root, 'dest');

    createTemplate(sourceDir, 1, 'drift-skill', 'Detect drift in check mode.');
    const syncResult = runNode(['--source-dir', sourceDir, '--dest', destDir]);
