/**
 * @script            codex-commit
 * @category          generator
 * @purpose           governance:agent-governance
 * @scope             tools/scripts, .githooks, ai-tools/ai-rules
 * @owner             docs
 * @needs             R-R27, R-R30
 * @purpose-statement Codex commit helper — audits codex branch state and generates compliant commit messages
 * @pipeline          manual — interactive developer tool, not suited for automated pipelines
 * @dualmode          dual-mode (document flags)
 * @usage             node tools/scripts/codex-commit.js [flags]
 */

const { spawnSync } = require('child_process')

function parseArgs(argv) {
  const args = {
    message: '',
    noVerify: false,
    humanOverride: '',
    overrideNote: '',
    trailers: [],
  }

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i]
    if (token === '--message') {
      args.message = String(argv[i + 1] || '').trim()
      i += 1
      continue
    }
    if (token.startsWith('--message=')) {
      args.message = token.slice('--message='.length).trim()
      continue
    }
    if (token === '--no-verify') {
      args.noVerify = true
      continue
    }
    if (token === '--human-override') {
      args.humanOverride = String(argv[i + 1] || '')
        .trim()
        .toLowerCase()
      i += 1
      continue
    }
    if (token.startsWith('--human-override=')) {
      args.humanOverride = token
        .slice('--human-override='.length)
        .trim()
        .toLowerCase()
      continue
    }
    if (token === '--override-note') {
      args.overrideNote = String(argv[i + 1] || '').trim()
      i += 1
      continue
    }
    if (token.startsWith('--override-note=')) {
      args.overrideNote = token.slice('--override-note='.length).trim()
      continue
    }
    if (token === '--trailer') {
      args.trailers.push(String(argv[i + 1] || '').trim())
      i += 1
      continue
    }
    if (token.startsWith('--trailer=')) {
      args.trailers.push(token.slice('--trailer='.length).trim())
      continue
    }
    if (token === '--help' || token === '-h') {
      args.help = true
      continue
    }

    throw new Error(`Unknown argument: ${token}`)
  }

  return args
}

function usage() {
  console.log(
    'Usage: node tools/scripts/codex-commit.js --message <text> [--no-verify --human-override true --override-note <text>] [--trailer <k=v>]'
  )
}

function validateArgs(args) {
  if (!args.message) {
    throw new Error('--message is required')
  }

  if (!args.noVerify) {
    return
  }

  if (args.humanOverride !== 'true') {
    throw new Error('--human-override true is required when using --no-verify')
  }

  if (!args.overrideNote) {
    throw new Error('--override-note is required when using --no-verify')
  }

  if (String(process.env.ALLOW_HUMAN_NO_VERIFY || '').trim() !== '1') {
    throw new Error(
      'ALLOW_HUMAN_NO_VERIFY=1 is required for --no-verify override path'
    )
  }
}

function runCommit(args) {
  const gitArgs = ['commit', '-m', args.message]

  if (args.noVerify) {
    gitArgs.push('--no-verify')
    gitArgs.push('--trailer', 'human-override=no-verify')
    gitArgs.push('--trailer', `override-note=${args.overrideNote}`)
  }

  args.trailers.forEach((trailer) => {
    if (!trailer) return
    gitArgs.push('--trailer', trailer)
  })

  const result = spawnSync('git', gitArgs, { stdio: 'inherit' })
  return result.status === 0
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  if (args.help) {
    usage()
    process.exit(0)
  }

  validateArgs(args)
  const ok = runCommit(args)
  if (!ok) {
    process.exit(1)
  }

  if (args.noVerify) {
    console.log('✅ Commit created with audited human no-verify override')
  } else {
    console.log('✅ Commit created')
  }
}

if (require.main === module) {
  try {
    main()
  } catch (error) {
    console.error(`❌ ${error.message}`)
    process.exit(1)
  }
}

#!/usr/bin/env node
/**
 * @script            codex-safe-merge-with-stash
 * @category          utility
 * @purpose           governance:agent-governance
 * @scope             tools/scripts
 * @owner             docs
 * @needs             R-R27, R-R30
 * @purpose-statement Codex merge utility — safely merges branches with stash handling to avoid codex conflicts
 * @pipeline          manual — interactive developer tool, not suited for automated pipelines
 * @usage             node tools/scripts/codex-safe-merge-with-stash.js [flags]
 */

const { spawnSync } = require('child_process');

function parseArgs(argv) {
  const args = {
    target: '',
    stashUntracked: true,
    dryRun: false,
    json: false
  };

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === '--target') {
      args.target = String(argv[i + 1] || '').trim();
      i += 1;
      continue;
    }
    if (token.startsWith('--target=')) {
      args.target = token.slice('--target='.length).trim();
      continue;
    }
    if (token === '--stash-untracked') {
      args.stashUntracked = true;
      continue;
    }
    if (token === '--no-stash-untracked') {
      args.stashUntracked = false;
      continue;
    }
    if (token === '--dry-run') {
      args.dryRun = true;
      continue;
    }
    if (token === '--json') {
      args.json = true;
      continue;
    }
    if (token === '--help' || token === '-h') {
      printUsage();
      process.exit(0);
    }
    throw new Error(`Unknown argument: ${token}`);
  }

  if (!args.target) {
    throw new Error('Missing required --target <branch-or-ref>');
  }

  return args;
}

function printUsage() {
  console.log('Usage: node tools/scripts/codex-safe-merge-with-stash.js --target <branch-or-ref> [--dry-run] [--json]');
}

function runGit(args, options = {}) {
  const res = spawnSync('git', args, {
    encoding: 'utf8',
    ...options
  });
  return {
    status: res.status,
    stdout: String(res.stdout || ''),
    stderr: String(res.stderr || ''),
    ok: res.status === 0
  };
}

function runGitOrThrow(args, options = {}) {
  const res = runGit(args, options);
  if (!res.ok) {
    const detail = (res.stderr || res.stdout).trim() || `git ${args.join(' ')} failed`;
    throw new Error(detail);
  }
  return res.stdout.trim();
}

function hasOriginRemote() {
  const res = runGit(['remote', 'get-url', 'origin']);
  return res.ok;
}

function getStashRefByMessage(marker) {
  const list = runGitOrThrow(['stash', 'list', '--format=%gd|%s']);
  if (!list) return '';
  const line = list
    .split('\n')
    .map((entry) => entry.trim())
    .find((entry) => entry.includes(marker));
  if (!line) return '';
  return line.split('|')[0].trim();
}

function getGitStatusPorcelain() {
  return runGitOrThrow(['status', '--porcelain']);
}

function printResult(result, jsonMode) {
  if (jsonMode) {
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    return;
  }

  const statusIcon = result.passed ? '✅' : '❌';
  console.log(`${statusIcon} ${result.message}`);
  if (result.actions && result.actions.length > 0) {
    result.actions.forEach((action) => console.log(`  - ${action}`));
  }
  if (result.recovery && result.recovery.length > 0) {
    console.log('Recovery steps:');
    result.recovery.forEach((line) => console.log(`  - ${line}`));
  }
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const actions = [];
  const recovery = [];

  try {
    const branch = runGitOrThrow(['rev-parse', '--abbrev-ref', 'HEAD']);
    const dirty = getGitStatusPorcelain().trim().length > 0;
    const marker = `codex-safe-merge:${new Date().toISOString()}:${args.target}`;
    let stashRef = '';

    if (args.dryRun) {
      actions.push(`would evaluate dirty tree on branch ${branch}`);
      if (dirty) {
        actions.push(
          `would run git stash push ${args.stashUntracked ? '-u ' : ''}-m "${marker}"`
        );
      }
      if (hasOriginRemote()) {
        actions.push(`would run git fetch origin ${args.target}`);
      }
      actions.push(`would run git merge --no-edit ${args.target}`);
      if (dirty) {
        actions.push('would run git stash pop <stash-ref> after successful merge');
      }

      printResult(
        {
          passed: true,
          message: 'Dry-run completed.',
          branch,
          target: args.target,
          dirty,
          actions,
          recovery
        },
        args.json
      );
      process.exit(0);
    }

    if (dirty) {
      const stashArgs = ['stash', 'push'];
      if (args.stashUntracked) stashArgs.push('-u');
