function buildRequiredEntries() {
  const required = [
    {
      label: 'AGENTS',
      candidates: ['AGENTS.md', 'ai-tools/ai-rules/AGENTS.md', '.github/AGENTS.md']
    },
    {
      label: 'ASSISTANT',
