 * @needs             E-R1, R-R11
 * @purpose-statement Unit tests for v2-wcag-audit.js — tests individual WCAG rules
 * @pipeline          manual — not yet in pipeline
 * @usage             node tests/unit/v2-wcag-audit.test.js [flags]
 */

const assert = require('assert');
const path = require('path');
const wcag = require('../integration/v2-wcag-audit');
const fileWalker = require('../utils/file-walker');

let errors = [];
let warnings = [];

function runCase(name, fn) {
  try {
    fn();
    console.log(`   ✓ ${name}`);
  } catch (error) {
    errors.push({
      rule: 'v2-wcag-audit unit',
      message: `${name}: ${error.message}`,
      line: 1,
      file: 'tests/unit/v2-wcag-audit.test.js'
    });
  }
}

function runTests() {
  errors = [];
  warnings = [];

  console.log('🧪 v2 WCAG Audit Unit Tests');

  runCase('Excludes x-* paths anywhere under v2', () => {
    assert.strictEqual(fileWalker.isExcludedV2ExperimentalPath('v2/x-pages/a.mdx'), true);
    assert.strictEqual(fileWalker.isExcludedV2ExperimentalPath('v2/about/x-archive/a.mdx'), true);
    assert.strictEqual(fileWalker.isExcludedV2ExperimentalPath('v2/about/livepeer-overview.mdx'), false);
  });

  runCase('Parses WCAG args with defaults and flags', () => {
    const parsed = wcag.parseArgs(['--staged', '--no-fix', '--fail-impact', 'moderate']);
    assert.strictEqual(parsed.mode, 'staged');
    assert.strictEqual(parsed.fix, false);
    assert.strictEqual(parsed.failImpact, 'moderate');
    assert.strictEqual(parsed.respectMintIgnore, true);
    assert.strictEqual(parsed.maxPages, 10);
  });

  runCase('Parses --no-mintignore override', () => {
    const parsed = wcag.parseArgs(['--full', '--no-mintignore']);
    assert.strictEqual(parsed.mode, 'full');
    assert.strictEqual(parsed.respectMintIgnore, false);
  });

  runCase('Files mode does not default-cap browser pages', () => {
    const parsed = wcag.parseArgs(['--files', 'v2/about/livepeer-overview.mdx']);
    assert.strictEqual(parsed.mode, 'files');
    assert.strictEqual(parsed.maxPages, null);
  });

  runCase('Maps legacy and migrated v2 route keys to URL paths', () => {
    assert.strictEqual(wcag.routeKeyToUrlPath('v2/pages/04_gateways/index'), '/v2/04_gateways');
    assert.strictEqual(wcag.routeKeyToUrlPath('v2/about/livepeer-overview'), '/v2/about/livepeer-overview');
  });

  runCase('Supports v2-aware file route key mapping', () => {
    const root = process.cwd();
    const migrated = path.join(root, 'v2', 'about', 'livepeer-overview.mdx');
    const legacy = path.join(root, 'v2', 'x-pages', '00_home', 'home', 'primer.mdx');
    assert.strictEqual(wcag.fileToV2RouteKey(migrated), 'v2/about/livepeer-overview');
    assert.strictEqual(wcag.fileToV2RouteKey(legacy), '');
  });

  runCase('Severity threshold logic blocks expected impacts', () => {
    assert.strictEqual(wcag.severityMeetsThreshold('critical', 'serious'), true);
    assert.strictEqual(wcag.severityMeetsThreshold('serious', 'serious'), true);
    assert.strictEqual(wcag.severityMeetsThreshold('moderate', 'serious'), false);
    assert.strictEqual(wcag.severityMeetsThreshold('minor', 'none'), false);
  });

  runCase('Color contrast is normalized to advisory-only (non-blocking)', () => {
    const normalized = wcag.normalizeAxeViolation({
      id: 'color-contrast',
      impact: 'serious',
      tags: ['wcag2aa']
    });
    assert.strictEqual(normalized.impact, 'none');
    assert.strictEqual(normalized.advisory, true);
    assert.strictEqual(wcag.severityMeetsThreshold(normalized.impact, 'serious'), false);
  });

  runCase('Conservative autofix inserts iframe title, img alt, and icon-link aria-label with line numbers', () => {
    const content = [
      '# Demo',
      '<iframe src="https://www.youtube.com/embed/abc123"></iframe>',
      '<img src="/snippets/assets/media/images/Livepeer%20Stats.png" />',
      '<a href="https://github.com/livepeer"><Icon icon="github" size={20} /></a>'
    ].join('\n');

    const out = wcag.applyConservativeAutofixes(content, 'v2/internal/test.mdx', { fix: true });
    assert.strictEqual(out.changed, true);
    assert.ok(out.content.includes('title="Embedded YouTube video"'));
    assert.ok(out.content.includes('alt="Livepeer Stats"') || out.content.includes('alt="Livepeer Stats.png"') === false);
    assert.ok(out.content.includes('aria-label='));
    const rules = out.findings.map((f) => f.rule).sort();
    assert.deepStrictEqual(rules, [
      'raw-anchor-missing-accessible-name',
      'raw-iframe-missing-title',
      'raw-img-missing-alt'
    ]);
    const iframeFinding = out.findings.find((f) => f.rule === 'raw-iframe-missing-title');
    const imgFinding = out.findings.find((f) => f.rule === 'raw-img-missing-alt');
    const anchorFinding = out.findings.find((f) => f.rule === 'raw-anchor-missing-accessible-name');
    assert.strictEqual(iframeFinding.line, 2);
    assert.strictEqual(imgFinding.line, 3);
    assert.strictEqual(anchorFinding.line, 4);
    assert.strictEqual(out.autofixes.length, 3);
  });

  runCase('Autofix is idempotent on second pass', () => {
    const content = '<iframe src="https://example.com/embed"></iframe>\n';
    const first = wcag.applyConservativeAutofixes(content, 'v2/internal/one.mdx', { fix: true });
    const second = wcag.applyConservativeAutofixes(first.content, 'v2/internal/one.mdx', { fix: true });
    assert.strictEqual(first.changed, true);
    assert.strictEqual(second.changed, false);
    assert.strictEqual(second.autofixes.length, 0);
    assert.strictEqual(second.findings.length, 0);
  });

  runCase('No-fix mode reports findings without mutating content', () => {
    const content = '<img src="/foo.png" />';
    const out = wcag.applyConservativeAutofixes(content, 'v2/internal/two.mdx', { fix: false });
    assert.strictEqual(out.changed, false);
    assert.strictEqual(out.content, content);
    assert.strictEqual(out.findings.length, 1);
    assert.strictEqual(out.findings[0].fixed, false);
  });

  runCase('Summary/report helpers produce deterministic sorted rule keys and suggestions', () => {
    const results = [
      {
        file: 'v2/b.mdx',
        wcagViolations: [
          { id: 'color-contrast', impact: 'serious', suggestion: 'Fix contrast.' },
          { id: 'image-alt', impact: 'serious', suggestion: 'Add alt.' }
        ],
        bestPracticeViolations: [],
        incomplete: [],
        staticFindings: [],
        autofixes: []
      },
      {
        file: 'v2/a.mdx',
        wcagViolations: [{ id: 'color-contrast', impact: 'serious', suggestion: 'Fix contrast.' }],
        bestPracticeViolations: [],
        incomplete: [],
        staticFindings: [],
        autofixes: []
      }
    ];
    const staticFindings = [
      { rule: 'raw-img-missing-alt', impact: 'serious', fixed: false },
      { rule: 'raw-iframe-missing-title', impact: 'moderate', fixed: true }
    ];
    const summary = wcag.summarizeResults(results, staticFindings, 'serious');
    const keys = Object.keys(summary.byRule);
    assert.deepStrictEqual(keys, [...keys].sort());
    const suggestions = wcag.collectTopSuggestions(summary);
    assert.strictEqual(suggestions[0].rule, 'color-contrast');
    const report = wcag.buildJsonReport({
      args: {
        mode: 'full',
        failImpact: 'serious',
        fix: true,
        maxPages: null,
        report: wcag.DEFAULT_REPORT_MD,
        reportJson: wcag.DEFAULT_REPORT_JSON
      },
      files: [path.join(process.cwd(), 'v2', 'a.mdx')],
      excludedInputs: [],
      browserAuditedCount: 1,
      staticOnlyCount: 0,
      results,
      allStaticFindings: staticFindings,
      summary,
      suggestions,
      baseUrl: 'http://localhost:3000'
    });
    const markdown = wcag.buildMarkdownReport(report);
    assert.ok(markdown.includes('# V2 WCAG Accessibility Audit Report'));
    assert.ok(markdown.includes('color-contrast'));
  });

  return {
    errors,
    warnings,
    passed: errors.length === 0,
    total: 12
  };
}

if (require.main === module) {
  const result = runTests();
  if (result.passed) {
    console.log(`\n✅ v2 WCAG audit unit tests passed (${result.total} cases)`);
    process.exit(0);
  }
  console.error(`\n❌ ${result.errors.length} v2 WCAG audit unit test failure(s)`);
  result.errors.forEach((err) => console.error(`  - ${err.message}`));
  process.exit(1);
}

#!/usr/bin/env node
/**
 * @script            add-pagetype-mechanical
 * @category          remediator
 * @purpose           qa:content-quality
 * @scope             tools/scripts, v2, tasks/reports
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement Mechanically assigns pageType frontmatter to eligible v2 MDX pages.
 * @pipeline          manual — deterministic metadata rollout utility for v2 docs
 * @usage             node tools/scripts/add-pagetype-mechanical.js [flags]
 */

'use strict';

const fs = require('fs');
const path = require('path');
const matter = require('gray-matter');

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const V2_ROOT = path.join(REPO_ROOT, 'v2');
const EXCLUDED_SEGMENTS = new Set(['cn', 'es', 'fr', 'views', 'groups']);
const SUMMARY_TYPES = ['reference', 'landing', 'quickstart', 'glossary', 'overview'];

function toPosix(filePath) {
  return String(filePath || '').split(path.sep).join('/');
}

function detectNewline(content) {
  return String(content || '').includes('\r\n') ? '\r\n' : '\n';
}

function printUsage() {
  console.log('Usage: node tools/scripts/add-pagetype-mechanical.js [--dry-run]');
}

function parseArgs(argv) {
  const args = {
    dryRun: false
  };

  for (const token of argv) {
    if (token === '--dry-run') {
      args.dryRun = true;
      continue;
    }
    if (token === '--help' || token === '-h') {
      printUsage();
      process.exit(0);
    }
    throw new Error(`Unknown argument: ${token}`);
  }

  return args;
}

function isExcluded(relPath) {
  const segments = toPosix(relPath).split('/');
  return segments.some((segment) => EXCLUDED_SEGMENTS.has(segment) || /^x-[^/]+$/i.test(segment));
}

function walkMdxFiles(dirPath, out = []) {
  const entries = fs.readdirSync(dirPath, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dirPath, entry.name);
    const relPath = toPosix(path.relative(REPO_ROOT, fullPath));

    if (isExcluded(relPath)) {
      continue;
    }

    if (entry.isDirectory()) {
      walkMdxFiles(fullPath, out);
      continue;
    }

    if (entry.isFile() && /\.mdx$/i.test(entry.name)) {
      out.push(relPath);
    }
  }

  return out;
}

function extractFrontmatterBlock(content) {
  const match = String(content || '').match(/^---\r?\n([\s\S]*?)\r?\n---(\r?\n|$)/);
  if (!match) {
    return {
      exists: false,
      raw: '',
      full: '',
      body: String(content || '')
    };
  }

  return {
    exists: true,
    raw: match[1],
    full: match[0],
    body: String(content || '').slice(match[0].length)
  };
}

function hasField(frontmatterRaw, fieldName) {
  const pattern = new RegExp(`^${fieldName}\\s*:`, 'm');
  return pattern.test(String(frontmatterRaw || ''));
}

function hasModeFrame(frontmatterRaw) {
  return /^mode:\s*['"]?frame['"]?\s*$/m.test(String(frontmatterRaw || ''));
}

function classifyFile(relPath, frontmatterRaw) {
  const normalized = toPosix(relPath);
  const fileName = path.basename(normalized).toLowerCase();

  if (hasField(frontmatterRaw, 'openapi')) return { type: 'reference', rule: 1 };
  if (hasModeFrame(frontmatterRaw)) return { type: 'landing', rule: 2 };
  if (fileName.includes('portal') || /-hub\.mdx$/i.test(fileName) || /-path\.mdx$/i.test(fileName)) {
    return { type: 'landing', rule: 3 };
  }
  if (normalized.includes('/quickstart/') || fileName === 'quickstart.mdx') {
    return { type: 'quickstart', rule: 4 };
  }
  if (fileName.includes('glossary')) return { type: 'glossary', rule: 5 };
  if (fileName.includes('faq')) return { type: 'reference', rule: 6 };
  if (normalized.includes('/api-reference/') && fileName === 'overview.mdx') {
    return { type: 'overview', rule: 7 };
  }
  if (normalized.includes('/api-reference/') && !hasField(frontmatterRaw, 'openapi') && fileName !== 'overview.mdx') {
    return { type: 'reference', rule: 8 };
  }
  if (fileName === 'overview.mdx' || fileName === 'index.mdx') {
    return { type: 'overview', rule: 9 };
  }
  return { type: '', rule: 10 };
}

function insertPageType(frontmatterRaw, pageType, newline) {
  const lines = String(frontmatterRaw || '').split(/\r?\n/);
  if (lines.some((line) => /^pageType\s*:/.test(line))) {
    return frontmatterRaw;
  }

  let insertAfterIndex = lines.findIndex((line) => /^description\s*:/.test(line));
  if (insertAfterIndex === -1) {
    insertAfterIndex = lines.findIndex((line) => /^title\s*:/.test(line));
  }
  if (insertAfterIndex === -1) {
    insertAfterIndex = lines.findIndex((line) => String(line || '').trim() !== '');
  }

  const insertAt = insertAfterIndex === -1 ? lines.length : getInsertionIndex(lines, insertAfterIndex);
  lines.splice(insertAt, 0, `pageType: ${pageType}`);
  return lines.join(newline);
}

function getInsertionIndex(lines, keyIndex) {
  const currentLine = String(lines[keyIndex] || '');
  const indentMatch = currentLine.match(/^(\s*)/);
  const baseIndent = indentMatch ? indentMatch[1].length : 0;
  const valueMatch = currentLine.match(/^[^:]+:\s*(.*)$/);
  const value = valueMatch ? valueMatch[1].trim() : '';
  const startsBlock = value === '' || value.startsWith('|') || value.startsWith('>');

  if (!startsBlock) {
    return keyIndex + 1;
  }

  let cursor = keyIndex;
  while (cursor + 1 < lines.length) {
    const nextLine = String(lines[cursor + 1] || '');
    const trimmed = nextLine.trim();
    if (!trimmed) {
      cursor += 1;
      continue;
    }

    const nextIndentMatch = nextLine.match(/^(\s*)/);
    const nextIndent = nextIndentMatch ? nextIndentMatch[1].length : 0;
    if (nextIndent > baseIndent) {
      cursor += 1;
      continue;
    }

    break;
  }

  return cursor + 1;
}

function buildUpdatedContent(content, pageType) {
  const newline = detectNewline(content);
  const frontmatter = extractFrontmatterBlock(content);
  if (!frontmatter.exists) {
    return '';
  }

  const nextFrontmatter = insertPageType(frontmatter.raw, pageType, newline);
  return `---${newline}${nextFrontmatter}${newline}---${newline}${frontmatter.body}`;
}

function validateUpdatedFrontmatter(content, relPath) {
  try {
    matter(content);
  } catch (error) {
    throw new Error(`${relPath}: invalid frontmatter after pageType insertion: ${error.message}`);
  }
}

function writeOperations(operations) {
  operations.forEach((operation) => {
    fs.writeFileSync(operation.absPath, operation.content, 'utf8');
  });
}

function printSummary(summary) {
  console.log('Phase 1 classification complete:');
  console.log(`  reference: ${summary.reference}`);
  console.log(`  landing: ${summary.landing}`);

#!/usr/bin/env node
/**
 * @script            assign-purpose-metadata
 * @category          generator
 * @purpose           qa:content-quality
 * @scope             tools/scripts, tools/lib/docs-usefulness, tools/config, v2
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement Purpose metadata assigner — fills purpose and audience frontmatter for routable v2 pages
 * @pipeline          manual — interactive developer tool, not suited for automated pipelines
 * @usage             node tools/scripts/assign-purpose-metadata.js [flags]
 */

'use strict';

const fs = require('fs');
const path = require('path');
const matter = require('gray-matter');
const { execSync } = require('child_process');
const {
  getDocsJsonRouteKeys,
  toDocsRouteKeyFromFileV2Aware,
  getV2DocsFiles
} = require('../../tests/utils/file-walker');
const {
  audienceTokensFromRaw,
  loadAudienceNormalization,
  loadLlmTiers,
  AUDIENCE_ENUM,
  PURPOSE_ENUM
} = require('../lib/docs-usefulness/rubric-loader');
const { analyzeMdxPage } = require('../lib/docs-usefulness/scoring');
const prompts = require('../lib/docs-usefulness/prompts');
const { loadAndValidateUsefulnessConfig } = require('../lib/docs-usefulness/config-validator');

const OPENROUTER_URL = 'https://openrouter.ai/api/v1/chat/completions';

function stripFrontmatter(content) {
  return String(content || '').replace(/^---\s*\n[\s\S]*?\n---\s*\n?/, '');
}

function getRepoRoot() {
  try {
    return execSync('git rev-parse --show-toplevel', { encoding: 'utf8' }).trim();
  } catch (_error) {
    return process.cwd();
  }
}

function toPosix(filePath) {
  return String(filePath || '').split(path.sep).join('/');
}

function parseArgs(argv) {
  const args = {
    dryRun: false,
    scope: 'pilot',
    files: [],
    classifyWithLlm: false,
    llmTier: 'free'
  };

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === '--dry-run') {
      args.dryRun = true;
      continue;
    }
    if (token === '--scope') {
      args.scope = String(argv[i + 1] || args.scope).trim();
      i += 1;
      continue;
    }
    if (token === '--files' || token === '--file') {
      const raw = String(argv[i + 1] || '').trim();
      if (raw) {
        raw.split(',').map((part) => part.trim()).filter(Boolean).forEach((file) => args.files.push(file));
      }
      i += 1;
      continue;
    }
    if (token === '--classify-with-llm') {
      args.classifyWithLlm = true;
      continue;
    }
    if (token === '--llm-tier') {
      args.llmTier = String(argv[i + 1] || args.llmTier).trim();
      i += 1;
      continue;
    }
  }

  args.files = [...new Set(args.files)];
  return args;
}

function getAllRoutablePages(repoRoot) {
  const docsRoutes = getDocsJsonRouteKeys(repoRoot);
  const files = getV2DocsFiles({ rootDir: repoRoot, respectMintIgnore: true }).filter((file) => /\.mdx$/i.test(file));
  return files
    .filter((abs) => {
      const key = toDocsRouteKeyFromFileV2Aware(abs, repoRoot);
      return key && docsRoutes.has(key);
    })
    .map((abs) => toPosix(path.relative(repoRoot, abs)))
    .sort((a, b) => a.localeCompare(b));
}

function isPilotFile(relPath) {
  const base = path.basename(relPath, '.mdx').toLowerCase();
  return (
    /portal/.test(base) ||
    /overview/.test(base) ||
    /get-started/.test(base) ||
    /^faq/.test(base) ||
    /troubleshoot/.test(base) ||
    /glossary/.test(base)
  );
}

const PURPOSE_RULES = [
  { test: (p) => /portal/i.test(path.basename(p)), purpose: 'landing', source: 'filename' },
  { test: (p) => /mission-control/i.test(path.basename(p)), purpose: 'landing', source: 'filename' },
  { test: (p) => path.basename(p) === 'index.mdx', purpose: 'landing', source: 'filename' },
  { test: (p) => /quickstart/i.test(path.basename(p)), purpose: 'tutorial', source: 'filename' },
  { test: (p) => /get-started/i.test(path.basename(p)), purpose: 'tutorial', source: 'filename' },
  { test: (p) => /primer/i.test(path.basename(p)), purpose: 'tutorial', source: 'filename' },
  { test: (p) => /^first-/i.test(path.basename(p)), purpose: 'tutorial', source: 'filename' },
  { test: (p) => /^faq/i.test(path.basename(p)), purpose: 'faq', source: 'filename' },
  { test: (p) => /troubleshoot/i.test(path.basename(p)), purpose: 'troubleshooting', source: 'filename' },
  { test: (p) => /glossary/i.test(path.basename(p)), purpose: 'glossary', source: 'filename' },
  { test: (p) => /changelog|release-notes/i.test(path.basename(p)), purpose: 'changelog', source: 'filename' },
  { test: (p) => /api-reference|config-flags/i.test(path.basename(p)), purpose: 'reference', source: 'filename' },
  { test: (p) => /overview/i.test(path.basename(p)), purpose: 'overview', source: 'filename' },
  { test: (p) => /\/references?\//i.test(p), purpose: 'reference', source: 'directory' }
];

function inferPurposeByRules(relPath, content) {
  for (const rule of PURPOSE_RULES) {
    if (rule.test(relPath)) {
      return { purpose: rule.purpose, source: rule.source };
    }
  }

  const page = analyzeMdxPage({ content, filePath: relPath, routePath: `/${relPath.replace(/\.mdx$/i, '').replace(/\/index$/i, '')}` });
  const accordionCount = (String(page.content || '').match(/<Accordion(?:Group)?[\s>]/g) || []).length;

  if ((page.components || []).includes('Steps')) {
    return { purpose: 'how_to', source: 'content' };
  }
  if (accordionCount >= 5) {
    return { purpose: 'faq', source: 'content' };
  }
  if ((page.wordCount || 0) < 150 && (page.components || []).some((component) => ['Card', 'CardGroup', 'GotoCard', 'DisplayCard'].includes(component))) {
    return { purpose: 'landing', source: 'content' };
  }
  if ((page.wordCount || 0) > 300 && (page.headings || []).length >= 3 && !(page.components || []).includes('Steps')) {
    return { purpose: 'concept', source: 'content' };
  }

  return { purpose: 'unclassified', source: 'none' };
}

function sectionFromPath(relPath) {
  const parts = String(relPath || '').split('/');
  if (parts[0] === 'v2') return parts[1] || 'unknown';
  return parts[0] || 'unknown';
}

function inferAudience(frontmatterValue, section, normalization) {
  const candidates = audienceTokensFromRaw(frontmatterValue, normalization);
  if (candidates.length > 0) {
    if (candidates.length === 1) {
      return { audience: candidates[0], source: 'frontmatter', candidates };
    }
    const sectionDefault = normalization.section_defaults?.[section];
    if (sectionDefault && candidates.includes(sectionDefault)) {
      return { audience: sectionDefault, source: 'frontmatter', candidates };
    }
    const precedence = normalization.deterministic_precedence || AUDIENCE_ENUM;
    for (const audience of precedence) {
      if (candidates.includes(audience)) {
        return { audience, source: 'frontmatter', candidates };
      }
    }
    return { audience: candidates[0], source: 'frontmatter', candidates };
  }

  return {
    audience: normalization.section_defaults?.[section] || 'everyone',
    source: 'section',
    candidates
  };
}

