function globToRegExp(glob) {
  let pattern = String(glob || '').trim().replace(/^\.?\//, '');
  if (!pattern) return null;

  let out = '^';
  for (let index = 0; index < pattern.length; index += 1) {
    const char = pattern[index];
    const next = pattern[index + 1];

    if (char === '*') {
      if (next === '*') {
        out += '.*';
        index += 1;
      } else {
        out += '[^/]*';
      }
      continue;
    }

    if (char === '?') {
      out += '.';
      continue;
    }

    if ('\\.[]{}()+-^$|'.includes(char)) {
      out += `\\${char}`;
      continue;
    }

    out += char;
  }

  out += '$';
  return new RegExp(out);
