function buildLineStarts(raw) {
  const starts = [0];
  for (let i = 0; i < raw.length; i += 1) {
    if (raw[i] === '\n') {
      starts.push(i + 1);
    }
  }
  return starts;
}

function getLineNumber(lineStarts, offset) {
  let low = 0;
  let high = lineStarts.length - 1;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (lineStarts[mid] <= offset) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return high + 1;
}

function collectProseBlocks(node, bodyStartOffset, out = []) {
  if (!node || typeof node !== 'object') return out;

  if (PROSE_BLOCK_TYPES.has(node.type)) {
    const block = buildVisibleBlock(node, bodyStartOffset);
    if (block && block.text.trim()) {
      out.push(block);
    }
    return out;
  }

  if (Array.isArray(node.children)) {
    node.children.forEach((child) => collectProseBlocks(child, bodyStartOffset, out));
  }

  return out;

#!/usr/bin/env node
/**
 * @script            wcag-repair-common
 * @category          remediator
 * @purpose           qa:content-quality
 * @scope             tools/scripts, tests/integration, tasks/reports, v2
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement WCAG repair shared logic — common repair functions used by WCAG audit fix mode
 * @pipeline          manual — interactive developer tool, not suited for automated pipelines
 * @usage             node tools/scripts/wcag-repair-common.js [flags]
 */

const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const DEFAULT_REPORT_MD = path.join(REPO_ROOT, 'tasks', 'reports', 'quality-accessibility', 'v2-wcag-repair-common-report.md');
const DEFAULT_REPORT_JSON = path.join(REPO_ROOT, 'tasks', 'reports', 'quality-accessibility', 'v2-wcag-repair-common-report.json');

function parseWrapperArgs(argv) {
  const passThrough = [];
  let reportProvided = false;
  let reportJsonProvided = false;
  let modeSet = false;

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === '--help' || token === '-h') {
      return { help: true, argv: [] };
    }
    if (token === '--full' || token === '--staged') {
      modeSet = true;
      passThrough.push(token);
      continue;
    }
    if (token === '--files' || token === '--file') {
      passThrough.push(token);
      if (i + 1 < argv.length) {
        passThrough.push(argv[i + 1]);
        i += 1;
      }
      continue;
    }
    if (token === '--report') {
      reportProvided = true;
      passThrough.push(token);
      if (i + 1 < argv.length) {
        passThrough.push(argv[i + 1]);
        i += 1;
      }
      continue;
    }
    if (token === '--report-json') {
      reportJsonProvided = true;
      passThrough.push(token);
      if (i + 1 < argv.length) {
        passThrough.push(argv[i + 1]);
        i += 1;
      }
      continue;
    }
    // Pass through supported/shared flags transparently.
    passThrough.push(token);
  }

  const out = [];
  if (!modeSet) out.push('--full');
  out.push(...passThrough);

  // Default to applying safe fixes unless the caller explicitly disabled them.
  if (!out.includes('--fix') && !out.includes('--no-fix')) {
    out.push('--fix');
  }

  // Disable browser auditing; this is the common-repair wrapper.
  if (!out.includes('--max-pages')) {
    out.push('--max-pages', '0');
  }

  if (!reportProvided) {
    out.push('--report', DEFAULT_REPORT_MD);
  }
  if (!reportJsonProvided) {
    out.push('--report-json', DEFAULT_REPORT_JSON);
  }

  return { help: false, argv: out };
}

function printHelp() {
  console.log(`Usage: node tools/scripts/wcag-repair-common.js [--full|--staged|--files <path[,path...]>] [--fix|--no-fix] [--stage] [--fail-impact <level>] [--report <path>] [--report-json <path>]`);
  console.log('');
  console.log('Applies conservative WCAG-related source autofixes only (no browser audit) using the shared tests/integration WCAG engine.');
  console.log('Usable via lpd script runner: lpd tools wcag-repair-common -- --staged --stage');
}

async function main() {
  const parsed = parseWrapperArgs(process.argv.slice(2));
  if (parsed.help) {
    printHelp();
    process.exit(0);
  }

  process.chdir(REPO_ROOT);
  const wcagAudit = require(path.join(REPO_ROOT, 'tests', 'integration', 'v2-wcag-audit.js'));
  const result = await wcagAudit.runAudit({ argv: parsed.argv });
  process.exit(result.exitCode || 0);
}

main().catch((error) => {
  console.error(`wcag-repair-common failed: ${error.message}`);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * @script            v2-link-audit.selftest
 * @category          validator
 * @purpose           qa:link-integrity
 * @scope             tests/integration
 * @owner             docs
 * @needs             E-R12, E-R14
 * @purpose-statement Self-test suite for v2-link-audit.js — validates audit logic against known fixtures
 * @pipeline          manual — not yet in pipeline
 * @dualmode          --full (validator) | --write-links (remediator)
 * @usage             node tests/integration/v2-link-audit.selftest.js [flags]
 */

const assert = require('assert');
const fs = require('fs');
const http = require('http');
const path = require('path');
const { execSync } = require('child_process');
const audit = require('./v2-link-audit');

function getRepoRoot() {
  try {
    return execSync('git rev-parse --show-toplevel', { encoding: 'utf8' }).trim();
  } catch (_error) {
    return process.cwd();
  }
}

async function startServer() {
  const server = http.createServer((req, res) => {
    const url = req.url || '/';

    if (url.startsWith('/ok')) {
      res.writeHead(200, { 'content-type': 'text/plain' });
      res.end('ok');
      return;
    }

    if (url.startsWith('/head-fallback')) {
      if (req.method === 'HEAD') {
        res.writeHead(405, { 'content-type': 'text/plain' });
        res.end();
        return;
      }
      res.writeHead(200, { 'content-type': 'text/plain' });
      res.end('fallback-ok');
      return;
    }

    if (url.startsWith('/soft')) {
      res.writeHead(503, { 'content-type': 'text/plain' });
      res.end('soft-fail');
      return;
    }

    if (url.startsWith('/hard')) {
      res.writeHead(404, { 'content-type': 'text/plain' });
      res.end('hard-fail');
      return;
    }

    if (url.startsWith('/media.png')) {
      res.writeHead(200, { 'content-type': 'image/png' });
      res.end('PNG');
      return;
    }

    res.writeHead(500, { 'content-type': 'text/plain' });
    res.end('unexpected route');
  });

  await new Promise((resolve, reject) => {
    server.listen(0, '127.0.0.1', (error) => {
      if (error) reject(error);
      else resolve();
    });
  });

  const addr = server.address();
  const base = `http://127.0.0.1:${addr.port}`;
  return { server, base };
}

async function closeServer(server) {
  if (!server) return;
  await new Promise((resolve) => server.close(() => resolve()));
}

async function run() {
  let server = null;
  let fixtureFile = '';
  const reportMd = '/tmp/v2-link-audit-selftest.md';
  const reportJson = '/tmp/v2-link-audit-selftest.json';

  try {
    const started = await startServer();
    server = started.server;
    const base = started.base;

    const root = getRepoRoot();
    const fixtureDir = path.join(root, 'v2', 'internal', 'reports', 'navigation-links');
    fixtureFile = path.join(fixtureDir, `v2-link-audit-selftest-${Date.now()}.mdx`);
    const relFixture = path.relative(root, fixtureFile).split(path.sep).join('/');

    const content = [
      '# V2 Link Audit Selftest Fixture',
      '',
      `[ok](${base}/ok)`,
      `[head fallback](${base}/head-fallback#anchor)`,
      `[soft](${base}/soft)`,
      `[hard](${base}/hard)`,
      '<a href="https://bad^url">invalid</a>',
      `![media](${base}/media.png)`
    ].join('\n');

    fs.writeFileSync(fixtureFile, `${content}\n`, 'utf8');

    const out = await audit.runAudit({
      argv: [
        '--files', relFixture,
        '--external-policy', 'validate',
        '--external-link-types', 'navigational',
        '--external-timeout-ms', '3000',
        '--external-concurrency', '4',
        '--external-per-host-concurrency', '2',
        '--external-retries', '0',
        '--no-write-links',
        '--report', reportMd,
        '--report-json', reportJson
      ]
    });

    assert.strictEqual(out.exitCode, 0);
    assert.strictEqual(out.externalValidation.eligibleRefCount, 5);
    assert.strictEqual(out.externalValidation.urlClassCounts[audit.EXTERNAL_OK], 2);
    assert.strictEqual(out.externalValidation.urlClassCounts[audit.EXTERNAL_SOFT_FAIL], 1);
    assert.strictEqual(out.externalValidation.urlClassCounts[audit.EXTERNAL_HARD_FAIL], 2);

    const json = JSON.parse(fs.readFileSync(reportJson, 'utf8'));
    const classes = json.external.urlResults.reduce((acc, row) => {
      acc[row.class] = (acc[row.class] || 0) + 1;
      return acc;
    }, {});

    assert.strictEqual(classes[audit.EXTERNAL_OK], 2);
    assert.strictEqual(classes[audit.EXTERNAL_SOFT_FAIL], 1);
    assert.strictEqual(classes[audit.EXTERNAL_HARD_FAIL], 2);

    const fileEntry = json.files.find((item) => item.file === relFixture);
    assert.ok(fileEntry, 'Expected fixture file in JSON report');

    const mediaRef = fileEntry.refs.find((ref) => String(ref.rawPath).includes('/media.png'));
    assert.ok(mediaRef, 'Expected media ref in fixture file refs');
    assert.strictEqual(mediaRef.status, audit.EXTERNAL_UNTESTED);

    console.log('✅ v2-link-audit selftest passed');
    return 0;
  } catch (error) {
    console.error(`❌ v2-link-audit selftest failed: ${error.message}`);
    return 1;
  } finally {
    if (fixtureFile && fs.existsSync(fixtureFile)) {
      fs.unlinkSync(fixtureFile);
    }
    await closeServer(server);
  }
}

if (require.main === module) {
  run().then((code) => process.exit(code));
}

module.exports = { run };

