function getDriveFileId(url) {
  if (!url) return null;
  const patterns = [
    /\/file\/d\/([a-zA-Z0-9_-]+)/,
    /[?&]id=([a-zA-Z0-9_-]+)/,
    /\/uc\?export=download&id=([a-zA-Z0-9_-]+)/
  ];
  for (const p of patterns) {
    const m = String(url).match(p);
    if (m?.[1]) return m[1];
  }
  return null;
}

