 */

const path = require('path');

let puppeteer;
try {
  puppeteer = require('puppeteer');
} catch (_error) {
  puppeteer = require(path.join(process.cwd(), 'tools', 'node_modules', 'puppeteer'));
}
const {
  ensureServerRunning,
  stopServer,
  getServerUrl
} = require('../../.githooks/server-manager');

const DEFAULT_TIMEOUT_MS = 30000;
const SENTINEL_ROUTES = [
  '/v2/home/mission-control',
  '/v2/about/portal',
  '/v2/developers/portal',
  '/v2/gateways/gateways-portal',
  '/v2/resources/documentation-guide/component-library/primitives'
];
const SENTINEL_ROUTE_FILES = new Set([
  'v2/home/mission-control.mdx',
  'v2/about/portal.mdx',
  'v2/developers/portal.mdx',
  'v2/gateways/gateways-portal.mdx',
  'v2/resources/documentation-guide/component-library/primitives.mdx'
]);
const BLOCKING_CONSOLE_PATTERNS = [
  /ReferenceError/i,
  /Cannot access/i,
  /is not defined/i,
  /BlinkingIcon/i,
  /normalizeIconName/i,
  /normalizeIconSize/i
];
const BLOCKING_BODY_PATTERNS = [
  /Failed to render/i,
  /ReferenceError/i,
  /normalizeIconName/i,
  /normalizeIconSize/i
];
const COMPONENT_CHANGE_RE = /^snippets\/components\/.+\.jsx$/;

function toPosix(value) {
  return String(value || '').replace(/\\/g, '/');
}

function usage() {
  console.log(
    [
      'Usage: node tests/integration/mdx-component-runtime-smoke.js [options]',
      '',
      'Options:',
      `  --routes <route[,route]>  Override sentinel routes (default: ${SENTINEL_ROUTES.join(', ')})`,
      '  --base-url <url>          Use an existing Mintlify base URL instead of server-manager discovery',
      '  --help, -h                Show this message'
    ].join('\n')
  );
}

function parseArgs(argv) {
  const args = {
    routes: [],
    baseUrl: String(process.env.MINT_BASE_URL || '').trim(),
    help: false
  };

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--help' || token === '-h') {
      args.help = true;
      continue;
    }

    if (token === '--routes') {
      const raw = String(argv[index + 1] || '').trim();
      if (raw) {
        raw
          .split(',')
          .map((part) => part.trim())
          .filter(Boolean)
          .forEach((route) => args.routes.push(route));
      }
      index += 1;
      continue;
    }

    if (token.startsWith('--routes=')) {
      token
        .slice('--routes='.length)
        .split(',')
        .map((part) => part.trim())
        .filter(Boolean)
        .forEach((route) => args.routes.push(route));
      continue;
    }

    if (token === '--base-url') {
      args.baseUrl = String(argv[index + 1] || '').trim();
      index += 1;
      continue;
    }

    if (token.startsWith('--base-url=')) {
      args.baseUrl = token.slice('--base-url='.length).trim();
      continue;
    }

    throw new Error(`Unknown argument: ${token}`);
  }

  args.routes = [...new Set(args.routes)];
  return args;
}

function normalizeRoute(route) {
  const raw = String(route || '').trim();
  if (!raw) return '';
  return raw.startsWith('/') ? raw : `/${raw}`;
}

function getRoutes(args = {}) {
  const routes = Array.isArray(args.routes) && args.routes.length > 0 ? args.routes : SENTINEL_ROUTES;
  return [...new Set(routes.map(normalizeRoute).filter(Boolean))];
}

function isBlockingConsoleMessage(type, text) {
  if (String(type || '').toLowerCase() !== 'error') return false;
  return BLOCKING_CONSOLE_PATTERNS.some((pattern) => pattern.test(String(text || '')));
}

function isBlockingPageError(message) {
  return BLOCKING_CONSOLE_PATTERNS.some((pattern) => pattern.test(String(message || '')));
}

function classifyDomFailure(snapshot) {
  const status = Number(snapshot?.status || 0);
  const bodyText = String(snapshot?.bodyText || '');
  const bodyLength = Number(snapshot?.bodyLength || 0);

  if (status === 404) {
    return `Route returned HTTP 404`;
  }

  if (snapshot?.is404) {
    return 'Page rendered a 404 state';
  }

  if (snapshot?.hasErrorBoundary) {
    return 'Page rendered an error boundary';
  }

  if (bodyLength < 500) {
    return `Page appears empty or failed to render (${bodyLength} chars)`;
  }

  const blockingBodyPattern = BLOCKING_BODY_PATTERNS.find((pattern) => pattern.test(bodyText));
  if (blockingBodyPattern) {
    return `Page body includes blocking runtime error text (${blockingBodyPattern})`;
  }

  return '';
}

function shouldRunForChangedFiles(changedFiles) {
  return changedFiles.some((filePath) => {
    const relPath = toPosix(filePath);
    return (
      COMPONENT_CHANGE_RE.test(relPath) ||
      relPath === 'tools/scripts/validators/components/check-mdx-component-scope.js' ||
      relPath === 'tests/integration/mdx-component-runtime-smoke.js' ||
      SENTINEL_ROUTE_FILES.has(relPath)
    );
  });
}

async function testRoute(browser, route, baseUrl) {
  const page = await browser.newPage();
  const consoleErrors = [];
  const pageErrors = [];

  await page.setViewport({ width: 1440, height: 900 });

  page.on('console', (msg) => {
    const type = msg.type();
    const text = msg.text();
    if (isBlockingConsoleMessage(type, text)) {
      consoleErrors.push(`Console ${type}: ${text}`);
    }
  });

  page.on('pageerror', (error) => {
    if (isBlockingPageError(error.message)) {
      pageErrors.push(`Page error: ${error.message}`);
    }
  });

  let response;
  try {
    response = await page.goto(`${baseUrl}${route}`, {
      waitUntil: 'networkidle2',
      timeout: DEFAULT_TIMEOUT_MS
    });
    await new Promise((resolve) => setTimeout(resolve, 1500));

#!/usr/bin/env node
/**
 * @script            openapi-reference-audit
 * @category          validator
 * @purpose           tooling:api-spec
 * @scope             tests/integration, v2, api, .github/workflows
 * @owner             docs
 * @needs             F-R17
 * @purpose-statement Comprehensive OpenAPI spec validation — checks references, schemas, examples. Supports --strict (validate), --fix (repair), and report modes.
 * @pipeline          P2, P3, P5, P6
 * @dualmode          --strict (enforcer) | --fix (remediator)
 * @usage             node tests/integration/openapi-reference-audit.js [flags]
 */

const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');
const { execSync } = require('child_process');

const FINDING_TYPES = {
  INVALID_REFERENCE_FORMAT: 'invalid-reference-format',
  MISSING_SPEC_MAPPING: 'missing-spec-mapping',
  SPEC_LOAD_ERROR: 'spec-load-error',
  ENDPOINT_NOT_FOUND: 'endpoint-not-found-in-spec',
  INTRA_FILE_MISMATCH: 'intra-file-openapi-mismatch'
};

const HTTP_METHODS = new Set(['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS', 'TRACE']);

const DEFAULT_REPORT = 'tasks/reports/openapi-reference/openapi-reference-audit.md';
const DEFAULT_REPORT_JSON = 'tasks/reports/openapi-reference/openapi-reference-audit.json';

const SPEC_BY_KEY = {
  studio: 'api/studio.yaml',
  ai: 'api/openapi.yaml',
  cliHttp: 'api/cli-http.yaml'
};

function getRepoRoot() {
  try {
    return execSync('git rev-parse --show-toplevel', { encoding: 'utf8' }).trim();
  } catch (_error) {
    return process.cwd();
  }
}

const REPO_ROOT = getRepoRoot();

function toPosix(value) {
  return String(value || '').split(path.sep).join('/');
}

function relFromRoot(absPath) {
  return toPosix(path.relative(REPO_ROOT, absPath));
}

function isExcludedV2ExperimentalPath(relPath) {
  const rel = toPosix(relPath).replace(/^\/+/, '');
  if (!rel.startsWith('v2/')) return false;
  return rel.split('/').some((segment) => segment.toLowerCase().startsWith('x-'));
}

function walkFiles(dirPath, out = []) {
  if (!fs.existsSync(dirPath)) return out;
  const entries = fs.readdirSync(dirPath, { withFileTypes: true });
  for (const entry of entries) {
    const abs = path.join(dirPath, entry.name);
    const rel = relFromRoot(abs);
    if (entry.isDirectory()) {
      if (entry.name === '.git' || entry.name === 'node_modules') continue;
      if (rel.startsWith('v2/') && isExcludedV2ExperimentalPath(rel)) continue;
      walkFiles(abs, out);
    } else if (/\.(md|mdx)$/i.test(entry.name)) {
      if (rel.startsWith('v2/') && !isExcludedV2ExperimentalPath(rel)) {
        out.push(abs);
      }
    }
  }
  return out;
}

function normalizePath(rawPath) {
  const trimmed = String(rawPath || '').trim();
  if (!trimmed) return '';
  return `/${trimmed.replace(/^\/+/, '')}`;
}

function normalizeMethod(rawMethod) {
  return String(rawMethod || '').trim().toUpperCase();
}

function normalizeEndpoint(method, endpointPath) {
  const normalizedMethod = normalizeMethod(method);
  const normalizedPath = normalizePath(endpointPath);
  if (!HTTP_METHODS.has(normalizedMethod) || !normalizedPath) {
    return null;
  }
  return {
    method: normalizedMethod,
    path: normalizedPath,
    key: `${normalizedMethod} ${normalizedPath}`
  };
}

function parseMethodPathValue(rawValue) {
  const text = String(rawValue || '').trim();
  const match = text.match(/^([A-Za-z]+)\s+(.+)$/);
  if (!match) return null;
  return normalizeEndpoint(match[1], match[2]);
}

function isVersionLiteral(value) {
  return /^\d+\.\d+(?:\.\d+)?$/.test(String(value || '').trim());
}

function isSpecPointer(value) {
  const text = String(value || '').trim().toLowerCase();
  return /\.ya?ml$/.test(text) || /\.json$/.test(text);
}

function isIgnoredFrontmatterOpenapiValue(value) {
  return isVersionLiteral(value) || isSpecPointer(value);
}

function parseArgs(argv) {
  const args = {
    mode: 'full',
    files: [],
    strict: false,
    fix: false,
    write: false,
    report: path.join(REPO_ROOT, DEFAULT_REPORT),
    reportJson: path.join(REPO_ROOT, DEFAULT_REPORT_JSON)
  };

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === '--full') {
      args.mode = 'full';
    } else if (token === '--files' || token === '--file') {
      const raw = String(argv[i + 1] || '').trim();
      if (raw) {
        raw
          .split(',')
          .map((part) => part.trim())
          .filter(Boolean)
          .forEach((part) => args.files.push(part));
      }
      i += 1;
    } else if (token === '--strict') {
      args.strict = true;
    } else if (token === '--fix') {
      args.fix = true;
    } else if (token === '--write') {
      args.write = true;
    } else if (token === '--report') {
      args.report = path.resolve(REPO_ROOT, String(argv[i + 1] || ''));
      i += 1;
    } else if (token === '--report-json') {
      args.reportJson = path.resolve(REPO_ROOT, String(argv[i + 1] || ''));
      i += 1;
    } else {
      throw new Error(`Unknown option: ${token}`);
    }
  }

  args.files = [...new Set(args.files)];
  if (args.files.length > 0) {
    args.mode = 'files';
  }

  if (args.write && !args.fix) {
    throw new Error('--write requires --fix');
  }

  return args;
}

function parseFrontmatter(content) {
  const match = content.match(/^---\s*\n([\s\S]*?)\n---\s*\n?/);
  if (!match) {
    return {
      exists: false,
      raw: '',
      data: null,
      startIndex: -1,
      endIndex: -1,
      lineOffset: 0,
      parseError: null
    };
  }

  let data = null;
  let parseError = null;
  try {
    data = yaml.load(match[1]);
  } catch (error) {
    parseError = error.message;
  }

  const lineOffset = content.slice(0, match.index).split('\n').length - 1;

  return {
    exists: true,
    raw: match[1],
    data,
    startIndex: match.index,
    endIndex: match.index + match[0].length,
    lineOffset,
    parseError
  };
}

function getFrontmatterOpenapiLine(frontmatter) {
  if (!frontmatter.exists) return 1;
  const lines = frontmatter.raw.split('\n');
  const openapiIndex = lines.findIndex((line) => /^\s*openapi\s*:/.test(line));
  if (openapiIndex === -1) return frontmatter.lineOffset + 1;
  return frontmatter.lineOffset + openapiIndex + 2;
}

