const DEFAULT_REPORT_JSON = path.join(REPO_ROOT, 'tasks', 'reports', 'quality-accessibility', 'v2-wcag-audit-report.json');
const DEFAULT_TIMEOUT_MS = 30000;
const DEFAULT_WAIT_AFTER_NAV_MS = 2000;
