function loadI18nTargetLanguages(repoRoot) {
  const configPath = path.join(repoRoot, I18N_CONFIG_REL);
  if (!fs.existsSync(configPath)) return new Set();

  try {
    const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
