/**
 * @script            openapi-rolling-issue.test
 * @category          validator
 * @purpose           tooling:api-spec
 * @scope             tests/unit, tests/utils, .github/workflows/openapi-reference-validation.yml
 * @owner             docs
 * @needs             F-R17
 * @purpose-statement Tests OpenAPI rolling issue tracker — validates issue creation and dedup logic
 * @pipeline          manual — not yet in pipeline
 * @usage             node tests/unit/openapi-rolling-issue.test.js [flags]
 */

const assert = require('assert');
const helpers = require('../utils/openapi-rolling-issue');

let errors = [];

async function runCase(name, fn) {
  try {
    await fn();
    console.log(`   \u001b[32m✓\u001b[0m ${name}`);
  } catch (error) {
    errors.push(`${name}: ${error.message}`);
  }
}

async function runTests() {
  errors = [];

  console.log('🧪 OpenAPI Rolling Issue Unit Tests');

  await runCase('findMarkerIssue dedupes by marker and prefers open issue', async () => {
    const items = [
      { number: 101, state: 'closed', body: 'x <!-- openapi-reference-audit --> x' },
      { number: 102, state: 'open', body: 'x <!-- openapi-reference-audit --> x' },
      { number: 103, state: 'open', body: 'unrelated' }
    ];

    const result = helpers.findMarkerIssue(items);
    assert.ok(result);
    assert.strictEqual(result.number, 102);
  });

  await runCase('getIssueAction returns create vs update for non-zero failures', async () => {
    assert.strictEqual(
      helpers.getIssueAction({ existingIssue: null, totalFailures: 2 }),
      'create'
    );

    assert.strictEqual(
      helpers.getIssueAction({ existingIssue: { number: 10, state: 'open' }, totalFailures: 2 }),
      'update'
    );
  });

  await runCase('getIssueAction returns close when failures become zero and issue is open', async () => {
    assert.strictEqual(
      helpers.getIssueAction({ existingIssue: { number: 22, state: 'open' }, totalFailures: 0 }),
      'close'
    );

    assert.strictEqual(
      helpers.getIssueAction({ existingIssue: null, totalFailures: 0 }),
      'noop'
    );
  });

  await runCase('buildIssueBody includes required headings', async () => {
    const body = helpers.buildIssueBody({
      runUrl: 'https://example.test/run/1',
      topFindings: '- endpoint-not-found-in-spec: v2/foo.mdx:3 (GET /foo)',
      totalFailures: 1,
      totalFiles: 10,
      totalReferences: 20
    });

    const headings = [
      '### Area',
      '### Failing command or workflow',
      '### Script or workflow path',
      '### Full error output',
      '### Reproduction conditions',
      '### Expected behavior',
      '### Action requested from maintainers',
      '### Classification',
      '### Priority'
    ];

    headings.forEach((heading) => assert.ok(body.includes(heading), `missing ${heading}`));
    assert.ok(body.includes(helpers.ROLLING_ISSUE_MARKER));
  });

  await runCase('buildTopFindings enforces deterministic ordering and limit', async () => {
    const findings = [
      { type: 't', file: 'b.mdx', line: 9, reference: 'GET /b', resolvedSpec: 'api/studio.yaml' },
      { type: 't', file: 'a.mdx', line: 10, reference: 'GET /a/2', resolvedSpec: 'api/studio.yaml' },
      { type: 't', file: 'a.mdx', line: 2, reference: 'GET /a/1', resolvedSpec: 'api/studio.yaml' },
      { type: 't', file: 'c.mdx', line: 1, reference: 'GET /c', resolvedSpec: 'api/studio.yaml' }
    ];

    const text = helpers.buildTopFindings(findings, 3);
    const lines = text.split('\n');
    assert.strictEqual(lines.length, 3);
    assert.ok(lines[0].includes('a.mdx:2'));
    assert.ok(lines[1].includes('a.mdx:10'));
    assert.ok(lines[2].includes('b.mdx:9'));
  });

  return {
    errors,
    passed: errors.length === 0,
    total: 5
  };
}

if (require.main === module) {
  runTests()
    .then((result) => {
      if (result.passed) {
        console.log(`\n✅ OpenAPI rolling issue unit tests passed (${result.total} cases)`);
        process.exit(0);
      }
      console.error(`\n❌ ${result.errors.length} OpenAPI rolling issue unit test failure(s)`);
      result.errors.forEach((msg) => console.error(`  - ${msg}`));
      process.exit(1);
    })
    .catch((error) => {
      console.error(`\n❌ OpenAPI rolling issue unit tests crashed: ${error.message}`);
      process.exit(1);
    });
}

module.exports = { runTests };

#!/usr/bin/env node
/**
 * @script            quality.test
 * @category          validator
 * @purpose           qa:content-quality
 * @scope             tests
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement Content quality checks — validates frontmatter completeness, thin content detection, placeholder flagging
 * @pipeline          P1, P3
 * @usage             node tests/unit/quality.test.js [flags]
 */
/**
 * Quality checks: alt text, links, frontmatter, SEO
 */

const path = require('path');
const { getMdxFiles, getStagedDocsPageFiles, readFile } = require('../utils/file-walker');
const { extractFrontmatter } = require('../utils/mdx-parser');

const ENFORCE_OG_IMAGE = process.env.ENFORCE_OG_IMAGE === '1';
const VALID_PAGE_TYPES = ['quickstart', 'tutorial', 'reference', 'conceptual', 'portal', 'api', 'guide', 'overview', 'index'];
const VALID_AUDIENCES = ['developer', 'orchestrator', 'gateway', 'delegator', 'community', 'all'];
const VALID_STATUSES = ['draft', 'published', 'review', 'deprecated'];

let errors = [];
let warnings = [];

function report(severity, file, message, rule = 'Frontmatter') {
  const issue = { file, rule, message };
  if (severity === 'error') {
    errors.push(issue);
    return;
  }
  warnings.push(issue);
}

function collectFilesFromArgs(args) {
  const files = [];

  for (let i = 0; i < args.length; i += 1) {
    const token = args[i];
    if (token === '--files' || token === '--file') {
      const raw = String(args[i + 1] || '').trim();
      if (raw) {
        raw
          .split(',')
          .map((part) => part.trim())
          .filter(Boolean)
          .forEach((part) => {
            files.push(path.isAbsolute(part) ? part : path.resolve(part));
          });
      }
      i += 1;
    }
  }

  return [...new Set(files)];
}

/**
 * Check for image alt text
 */
function checkImageAltText(files) {
  files.forEach(file => {
    const content = readFile(file);
    if (!content) return;

    // Check for img tags without alt
    const imgRegex = /<img[^>]*>/gi;
    const matches = content.match(imgRegex) || [];

    matches.forEach(match => {
      if (!match.includes('alt=') && !match.includes("alt='") && !match.includes('alt="')) {
        errors.push({
          file,
          rule: 'Image alt text',
          message: 'Image tag missing alt attribute',
          tag: match
        });
      }
    });

    // Check for Image component usage (should have alt prop)
    const imageComponentRegex = /<Image[^>]*>/gi;
    const imageMatches = content.match(imageComponentRegex) || [];

    imageMatches.forEach(match => {
      if (!match.includes('alt=') && !match.includes("alt='") && !match.includes('alt="')) {
        warnings.push({
          file,
          rule: 'Image component alt text',
          message: 'Image component should have alt prop',
          tag: match
        });
      }
    });
  });
}

/**
 * Check frontmatter completeness
 */
function checkFrontmatter(files) {
  files.forEach(file => {
    const content = readFile(file);
    if (!content) return;

    const frontmatter = extractFrontmatter(content);

    if (!frontmatter.exists) {
      report('warning', file, 'Missing frontmatter (recommended: title, description)');
      return;
    }

    if (!frontmatter.data) {
      report('error', file, `Invalid frontmatter: ${frontmatter.error || 'parse error'}`);
      return;
    }

    const data = frontmatter.data;

    if (!data.title) {
      report('warning', file, 'Missing title in frontmatter');
    }

    if (!data.description) {
      report('warning', file, 'Missing description in frontmatter (important for SEO)');
    }

    if (ENFORCE_OG_IMAGE && !data['og:image'] && !data.ogImage) {
      report('error', file, 'Missing og:image in frontmatter');
    }

    if (!data.pageType) {
      report('advisory', file, 'Missing pageType field (recommended for audit framework)');
    } else if (!VALID_PAGE_TYPES.includes(data.pageType)) {
      report('advisory', file, `Invalid pageType: "${data.pageType}". Valid: ${VALID_PAGE_TYPES.join(', ')}`);
    }

    if (!data.audience) {
      report('advisory', file, 'Missing audience field (recommended for audit framework)');
    } else if (!VALID_AUDIENCES.includes(data.audience)) {
      report('advisory', file, `Invalid audience: "${data.audience}". Valid: ${VALID_AUDIENCES.join(', ')}`);
    }

    if (!data.status) {
      report('advisory', file, 'Missing status field (recommended for audit framework)');
    } else if (!VALID_STATUSES.includes(data.status)) {
      report('advisory', file, `Invalid status: "${data.status}". Valid: ${VALID_STATUSES.join(', ')}`);
    }

    if (!data.lastVerified) {
      report('advisory', file, 'Missing lastVerified field (recommended for audit framework)');
    } else if (Number.isNaN(Date.parse(data.lastVerified))) {
      report('advisory', file, `Invalid lastVerified date: "${data.lastVerified}"`);
    }

    if (data.title && String(data.title).length > 60) {
      report(
        'warning',
        file,
        `Title may be truncated in search: ${String(data.title).length} chars (recommended max 60)`
      );
    }
  });
}

/**
 * Check for broken internal links (basic)
 */
function checkInternalLinks(files) {
  files.forEach(file => {
    const content = readFile(file);
    if (!content) return;

    // Check for markdown links
    const linkRegex = /\[([^\]]+)\]\(([^)]+)\)/g;
    let match;

    while ((match = linkRegex.exec(content)) !== null) {
      const linkPath = match[2];

      // Skip external links
      if (linkPath.startsWith('http') || linkPath.startsWith('mailto:')) {
        continue;
      }

      // Check for common issues
      if (linkPath.includes('..')) {
        warnings.push({
          file,
          rule: 'Link validation',
          message: `Relative link path: ${linkPath} (consider using absolute path)`,
          link: linkPath
        });
      }
    }
  });
}

/**
 * Run all quality tests
 */
function runTests(options = {}) {
  errors = [];
  warnings = [];

  const { files = null, stagedOnly = false } = options;

  let testFiles = files;
  if (!testFiles) {
    if (stagedOnly) {
      testFiles = getStagedDocsPageFiles().filter(f => f.endsWith('.mdx'));
    } else {
      testFiles = getMdxFiles();
    }
  }

  checkImageAltText(testFiles);

