/**
 * @script            mintignore
 * @category          validator
 * @purpose           tooling:dev-tools
 * @scope             tests
 * @owner             docs
 * @needs             E-C6, F-C1
 * @purpose-statement Mintignore utility — reads .mintignore patterns and filters file lists
 * @pipeline          indirect — library module
 * @usage             node tests/utils/mintignore.js [flags]
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const tempRepoCache = new Map();
const trackedTempRepos = new Set();
const GIT_ENV_STRIP_KEYS = ['GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'GIT_PREFIX'];

function getSanitizedGitEnv(overrides = {}) {
  const env = { ...process.env, ...overrides };
  GIT_ENV_STRIP_KEYS.forEach((key) => {
    delete env[key];
  });
  return env;
}

function toPosix(filePath) {
  return String(filePath || '').split(path.sep).join('/');
}

function getRepoRoot(rootDir = process.cwd()) {
  try {
    return execFileSync('git', ['rev-parse', '--show-toplevel'], {
      cwd: rootDir,
      encoding: 'utf8',
      env: getSanitizedGitEnv()
    }).trim();
  } catch (_error) {
    return rootDir;
  }
}

function normalizeRepoRelativePath(filePath, repoRoot) {
  if (!filePath) return '';
  const raw = String(filePath).trim();
  if (!raw) return '';

  const absolutePath = path.isAbsolute(raw)
    ? path.resolve(raw)
    : path.resolve(repoRoot, raw);

  let rel = toPosix(path.relative(repoRoot, absolutePath));
  if (!rel) return '';
  rel = rel.replace(/^\.\//, '');
  rel = rel.replace(/^\/+/, '');
  return rel;
}

function getMintIgnorePath(rootDir = null) {
  const repoRoot = getRepoRoot(rootDir || process.cwd());
  const mintIgnorePath = path.join(repoRoot, '.mintignore');
  return fs.existsSync(mintIgnorePath) ? mintIgnorePath : '';
}

function ensureTempGitRepo(repoRoot) {
  const cached = tempRepoCache.get(repoRoot);
  if (cached && fs.existsSync(cached)) {
    return cached;
  }

  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'mintignore-check-'));
  execFileSync('git', ['init', '-q'], { cwd: tempDir, env: getSanitizedGitEnv() });
  tempRepoCache.set(repoRoot, tempDir);
  trackedTempRepos.add(tempDir);
  return tempDir;
}

function parseCheckIgnoreOutput(output, mintIgnorePath) {
  const ignored = new Set();
  if (!output) return ignored;

  const mintIgnoreAbs = path.resolve(mintIgnorePath);
  const lines = output.split('\n').filter(Boolean);

  lines.forEach((line) => {
    const tabIndex = line.indexOf('\t');
    if (tabIndex < 0) return;

    const meta = line.slice(0, tabIndex);
    const relPath = toPosix(line.slice(tabIndex + 1).trim())
      .replace(/^\.\//, '')
      .replace(/^\/+/, '');

    if (!relPath || meta === '::') return;

    const sourceMatch = meta.match(/^(.*):(\d+):([^\t]*)$/);
    if (!sourceMatch) return;

    const sourceFile = path.resolve(sourceMatch[1]);
    const pattern = String(sourceMatch[3] || '').trim();

    if (sourceFile === mintIgnoreAbs && !pattern.startsWith('!')) {
      ignored.add(relPath);
    } else {
      ignored.delete(relPath);
    }
  });

  return ignored;
}

function listMintIgnoredRepoPaths(paths, options = {}) {
  const { rootDir = null } = options;
  const repoRoot = getRepoRoot(rootDir || process.cwd());
  const mintIgnorePath = getMintIgnorePath(repoRoot);
  if (!mintIgnorePath) return new Set();

  const uniqueRelPaths = [...new Set(
    (paths || [])
      .map((entry) => normalizeRepoRelativePath(entry, repoRoot))
      .filter(Boolean)
  )];

  if (!uniqueRelPaths.length) {
    return new Set();
  }

  try {
    const checkerRepo = ensureTempGitRepo(repoRoot);
    const output = execFileSync(
      'git',
      [
        '-c',
        `core.excludesfile=${mintIgnorePath}`,
        'check-ignore',
        '--verbose',
        '--non-matching',
        '--no-index',
        '--stdin'
      ],
      {
        cwd: checkerRepo,
        encoding: 'utf8',
        input: `${uniqueRelPaths.join('\n')}\n`,
        maxBuffer: 64 * 1024 * 1024,
        env: getSanitizedGitEnv()
      }
    );

    return parseCheckIgnoreOutput(output, mintIgnorePath);
  } catch (_error) {
    return new Set();
  }
}

function filterPathsByMintIgnore(paths, options = {}) {
  const { rootDir = null, respectMintIgnore = true } = options;
  if (!respectMintIgnore) {
    return [...(paths || [])];
  }

  const repoRoot = getRepoRoot(rootDir || process.cwd());
  const rows = (paths || []).map((entry) => ({
    original: entry,
    rel: normalizeRepoRelativePath(entry, repoRoot)
  }));

  const ignored = listMintIgnoredRepoPaths(rows.map((row) => row.rel), {
    rootDir: repoRoot
  });

  return rows
    .filter((row) => !row.rel || !ignored.has(row.rel))
    .map((row) => row.original);
}

process.on('exit', () => {
  trackedTempRepos.forEach((tempDir) => {
    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch (_error) {
      // Best-effort cleanup only.
    }
  });
});

module.exports = {
  toPosix,
  getRepoRoot,
  normalizeRepoRelativePath,
  getMintIgnorePath,
  listMintIgnoredRepoPaths,
  filterPathsByMintIgnore
};

#!/usr/bin/env node
/**
 * @script            openapi-rolling-issue
 * @category          validator
 * @purpose           tooling:api-spec
 * @scope             tests/utils, tests/unit, .github/workflows/openapi-reference-validation.yml
 * @owner             docs
 * @needs             F-R17
 * @purpose-statement OpenAPI rolling issue utility — creates/updates GitHub issues for persistent OpenAPI audit findings
 * @pipeline          indirect -- library module
 * @usage             node tests/utils/openapi-rolling-issue.js [flags]
 */

const ROLLING_ISSUE_MARKER = '<!-- openapi-reference-audit -->';
const ROLLING_ISSUE_TITLE = '[tooling]: OpenAPI reference validation failures';
const ROLLING_ISSUE_LABELS = ['docs-v2', 'help wanted', 'status: needs-triage', 'type: bug', 'area: ci-cd'];

function compareFindings(a, b) {
  const fileA = String(a?.file || '');
  const fileB = String(b?.file || '');
  if (fileA !== fileB) return fileA.localeCompare(fileB);

  const lineA = Number(a?.line || 0);
  const lineB = Number(b?.line || 0);
  if (lineA !== lineB) return lineA - lineB;

  const typeA = String(a?.type || '');
  const typeB = String(b?.type || '');
  if (typeA !== typeB) return typeA.localeCompare(typeB);

  const refA = String(a?.reference || '');
  const refB = String(b?.reference || '');
  if (refA !== refB) return refA.localeCompare(refB);

  const specA = String(a?.resolvedSpec || '');
  const specB = String(b?.resolvedSpec || '');
  return specA.localeCompare(specB);
}

function formatFindingLine(finding) {
  const ref = finding?.reference ? ` (${finding.reference})` : '';
  const spec = finding?.resolvedSpec ? ` [${finding.resolvedSpec}]` : '';
  return `- ${finding.type}: ${finding.file}:${finding.line}${ref}${spec}`;
}

function buildTopFindings(findings, limit = 30) {
  const safeLimit = Number.isFinite(limit) && limit > 0 ? Math.floor(limit) : 30;
  const sorted = Array.isArray(findings)
    ? findings.slice().sort(compareFindings)
    : [];
  const lines = sorted.slice(0, safeLimit).map(formatFindingLine);
  return lines.length > 0 ? lines.join('\n') : '- none';
}

function findMarkerIssue(items, marker = ROLLING_ISSUE_MARKER) {
  if (!Array.isArray(items) || items.length === 0) return null;

  const matches = items.filter((item) => String(item?.body || '').includes(marker));
  if (matches.length === 0) return null;

  matches.sort((a, b) => {
    const aOpen = a?.state === 'open' ? 1 : 0;
    const bOpen = b?.state === 'open' ? 1 : 0;
    if (aOpen !== bOpen) return bOpen - aOpen;
    return Number(b?.number || 0) - Number(a?.number || 0);
  });

  return matches[0] || null;
}

function buildIssueBody({
  runUrl,
  topFindings,
  totalFailures,
  totalFiles,
  totalReferences,
  marker = ROLLING_ISSUE_MARKER
}) {
  return [
    marker,
    '',
    '### Area',
    'area: ci-cd',
    '',
    '### Failing command or workflow',
    '.github/workflows/openapi-reference-validation.yml',
    '',
    '### Script or workflow path',
    'tests/integration/openapi-reference-audit.js and .github/workflows/openapi-reference-validation.yml',
    '',
    '### Full error output',
    '```text',
    topFindings || '- none',
    '```',
    '',
    '### Reproduction conditions',
    [
      '- Triggered by CI OpenAPI Reference Validation workflow.',
      '- Scope: v2 + locales (`v2/es`, `v2/fr`, `v2/cn`).',
      `- Workflow run: ${runUrl}`
    ].join('\n'),
    '',
    '### Expected behavior',
    'All OpenAPI endpoint references should resolve to the canonical mapped spec and pass strict validation.',
    '',
    '### Action requested from maintainers',
    'Review reported references, apply required content corrections, and re-run the OpenAPI reference audit workflow.',
    '',
    '### Classification',
    'classification: high',
    '',
    '### Priority',
    'priority: high',
    '',
    '### Additional context',
    [
      `- Total failures: ${totalFailures}`,
      `- Files analyzed: ${totalFiles}`,
      `- References analyzed: ${totalReferences}`
    ].join('\n')
  ].join('\n');
}

function buildResolutionComment(runUrl) {
  return [
    'OpenAPI reference validation is passing again.',
    '',
    `Resolved in run: ${runUrl}`
  ].join('\n');
}

function getIssueAction({ existingIssue, totalFailures }) {
  const failures = Number(totalFailures || 0);
  const hasExisting = Boolean(existingIssue);
  const existingOpen = hasExisting && existingIssue.state === 'open';

  if (failures === 0) {
    return existingOpen ? 'close' : 'noop';
  }

  return hasExisting ? 'update' : 'create';
}

module.exports = {
  ROLLING_ISSUE_MARKER,
  ROLLING_ISSUE_TITLE,
  ROLLING_ISSUE_LABELS,
  buildTopFindings,
  findMarkerIssue,
  buildIssueBody,
  buildResolutionComment,
  getIssueAction
};

