  REQUIRED_FRAMEWORK_KEYS,
  SCOPE_ENUM,
  SCRIPT_EXTENSIONS,
  isDiscoveredScriptPath,
  isHookScriptPath,
  isWithinRoots,
  normalizeRepoPath,
  parseDeclaredPipelines,
  shouldExcludeScriptPath
};

/**
 * @script            1-read-notion-to-csv
 * @category          automation
 * @purpose           tooling:dev-tools
 * @scope             external
 * @owner             docs
 * @needs             node, @notionhq/client, dotenv, NOTION_API_KEY, NOTION_DATABASE_ID
 * @purpose-statement Reads the Notion pages database, filters v2 rows, and writes CSV/JSON exports for downstream sync steps.
 * @pipeline          manual
 * @usage             node tools/notion/1-read-notion-to-csv.js [flags]
 */

require("dotenv").config();
const { Client } = require("@notionhq/client");
const fs = require("fs");

async function readNotionToCSV() {
  const notion = new Client({ auth: process.env.NOTION_API_KEY });
  const databaseId = process.env.NOTION_DATABASE_ID;

  console.log("Fetching all pages from Notion database...");

  const allPages = [];
  let hasMore = true;
  let startCursor = undefined;

  while (hasMore) {
    const response = await notion.databases.query({
      database_id: databaseId,
      start_cursor: startCursor,
    });

    response.results.forEach((page) => {
      const pageName =
        page.properties["Page Name"]?.title?.[0]?.plain_text || "";
      const tabGroup = page.properties["Tab Group"]?.select?.name || "";
      const sectionGroup = page.properties["Section Group"]?.select?.name || "";
      const subGroup = page.properties["Sub Section"]?.select?.name || "";
      const pageStatus =
        page.properties["Page Status"]?.multi_select?.[0]?.plain_text || "";
      const notes = page.properties["Notes"]?.rich_text?.[0]?.plain_text || "";
      const relativePath = page.properties["Relative path URL"]?.url || "";

      // ONLY INCLUDE V2 PAGES
      if (relativePath && relativePath.startsWith("v2/")) {
        allPages.push({
          id: page.id,
          pageName,
          tabGroup,
          sectionGroup,
          subGroup,
          pageStatus,
          notes,
          relativePath,
        });
      }
    });

    hasMore = response.has_more;
    startCursor = response.next_cursor;
    console.log(`Fetched ${allPages.length} pages...`);
  }

  console.log(`\nTotal pages fetched: ${allPages.length}`);

  // Write to CSV
  const csvHeader =
    "ID,Page Name,Tab Group,Section Group,Sub Group,Page Status,Notes,Relative Path URL\n";
  const csvRows = allPages.map(
    (p) =>
      `"${p.id}","${p.pageName}","${p.tabGroup}","${p.sectionGroup}","${p.subGroup}","${p.pageStatus}","${p.notes}","${p.relativePath}"`
  );
  const csvContent = csvHeader + csvRows.join("\n");

  // Create data directory if it doesn't exist
  const dataDir = __dirname + "/data";
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  const outputPath = dataDir + "/notion-read.csv";
  fs.writeFileSync(outputPath, csvContent);
  console.log(`\nCSV exported to: ${outputPath}`);

  // Also write JSON for easier processing
  const jsonPath = dataDir + "/notion-read.json";
  fs.writeFileSync(jsonPath, JSON.stringify(allPages, null, 2));
  console.log(`JSON exported to: ${jsonPath}`);
}

readNotionToCSV().catch(console.error);

/**
 * @script            2-read-docs-to-csv
 * @category          generator
 * @purpose           tooling:dev-tools
 * @scope             external
 * @owner             docs
 * @needs             node
 * @purpose-statement Parses docs.json v2 navigation and writes CSV/JSON exports with section-group metadata for Notion sync.
 * @pipeline          manual
 * @usage             node tools/notion/2-read-docs-to-csv.js [flags]
 */

const fs = require("fs");
const path = require("path");

function readDocsToCSV() {
  console.log("Starting docs.json export...");

  const docsJsonPath = path.join(__dirname, "../docs.json");
  console.log(`Reading docs.json from: ${docsJsonPath}`);

  const docsJson = JSON.parse(fs.readFileSync(docsJsonPath, "utf8"));
  console.log("docs.json loaded successfully");

  const pages = [];
  const sectionGroupColors = new Map();

  function processItem(
    item,
    tabGroup = "",
    sectionGroup = "",
    subGroup = "",
    depth = 0
  ) {
    // Handle string pages (direct page paths)
    if (typeof item === "string") {
      const pageName = path.basename(item, ".mdx");
      const relativePath = item;
      const pageStatus = "Active";
      const notes = "";

      // ONLY INCLUDE V2 PAGES
      // EXCLUDE redirect pages (these are navigation hacks, not real content)
      if (
        relativePath &&
        relativePath.startsWith("v2/") &&
        !relativePath.includes("/redirect")
      ) {
        pages.push({
          pageName,
          tabGroup,
          sectionGroup,
          subGroup,
          pageStatus,
          notes,
          relativePath,
        });
      }
      return;
    }

    // Handle arrays
    if (Array.isArray(item)) {
      item.forEach((subItem) =>
        processItem(subItem, tabGroup, sectionGroup, subGroup, depth)
      );
      return;
    }

    // Handle groups
    if (item.group) {
      // depth 0 = top-level group under anchor (Section Group)
      // depth 1+ = nested group (Sub Group)
      if (depth === 0) {
        // This is a Section Group (top-level)
        const newSectionGroup = item.group;
        if (!sectionGroupColors.has(newSectionGroup)) {
          sectionGroupColors.set(
            newSectionGroup,
            getColorForIndex(sectionGroupColors.size)
          );
        }
        item.pages?.forEach((page) =>
          processItem(page, tabGroup, newSectionGroup, "", depth + 1)
        );
      } else {
        // This is a Sub Group (nested)
        const newSubGroup = item.group;
        item.pages?.forEach((page) =>
          processItem(page, tabGroup, sectionGroup, newSubGroup, depth + 1)
        );
      }
      return;
    }

    // Handle tabs
    if (item.tab) {
      const newTabGroup = item.tab;
      item.anchors?.forEach((anchor) =>
        processItem(anchor, newTabGroup, sectionGroup)
      );
    }

    // Handle anchors
    if (item.anchor) {
      // If anchor has groups, process groups (which will handle pages)
      // Groups under anchors are depth 0 (Section Groups)
      if (item.groups && item.groups.length > 0) {
        item.groups.forEach((group) => processItem(group, tabGroup, "", "", 0));
      } else {
        // Only process pages directly if there are no groups
        item.pages?.forEach((page) => processItem(page, tabGroup, "", "", 0));
      }
    }
  }

  // Navigate through the nested structure
  if (docsJson.navigation?.versions) {
    docsJson.navigation.versions.forEach((version) => {
      if (version.languages) {
        version.languages.forEach((language) => {
          if (language.tabs) {
            language.tabs.forEach((tab) => processItem(tab));
          }
        });
      }
    });
  }

  console.log(`Found ${pages.length} pages`);
  console.log(`Assigned colors to ${sectionGroupColors.size} section groups`);

  // Create data directory if it doesn't exist
  const dataDir = path.join(__dirname, "data");
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  // Write to CSV
  const csvHeader =
    "Page Name,Tab Group,Section Group,Sub Group,Page Status,Notes,Relative Path URL\n";
  const csvRows = pages.map(
    (p) =>
      `"${p.pageName}","${p.tabGroup}","${p.sectionGroup}","${p.subGroup}","${p.pageStatus}","${p.notes}","${p.relativePath}"`
  );
  const csvContent = csvHeader + csvRows.join("\n");

  const csvPath = path.join(dataDir, "docs-read.csv");
  fs.writeFileSync(csvPath, csvContent);
  console.log(`CSV exported to: ${csvPath}`);

  // Write JSON with colors
  const jsonPath = path.join(dataDir, "docs-read.json");
  const jsonData = {
    pages,
    sectionGroupColors: Object.fromEntries(sectionGroupColors),
  };
  fs.writeFileSync(jsonPath, JSON.stringify(jsonData, null, 2));
  console.log(`JSON exported to: ${jsonPath}`);
}

function getColorForIndex(index) {
  const colors = [
    "blue",
    "brown",
    "default",
    "gray",
    "green",
    "orange",
    "pink",
    "purple",
    "red",
    "yellow",
  ];
  return colors[index % colors.length];
}

readDocsToCSV();

/**
 * @script            3-check-duplicates
 * @category          validator
 * @purpose           tooling:dev-tools
 * @scope             external
 * @owner             docs
 * @needs             node
 * @purpose-statement Analyzes the exported Notion snapshot for duplicate page keys and writes JSON and Markdown reports.
 * @pipeline          manual
 * @usage             node tools/notion/3-check-duplicates.js [flags]
 */

const fs = require("fs");
const path = require("path");

function checkDuplicates() {
  console.log("Checking for duplicates in Notion database...\n");

  const notionJsonPath = path.join(__dirname, "data", "notion-read.json");

  if (!fs.existsSync(notionJsonPath)) {
    console.error("ERROR: data/notion-read.json not found!");
    console.error("Please run: node 1-read-notion-to-csv.js first");
    process.exit(1);
  }

  const notionPages = JSON.parse(fs.readFileSync(notionJsonPath, "utf8"));

  console.log(`Total pages in Notion: ${notionPages.length}`);

  // Group by unique key: Page Name + Tab Group + Section Group
  const pageGroups = new Map();

  notionPages.forEach((page) => {
    const uniqueKey = `${page.pageName}|||${page.tabGroup}|||${page.sectionGroup}`;

    if (!pageGroups.has(uniqueKey)) {
      pageGroups.set(uniqueKey, []);
    }
    pageGroups.get(uniqueKey).push(page);
  });

  // Find duplicates
  const duplicates = [];
  pageGroups.forEach((pages, key) => {
    if (pages.length > 1) {
      duplicates.push({ key, pages });
    }
  });

  console.log(`\nUnique page combinations: ${pageGroups.size}`);
  console.log(`Duplicate groups found: ${duplicates.length}\n`);

  if (duplicates.length > 0) {
    // Report duplicates
    console.log("DUPLICATES FOUND:\n");
    duplicates.forEach((dup, index) => {
      const [pageName, tabGroup, sectionGroup] = dup.key.split("|||");
      console.log(
        `${
          index + 1
        }. "${pageName}" | Tab: "${tabGroup}" | Section: "${sectionGroup}"`
      );
      console.log(`   Found ${dup.pages.length} copies:`);
      dup.pages.forEach((page, i) => {
        console.log(`   ${i + 1}. ID: ${page.id} | Path: ${page.relativePath}`);
      });
      console.log();
    });
  } else {
    console.log("✓ No duplicates found!");
  }

  // Create reports directory if it doesn't exist
  const reportsDir = path.join(__dirname, "reports");
  if (!fs.existsSync(reportsDir)) {
    fs.mkdirSync(reportsDir, { recursive: true });
  }

  // Write duplicates report as JSON
  const jsonReportPath = path.join(reportsDir, "duplicates-report.json");
  fs.writeFileSync(jsonReportPath, JSON.stringify(duplicates, null, 2));

  // Write duplicates report as Markdown
  let mdReport = `# Duplicates Report\n\n`;
  mdReport += `**Generated:** ${new Date().toISOString()}\n\n`;
  mdReport += `**Total pages in Notion:** ${notionPages.length}\n`;
  mdReport += `**Unique page combinations:** ${pageGroups.size}\n`;
  mdReport += `**Duplicate groups found:** ${duplicates.length}\n\n`;

  if (duplicates.length === 0) {
    mdReport += `✓ **No duplicates found!**\n`;
  } else {
    mdReport += `## Duplicates Found\n\n`;
    duplicates.forEach((dup, index) => {
      const [pageName, tabGroup, sectionGroup] = dup.key.split("|||");
      mdReport += `### ${index + 1}. "${pageName}"\n\n`;
      mdReport += `- **Tab Group:** "${tabGroup}"\n`;
      mdReport += `- **Section Group:** "${sectionGroup}"\n`;
      mdReport += `- **Copies found:** ${dup.pages.length}\n\n`;
      mdReport += `| # | Notion ID | Relative Path |\n`;
      mdReport += `|---|-----------|---------------|\n`;
      dup.pages.forEach((page, i) => {
        mdReport += `| ${i + 1} | \`${page.id}\` | ${
          page.relativePath || "(empty)"
        } |\n`;
      });
      mdReport += `\n`;
    });
  }

  const mdReportPath = path.join(reportsDir, "Duplicates.md");
  fs.writeFileSync(mdReportPath, mdReport);

  console.log(`\nJSON report saved to: ${jsonReportPath}`);
  console.log(`Markdown report saved to: ${mdReportPath}`);

  if (duplicates.length > 0) {
    console.log(`\nTo remove duplicates, run: node 4-remove-duplicates.js`);
  }
}

checkDuplicates();

/**
 * @script            4-remove-duplicates
 * @category          remediator
 * @purpose           tooling:dev-tools
 * @scope             external
 * @owner             docs
 * @needs             node, @notionhq/client, dotenv, NOTION_API_KEY
 * @purpose-statement Archives duplicate Notion pages from the duplicate report while keeping the first record in each group.
 * @pipeline          manual
 * @usage             node tools/notion/4-remove-duplicates.js [flags]
 */

require("dotenv").config();
const { Client } = require("@notionhq/client");
const fs = require("fs");
const path = require("path");

async function removeDuplicates() {
  const reportPath = path.join(__dirname, "reports", "duplicates-report.json");

  if (!fs.existsSync(reportPath)) {
    console.error("ERROR: reports/duplicates-report.json not found!");
    console.error("Please run: node 3-check-duplicates.js first");
    process.exit(1);
  }

  const duplicates = JSON.parse(fs.readFileSync(reportPath, "utf8"));

  if (duplicates.length === 0) {
    console.log("No duplicates to remove!");
    return;
  }

  console.log(`Found ${duplicates.length} duplicate groups`);
  console.log("Strategy: Keep the FIRST entry, delete the rest\n");

  const notion = new Client({ auth: process.env.NOTION_API_KEY });

  let deletedCount = 0;
  let errorCount = 0;

  for (const dup of duplicates) {
    const [pageName, tabGroup, sectionGroup] = dup.key.split("|||");
    console.log(
      `Processing: "${pageName}" | Tab: "${tabGroup}" | Section: "${sectionGroup}"`
    );
    console.log(`  Keeping: ${dup.pages[0].id}`);

    // Delete all except the first one
    for (let i = 1; i < dup.pages.length; i++) {
      const pageToDelete = dup.pages[i];
      try {
        await notion.pages.update({
          page_id: pageToDelete.id,
          archived: true,
        });
        console.log(`  ✓ Deleted: ${pageToDelete.id}`);
        deletedCount++;
      } catch (error) {
        console.error(
          `  ✗ Failed to delete ${pageToDelete.id}:`,
          error.message
        );
        errorCount++;
      }
    }
    console.log();
  }

  console.log(`\nDeletion complete:`);
  console.log(`  Deleted: ${deletedCount}`);
  console.log(`  Errors: ${errorCount}`);

  // Write cleanup report
  const reportsDir = path.join(__dirname, "reports");
  if (!fs.existsSync(reportsDir)) {
    fs.mkdirSync(reportsDir, { recursive: true });
  }

  const cleanupReport = {
    timestamp: new Date().toISOString(),
    duplicateGroupsProcessed: duplicates.length,
    pagesDeleted: deletedCount,
    errors: errorCount,
  };

  const cleanupReportPath = path.join(reportsDir, "notion-clean.json");
  fs.writeFileSync(cleanupReportPath, JSON.stringify(cleanupReport, null, 2));
  console.log(`\nCleanup report saved to: ${cleanupReportPath}`);
  console.log(`\nRun 'node 1-read-notion-to-csv.js' to verify the cleanup.`);
}

removeDuplicates().catch(console.error);

/**
 * @script            5-export-to-notion
 * @category          automation
 * @purpose           tooling:dev-tools
 * @scope             external
 * @owner             docs
 * @needs             node, @notionhq/client, dotenv, NOTION_API_KEY, NOTION_DATABASE_ID, NOTION_WRITABLE_DATABASE_ID(optional)
 * @purpose-statement Updates existing Notion page grouping fields from the exported docs navigation snapshot.
 * @pipeline          manual
 * @usage             node tools/notion/5-export-to-notion.js [flags]
 */

require("dotenv").config();
const { Client } = require("@notionhq/client");
const fs = require("fs");
const path = require("path");

async function exportToNotion() {
  console.log("Starting export to Notion...\n");

  // Check prerequisites
  const notionJsonPath = path.join(__dirname, "data", "notion-read.json");
  const docsJsonPath = path.join(__dirname, "data", "docs-read.json");
  const duplicatesReportPath = path.join(
    __dirname,
    "reports",
    "duplicates-report.json"
  );

  if (!fs.existsSync(notionJsonPath)) {
    console.error("ERROR: data/notion-read.json not found!");
    console.error("Please run: node 1-read-notion-to-csv.js first");
    process.exit(1);
  }

  if (!fs.existsSync(docsJsonPath)) {
    console.error("ERROR: data/docs-read.json not found!");
    console.error("Please run: node 2-read-docs-to-csv.js first");
    process.exit(1);
  }

  // Check for duplicates
  if (fs.existsSync(duplicatesReportPath)) {
    const duplicates = JSON.parse(
      fs.readFileSync(duplicatesReportPath, "utf8")
    );
    if (duplicates.length > 0) {
      console.error("ERROR: Duplicates still exist in Notion database!");
      console.error(`Found ${duplicates.length} duplicate groups.`);
      console.error("Please run: node 4-remove-duplicates.js first");
      process.exit(1);
    }
  }

  const notionPages = JSON.parse(fs.readFileSync(notionJsonPath, "utf8"));
  const docsData = JSON.parse(fs.readFileSync(docsJsonPath, "utf8"));
  const { pages, sectionGroupColors } = docsData;

  console.log(`Notion database has: ${notionPages.length} pages`);
  console.log(`Docs.json has: ${pages.length} pages\n`);

  // Build map of existing pages - match by URL OR (Page Name + Tab Group) case-insensitive
  const existingByUrl = new Map();
  const existingByNameTab = new Map();
  notionPages.forEach((page) => {
    // Primary match: relativePath URL (case-insensitive)
    if (page.relativePath) {
      existingByUrl.set(page.relativePath.toLowerCase(), page.id);
    }
    // Secondary match: Page Name + Tab Group (case-insensitive)
    const nameTabKey = `${(page.pageName || "").toLowerCase()}|||${(
      page.tabGroup || ""
    ).toLowerCase()}`;
    existingByNameTab.set(nameTabKey, page.id);
  });

  const notion = new Client({ auth: process.env.NOTION_API_KEY });
  // Use the writable database for creating/updating pages
  const databaseId =
    process.env.NOTION_WRITABLE_DATABASE_ID || process.env.NOTION_DATABASE_ID;

  let createdCount = 0;
  let updatedCount = 0;
  let skippedCount = 0;
  let errorCount = 0;

  console.log("Syncing pages to Notion...\n");

  // Reverse pages array so Section Group options are created in correct order for Notion
  // (Notion shows select options in order they were created, we want reverse of docs.json order)
  const reversedPages = [...pages].reverse();

  for (const page of reversedPages) {
    try {
      // Match by URL first, then by Page Name + Tab Group (case-insensitive)
      let existingPageId = null;
      if (page.relativePath) {
        existingPageId = existingByUrl.get(page.relativePath.toLowerCase());
      }
      if (!existingPageId) {
        const nameTabKey = `${(page.pageName || "").toLowerCase()}|||${(
          page.tabGroup || ""
        ).toLowerCase()}`;
        existingPageId = existingByNameTab.get(nameTabKey);
      }

      if (existingPageId) {
        // ONLY update Section Group and Sub Section - nothing else
        const updateProperties = {
          "Section Group": page.sectionGroup
            ? {
                select: {
                  name: page.sectionGroup,
                  color: sectionGroupColors[page.sectionGroup],
                },
              }
            : { select: null },
          "Sub Section": page.subGroup
            ? { select: { name: page.subGroup } }
            : { select: null },
        };

        await notion.pages.update({
          page_id: existingPageId,
          properties: updateProperties,
        });
        updatedCount++;
        console.log(`↻ Updated: ${page.pageName}`);
      } else {
        // Page doesn't exist - skip (do NOT create new pages)
        skippedCount++;
        console.log(`⊘ Skipped (not in Notion): ${page.pageName}`);
      }
    } catch (error) {
      errorCount++;
      console.error(`✗ Failed to sync ${page.pageName}:`, error.message);
    }
  }

  console.log(`\nSync complete:`);
  console.log(`  Updated: ${updatedCount}`);
  console.log(`  Skipped (not in Notion): ${skippedCount}`);
  console.log(`  Errors: ${errorCount}`);

  // Write export report
  const reportsDir = path.join(__dirname, "reports");
  if (!fs.existsSync(reportsDir)) {
    fs.mkdirSync(reportsDir, { recursive: true });
  }

  const exportReport = {
    timestamp: new Date().toISOString(),
    totalDocsPages: pages.length,
    updated: updatedCount,
    skipped: skippedCount,
    errors: errorCount,
  };

  const reportPath = path.join(reportsDir, "notion-export.json");
  fs.writeFileSync(reportPath, JSON.stringify(exportReport, null, 2));
  console.log(`\nExport report saved to: ${reportPath}`);
}

exportToNotion().catch(console.error);

#!/usr/bin/env node
