# @script            ensure-mint-watcher-patch
# @category          utility
# @purpose           tooling:dev-tools
# @scope             tools/scripts
# @owner             docs
# @needs             E-C6, F-C1
# @purpose-statement Mint watcher patcher — applies patch to fix Mintlify file watcher issues in dev mode
# @pipeline          manual — interactive developer tool, not suited for automated pipelines
# @usage             bash tools/scripts/dev/ensure-mint-watcher-patch.sh [flags]
set -euo pipefail

MODE="apply"
if [ "${1:-}" = "--check" ]; then
    MODE="check"
elif [ "${1:-}" = "--apply" ] || [ "${1:-}" = "" ]; then
    MODE="apply"
elif [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
    cat <<'EOF'
Usage:
  bash tools/scripts/dev/ensure-mint-watcher-patch.sh --check
  bash tools/scripts/dev/ensure-mint-watcher-patch.sh --apply
EOF
    exit 0
else
    echo "Error: Unknown option: $1" >&2
    exit 2
fi

if ! command -v mint >/dev/null 2>&1; then
    echo "Error: mint CLI not found in PATH." >&2
    exit 2
fi

MINT_BIN="$(command -v mint)"
MINT_ENTRY_REALPATH="$(node -e 'const fs=require("fs"); console.log(fs.realpathSync(process.argv[1]));' "$MINT_BIN")"
MINT_ROOT="$(cd "$(dirname "$MINT_ENTRY_REALPATH")" && pwd)"
LISTENER_PATH="$MINT_ROOT/node_modules/@mintlify/previewing/dist/local-preview/listener/index.js"

if [ ! -f "$LISTENER_PATH" ]; then
    echo "Error: Mint listener file not found at: $LISTENER_PATH" >&2
    exit 2
fi

if rg -q "disableGlobbing:\\s*true" "$LISTENER_PATH"; then
    echo "Mint watcher patch present: $LISTENER_PATH"
    exit 0
fi

if [ "$MODE" = "check" ]; then
    echo "Mint watcher patch missing: $LISTENER_PATH" >&2
    exit 1
fi

if ! rg -q "^\\s*ignoreInitial:\\s*true," "$LISTENER_PATH"; then
    echo "Error: Could not find expected watcher option in listener file." >&2
    exit 2
fi

if ! node -e '
const fs = require("fs");
const path = process.argv[1];
const src = fs.readFileSync(path, "utf8");
if (src.includes("disableGlobbing: true")) {
  process.exit(0);
}
const needle = "        ignoreInitial: true,\n";
const injected = "        ignoreInitial: true,\n        disableGlobbing: true,\n";
if (!src.includes(needle)) {
  console.error("Unsupported listener format: ignoreInitial block not found.");
  process.exit(2);
}
const next = src.replace(needle, injected);
if (next === src) {
  console.error("Patch was not applied.");
  process.exit(2);
}
try {
  fs.writeFileSync(path, next, "utf8");
} catch (err) {
  console.error(err && err.message ? err.message : String(err));
  process.exit(3);
}
' "$LISTENER_PATH"; then
    echo "Error: Failed to apply Mint watcher patch at: $LISTENER_PATH" >&2
    exit 3
fi

echo "Mint watcher patch applied: $LISTENER_PATH"
exit 0

#!/usr/bin/env node
/**
 * @script            generate-mint-dev-scope
 * @category          generator
 * @purpose           tooling:dev-tools
 * @scope             tools/scripts/dev, docs.json, .mintignore
 * @owner             docs
 * @needs             E-C6, F-C1
 * @purpose-statement Mint dev scope generator — creates a scoped docs.json for running mint dev on a subset of pages
 * @pipeline          manual — interactive developer tool, not suited for automated pipelines
 * @usage             node tools/scripts/dev/generate-mint-dev-scope.js [flags]
 */

const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');
const readline = require('readline');

const STRUCTURAL_ARRAY_KEYS = ['versions', 'languages', 'tabs', 'anchors', 'groups', 'pages'];

function printUsage() {
  console.log(
    [
      'Usage: node tools/scripts/dev/generate-mint-dev-scope.js [options]',
      '',
      'Options:',
      '  --repo-root <path>',
      '  --workspace-base <path>',
      '  --scope-file <path>',
      '  --versions <csv>          (repeatable)',
      '  --languages <csv>         (repeatable)',
      '  --tabs <csv>              (repeatable)',
      '  --prefixes <csv>          (repeatable)',
      '  --interactive',
      '  --disable-openapi',
      '  --print-only',
      '  --help'
    ].join('\n')
  );
}

function splitCsv(value) {
  return String(value || '')
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean);
}

function uniqStrings(values) {
  return [...new Set((values || []).map((entry) => String(entry || '').trim()).filter(Boolean))];
}

function normalizeRoute(value) {
  return String(value || '')
    .trim()
    .replace(/^\/+/, '')
    .replace(/\/+$/, '');
}

function normalizeForCompare(value) {
  return String(value || '').trim().toLowerCase();
}

function routeMatchesPrefix(route, prefix) {
  const normalizedRoute = normalizeRoute(route);
  const normalizedPrefix = normalizeRoute(prefix);
  if (!normalizedRoute || !normalizedPrefix) return false;
  return normalizedRoute === normalizedPrefix || normalizedRoute.startsWith(`${normalizedPrefix}/`);
}

function isLanguageSegment(value) {
  const segment = String(value || '').trim();
  return /^[a-z]{2}(?:-[A-Za-z]{2})?$/.test(segment);
}

function isLikelyRouteEntry(value) {
  const route = normalizeRoute(value);
  if (!route) return false;
  if (route.startsWith('http://') || route.startsWith('https://')) return false;
  if (route === '-') return false;
  return route.includes('/');
}

function isOpenapiRoute(route) {
  const normalized = normalizeRoute(route);
  return normalized.includes('/api-reference/') || normalized.endsWith('/api-reference');
}

function shouldKeepRouteEntry(routeValue, context) {
  const route = normalizeRoute(routeValue);
  if (!route) return false;
  if (!isLikelyRouteEntry(route)) return false;
  if (context.disableOpenapi && isOpenapiRoute(route)) return false;
  if (context.prefixes.length === 0) return true;
  return context.prefixes.some((prefix) => routeMatchesPrefix(route, prefix));
}

function deriveSectionPrefix(routeValue) {
  const route = normalizeRoute(routeValue);
  if (!route) return '';
  const segments = route.split('/').filter(Boolean);
  if (segments.length < 2) return route;
  if (/^v\d+$/.test(segments[0])) {
    if (segments.length >= 3 && isLanguageSegment(segments[1])) {
      return segments.slice(0, 3).join('/');
    }
    return segments.slice(0, 2).join('/');
  }
  return segments.slice(0, 2).join('/');
}

function collectRoutesFromPages(pages, outSet) {
  if (!Array.isArray(pages)) return;
  for (const entry of pages) {
    if (typeof entry === 'string') {
      const route = normalizeRoute(entry);
      if (isLikelyRouteEntry(route)) outSet.add(route);
      continue;
    }
    if (entry && typeof entry === 'object') {
      visitNavigationNode(entry, outSet);
    }
  }
}

function visitNavigationNode(node, outSet) {
  if (!node || typeof node !== 'object') return;
  if (Array.isArray(node.pages)) collectRoutesFromPages(node.pages, outSet);
  if (Array.isArray(node.groups)) node.groups.forEach((group) => visitNavigationNode(group, outSet));
  if (Array.isArray(node.anchors)) node.anchors.forEach((anchor) => visitNavigationNode(anchor, outSet));
  if (Array.isArray(node.tabs)) node.tabs.forEach((tab) => visitNavigationNode(tab, outSet));
  if (Array.isArray(node.languages)) node.languages.forEach((language) => visitNavigationNode(language, outSet));
  if (Array.isArray(node.versions)) node.versions.forEach((version) => visitNavigationNode(version, outSet));
}

function collectRoutesFromNavigation(navigation) {
  const routes = new Set();
  visitNavigationNode(navigation, routes);
  return [...routes].sort();
}

function parseArgs(argv) {
  const out = {
    repoRoot: process.cwd(),
    workspaceBase: path.join(os.tmpdir(), 'lpd-mint-dev'),
    scopeFile: '',
    versions: [],
    languages: [],
    tabs: [],
    prefixes: [],
    interactive: false,
    disableOpenapi: false,
    printOnly: false,
    help: false
  };

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === '--help' || token === '-h') {
      out.help = true;
      continue;
    }
    if (token === '--repo-root') {
