#!/usr/bin/env node
/**
 * @script            enforce-generated-file-banners
 * @category          remediator
 * @purpose           governance:index-management
 * @scope             tools/scripts, tools/lib, docs-guide/indexes, v2, tests/unit/docs-guide-sot.test.js
 * @owner             docs
 * @needs             R-R16, R-R17
 * @purpose-statement Generated file banner enforcer — checks (--check) or writes (default) "do not edit" banners on generated files
 * @pipeline          P1, P3
 * @dualmode          --check (enforcer) | default (remediator)
 * @usage             node tools/scripts/enforce-generated-file-banners.js [flags]
 */

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const { loadI18nConfig } = require('./i18n/lib/config');
const { parseProvenanceComment } = require('./i18n/lib/provenance');
const {
  GENERATED_HIDDEN_MARKER,
  parseGeneratedHiddenBanner,
  hasGeneratedNote,
  removeGeneratedNotes,
  hasFrontmatterKey
} = require('../lib/generated-file-banners');

const REPO_ROOT = process.cwd();

const NON_I18N_GENERATED_STATIC = [
  'docs-guide/indexes/components-index.mdx',
  'docs-guide/indexes/pages-index.mdx',
  'docs-guide/indexes/scripts-index.mdx',
  'docs-guide/indexes/templates-index.mdx',
  'docs-guide/indexes/workflows-index.mdx',
  'v2/resources/documentation-guide/component-library/overview.mdx'
];

const CHECK_COMMANDS = [
  ['tools/scripts/generate-docs-guide-indexes.js', '--check'],
  ['tools/scripts/generate-docs-guide-pages-index.js', '--check'],
  ['tools/scripts/generate-docs-guide-components-index.js', '--check'],
  ['tests/unit/script-docs.test.js', '--check-indexes'],
  ['tools/scripts/generate-pages-index.js']
];

const WRITE_COMMANDS = [
  ['tools/scripts/generate-docs-guide-indexes.js', '--write'],
  ['tools/scripts/generate-docs-guide-pages-index.js', '--write'],
  ['tools/scripts/generate-docs-guide-components-index.js', '--write'],
  ['tests/unit/script-docs.test.js', '--write', '--rebuild-indexes'],
  ['tools/scripts/generate-pages-index.js', '--write', '--rebuild-indexes']
];

function normalizeRepoPath(value) {
  return String(value || '').split(path.sep).join('/');
}

function readFileSafe(repoPath) {
  try {
    return fs.readFileSync(path.join(REPO_ROOT, repoPath), 'utf8');
  } catch (_err) {
    return '';
  }
}

function listGeneratedV2IndexFiles() {
  const root = path.join(REPO_ROOT, 'v2');
  if (!fs.existsSync(root)) return [];
  const out = ['v2/index.mdx'];
  const entries = fs.readdirSync(root, { withFileTypes: true });
  entries
    .filter((entry) => entry.isDirectory())
    .forEach((entry) => {
      const rel = normalizeRepoPath(path.join('v2', entry.name, 'index.mdx'));
      if (fs.existsSync(path.join(REPO_ROOT, rel))) out.push(rel);
    });
  return [...new Set(out)].sort();
}

function getExpectedNonI18nGeneratedFiles() {
  return [...new Set([...NON_I18N_GENERATED_STATIC, ...listGeneratedV2IndexFiles()])].sort();
}

function runNodeCommand(args) {
  const result = spawnSync('node', args, {
    cwd: REPO_ROOT,
    encoding: 'utf8'
  });
  if (result.stdout) process.stdout.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  return result.status === 0;
}

function runGeneratorSet(writeMode, violations) {
  const commands = writeMode ? WRITE_COMMANDS : CHECK_COMMANDS;
  commands.forEach((args) => {
    const ok = runNodeCommand(args);
    if (!ok) {
      violations.push({
        rule: 'GENERATOR_SYNC',
        file: args[0],
        message: `Generator command failed: node ${args.join(' ')}`
      });
    }
  });
}

function addViolation(violations, rule, file, message) {
  violations.push({
    rule,
    file,
    message
  });
}

function validateNonI18nGeneratedFiles(violations) {
  const files = getExpectedNonI18nGeneratedFiles();
  files.forEach((repoPath) => {
    const raw = readFileSafe(repoPath);
    if (!raw.trim()) {
      addViolation(violations, 'MISSING_FILE', repoPath, 'Generated file is missing or empty.');
      return;
    }

    if (!hasFrontmatterKey(raw, 'title')) {
      addViolation(violations, 'FRONTMATTER_TITLE', repoPath, 'Generated MDX must include frontmatter `title`.');
    }
    if (!hasFrontmatterKey(raw, 'description')) {
      addViolation(violations, 'FRONTMATTER_DESCRIPTION', repoPath, 'Generated MDX must include frontmatter `description`.');
    }

    const hidden = parseGeneratedHiddenBanner(raw);
    if (!hidden.found) {
      addViolation(violations, 'HIDDEN_BANNER_MISSING', repoPath, 'Missing standardized hidden generated banner.');
    } else if (hidden.marker !== GENERATED_HIDDEN_MARKER) {
      addViolation(
        violations,
        'HIDDEN_BANNER_MARKER',
        repoPath,
        `Unexpected hidden banner marker "${hidden.marker}" (expected "${GENERATED_HIDDEN_MARKER}").`
      );
    }

    if (!hasGeneratedNote(raw)) {
      addViolation(violations, 'VISIBLE_NOTE_MISSING', repoPath, 'Missing visible generated <Note> block.');
    }
  });
}

function walkMdxFiles(rootAbs, out = []) {
  if (!fs.existsSync(rootAbs)) return out;
  const entries = fs.readdirSync(rootAbs, { withFileTypes: true });
  entries.forEach((entry) => {
    const abs = path.join(rootAbs, entry.name);
    if (entry.isDirectory()) {
      walkMdxFiles(abs, out);
      return;
    }
    if (!entry.isFile()) return;
    if (!/\.mdx$/i.test(entry.name)) return;
    out.push(abs);
  });
  return out;
}

function collectLocalizedMdxFiles() {
  const { config } = loadI18nConfig({ repoRoot: REPO_ROOT });
  const root = normalizeRepoPath(config.sourceRoot || 'v2');
  const languages = Array.isArray(config.targetLanguages) ? config.targetLanguages : [];
  const files = [];

  languages.forEach((language) => {
    const abs = path.join(REPO_ROOT, root, language);
    if (!fs.existsSync(abs) || !fs.statSync(abs).isDirectory()) return;
    walkMdxFiles(abs, files);
  });

  return files
    .map((abs) => normalizeRepoPath(path.relative(REPO_ROOT, abs)))
    .sort((a, b) => a.localeCompare(b));
}

function normalizeI18nNoteParity(repoPath, sourceHasNote) {
  const fullPath = path.join(REPO_ROOT, repoPath);
  const content = fs.readFileSync(fullPath, 'utf8');
  if (!sourceHasNote && hasGeneratedNote(content)) {
    const next = removeGeneratedNotes(content);
    if (next !== content) {
      fs.writeFileSync(fullPath, next, 'utf8');
      return true;
    }
  }
  return false;
}

function validateI18nParity(writeMode, violations, warnings) {
  const localizedFiles = collectLocalizedMdxFiles();
  let normalizedCount = 0;

  localizedFiles.forEach((repoPath) => {
    const raw = readFileSafe(repoPath);
    if (!raw.trim()) return;

    const hiddenBanner = parseGeneratedHiddenBanner(raw);
    if (hiddenBanner.found) return;

    const provenance = parseProvenanceComment(raw);
    if (!provenance) {
      addViolation(violations, 'I18N_PROVENANCE_MISSING', repoPath, 'Missing codex-i18n provenance hidden comment.');
      return;
    }

    const sourcePath = normalizeRepoPath(provenance.sourcePath || '');
    if (!sourcePath) {
      warnings.push({
        rule: 'I18N_SOURCE_PATH_MISSING',
        file: repoPath,
        message: 'Provenance is missing sourcePath; skipping visible-note parity check.'
      });

#!/usr/bin/env node
/**
 * @script    check-component-immutability
 * @category  enforcer
 * @purpose   governance:repo-health
 * @scope     changed
 * @owner     docs
 * @needs     R-R10
 * @purpose-statement  Flags modifications to existing component files in PR context. New files allowed. Modifications require approval label.
 * @pipeline  P2, P3
 * @usage     node tools/scripts/enforcers/pr/check-component-immutability.js --base-ref main
 */

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const DEFAULT_BASE_REF = 'docs-v2';
const APPROVAL_LABEL = 'component-change-approved';
const COMPONENT_ROOT = 'snippets/components/';
const REPO_ROOT = getRepoRoot();

function getRepoRoot() {
  const result = spawnSync('git', ['rev-parse', '--show-toplevel'], { encoding: 'utf8' });
  if (result.status === 0 && String(result.stdout || '').trim()) {
    return String(result.stdout || '').trim();
  }
  return process.cwd();
}

function toPosix(value) {
  return String(value || '').split(path.sep).join('/');
}

function runGit(args) {
  const result = spawnSync('git', args, { cwd: REPO_ROOT, encoding: 'utf8' });
  if (result.status !== 0) {
    const stderr = String(result.stderr || '').trim();
    const stdout = String(result.stdout || '').trim();
    throw new Error(stderr || stdout || `git ${args.join(' ')} failed`);
  }
  return String(result.stdout || '').trim();
}

function tryRunGit(args) {
  try {
    return runGit(args);
  } catch (_error) {
    return '';
  }
}

function parseArgs(argv) {
  const args = {
    baseRef: DEFAULT_BASE_REF
  };

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];

    if (token === '--base-ref') {
      args.baseRef = String(argv[i + 1] || '').trim() || DEFAULT_BASE_REF;
      i += 1;
      continue;
    }

    if (token.startsWith('--base-ref=')) {
      args.baseRef = token.slice('--base-ref='.length).trim() || DEFAULT_BASE_REF;
      continue;
    }

    if (token === '--help' || token === '-h') {
      args.help = true;
      continue;
    }

    throw new Error(`Unknown argument: ${token}`);
  }

  return args;
}

function usage() {
  console.log(
    'Usage: node tools/scripts/enforcers/pr/check-component-immutability.js [--base-ref docs-v2]'
  );
}

function resolveBaseRef(baseRef) {
  const remoteRef = `origin/${baseRef}`;
  if (tryRunGit(['rev-parse', '--verify', remoteRef])) return remoteRef;
  if (tryRunGit(['rev-parse', '--verify', baseRef])) return baseRef;
  throw new Error(
    `Unable to resolve base ref "${baseRef}" or "${remoteRef}". Fetch the base branch before running this check.`
  );
}

function parseDiffEntry(line) {
  const parts = String(line || '')
    .split('\t')
    .map((part) => part.trim())
    .filter(Boolean);

  if (parts.length < 2) return null;

  const status = parts[0];
  if (status.startsWith('R')) {
    const fromPath = toPosix(parts[1]);
    const toPath = toPosix(parts[2]);
    if (!fromPath || !toPath) return null;
    return {
      status,
      path: toPath,
      fromPath,
      display: `${fromPath} -> ${toPath}`
    };
  }

  return {
    status,
    path: toPosix(parts[1]),
    fromPath: '',
    display: toPosix(parts[1])
  };
}

function getChangedComponentEntries(baseRef) {
  const resolvedBaseRef = resolveBaseRef(baseRef);
  const mergeBase = runGit(['merge-base', resolvedBaseRef, 'HEAD']);
  const output = runGit([
    'diff',
    '--name-status',
    '--find-renames',
    '--diff-filter=AMDRT',
    `${mergeBase}..HEAD`,
    '--',
    COMPONENT_ROOT
  ]);

  if (!output) return [];

  return output
    .split('\n')
    .map((line) => parseDiffEntry(line))
    .filter((entry) => Boolean(entry));
}

function classifyEntries(entries) {
  const newFiles = [];
  const existingChanges = [];

  entries.forEach((entry) => {
    if (entry.status === 'A') {
      newFiles.push(entry);
      return;
    }
    existingChanges.push(entry);
  });

  return { newFiles, existingChanges };
}

function loadPrLabels() {
  const eventPath = String(process.env.GITHUB_EVENT_PATH || '').trim();
  if (!eventPath) {
    return {
      available: false,
      labels: [],
      reason: 'PR context unavailable: GITHUB_EVENT_PATH is not set.'
    };
  }

  try {
    const event = JSON.parse(fs.readFileSync(eventPath, 'utf8'));
    const rawLabels =
      event && event.pull_request && Array.isArray(event.pull_request.labels)
        ? event.pull_request.labels
        : null;

    if (!rawLabels) {
      return {
        available: false,
        labels: [],
        reason: 'PR context unavailable: GITHUB_EVENT_PATH does not contain pull_request.labels.'
      };
    }

    return {
      available: true,
      labels: rawLabels
        .map((entry) => String(entry && entry.name ? entry.name : '').trim())
        .filter(Boolean),
      reason: ''
    };
  } catch (error) {
    return {
      available: false,
      labels: [],
      reason: `PR context unavailable: failed to parse GITHUB_EVENT_PATH (${error.message}).`
    };
  }
}

function formatEntry(entry) {
  if (entry.status.startsWith('R')) return `RENAMED: ${entry.display}`;
  if (entry.status === 'M') return `MODIFIED: ${entry.display}`;
  if (entry.status === 'D') return `DELETED: ${entry.display}`;
  if (entry.status === 'T') return `TYPE-CHANGED: ${entry.display}`;
  if (entry.status === 'A') return `NEW: ${entry.display}`;
  return `${entry.status}: ${entry.display}`;
}

function printSection(stream, title, entries) {
  if (!entries.length) return;
  stream.write(`\n${title}\n`);
  entries.forEach((entry) => {
    stream.write(`  ${formatEntry(entry)}\n`);
  });
}

#!/usr/bin/env node
/**
 * @script            check-pr-template
 * @category          enforcer
 * @purpose           governance:repo-health
 * @scope             tools/scripts/enforcers/pr, .github/pull_request_template.md, .github/pull-request-template-v2.md
 * @owner             docs
 * @needs             R-R14, R-C6
 * @purpose-statement Enforces that PR descriptions include required change and rationale sections before merge
 * @pipeline          ci
 * @usage             PR_BODY="..." node tools/scripts/enforcers/pr/check-pr-template.js
 */

const fs = require('fs');

const CHANGE_HEADINGS = new Set(['what changed', 'changes', 'changes made']);
const RATIONALE_HEADINGS = new Set(['why', 'motivation', 'reason', 'description']);

function normalizeHeading(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[`*_~]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function readPrBody() {
  const fromEnv = String(process.env.PR_BODY || '');
  if (fromEnv.trim()) return fromEnv;
  if (!process.stdin.isTTY) {
    return fs.readFileSync(0, 'utf8');
  }
  return '';
}

function collectHeadings(body) {
  const headings = [];
  const re = /^\s{0,3}#{2,6}\s+(.+?)\s*#*\s*$/gm;
  let match = re.exec(body);

  while (match) {
    headings.push(normalizeHeading(match[1]));
    match = re.exec(body);
  }

  return headings;
}

function hasRequiredHeading(headings, allowed) {
  return headings.some((heading) => allowed.has(heading));
}

function main() {
  const prBody = readPrBody();
  const headings = collectHeadings(prBody);
  const hasChangeSection = hasRequiredHeading(headings, CHANGE_HEADINGS);
  const hasRationaleSection = hasRequiredHeading(headings, RATIONALE_HEADINGS);
  const missing = [];

  if (!hasChangeSection) {
    missing.push('change section (accepted: ## What changed, ## Changes, ## Changes Made)');
  }

  if (!hasRationaleSection) {
    missing.push('rationale section (accepted: ## Why, ## Motivation, ## Reason, ## Description)');
  }

  if (missing.length === 0) {
    console.log('✅ PR template sections present.');
    process.exit(0);
  }

  const branch = String(process.env.GITHUB_HEAD_REF || '').trim();
  const message = `Missing required PR sections: ${missing.join('; ')}`;

  if (branch.startsWith('codex/')) {
    console.warn(`⚠️ ${message}`);
    process.exit(0);
  }

  console.error(`❌ ${message}`);
  process.exit(1);
}

main();

