    .filter(Boolean)
    .filter((candidate, idx, arr) => arr.indexOf(candidate) === idx);

  for (const candidate of candidates) {
    const absPath = path.join(REPO_ROOT, candidate);
    if (fileExists(absPath)) {
      return candidate;
    }
  }

  return normalized;
}

function resolveSourceDirRel(outputDirRel) {
  const normalized = normalizeRel(outputDirRel);
  if (!normalized.startsWith('v2/pages/')) return normalized;
  const rest = normalized.slice('v2/pages/'.length);
  const [legacyDomain] = rest.split('/').filter(Boolean);
  const modernDomain = DOMAIN_RENAME_MAP[legacyDomain];
  if (!modernDomain) return normalized;
  const modernDirRel = normalizeRel(path.posix.join('v2', modernDomain));
  if (!fileExists(path.join(REPO_ROOT, modernDirRel))) return normalized;
  return modernDirRel;
}

function isMarkdownFile(fileName) {
  return /\.(md|mdx)$/i.test(fileName);
}

function isIndexFile(fileName) {
  const lower = fileName.toLowerCase();
  return lower === INDEX_FILENAME || lower === LEGACY_INDEX_FILENAME;
}

function sortAlpha(values) {
  return [...values].sort((a, b) => a.localeCompare(b, 'en', { sensitivity: 'base' }));
}

function getDirectSubdirs(absDir) {
  if (!fs.existsSync(absDir)) return [];
  const entries = fs.readdirSync(absDir, { withFileTypes: true });
  return sortAlpha(entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name));
}

function getDirectMarkdownFiles(absDir) {
  if (!fs.existsSync(absDir)) return [];
  const entries = fs.readdirSync(absDir, { withFileTypes: true });
  return sortAlpha(
    entries
      .filter((entry) => entry.isFile())
      .map((entry) => entry.name)
      .filter((name) => isMarkdownFile(name) && !isIndexFile(name))
  );
}

function normalizeDocsRouteKey(routePath) {
  let normalized = normalizeRel(String(routePath || '').trim());
  normalized = normalized.replace(/\.(md|mdx)$/i, '');
  normalized = normalized.replace(/\/index$/i, '');
  normalized = normalized.replace(/\/+$/, '');
  return normalized;
}

function collectDocsPageEntries(node, out = []) {
  if (typeof node === 'string') {
    const value = node.trim();
    if (value.startsWith('v1/') || value.startsWith('v2/')) {
      out.push(value);
    }
    return out;
  }

  if (Array.isArray(node)) {
    node.forEach((item) => collectDocsPageEntries(item, out));
    return out;
  }

  if (!node || typeof node !== 'object') {
    return out;
  }

  if (Array.isArray(node.pages)) {
    node.pages.forEach((item) => collectDocsPageEntries(item, out));
  }

  Object.values(node).forEach((value) => collectDocsPageEntries(value, out));
  return out;
}

function getDocsJsonRouteKeys() {
  const docsJsonAbs = path.join(REPO_ROOT, DOCS_JSON_FILENAME);
  if (!fileExists(docsJsonAbs)) {
    throw new Error(`Missing ${DOCS_JSON_FILENAME} at repo root`);
  }

  const docsJson = JSON.parse(fs.readFileSync(docsJsonAbs, 'utf8'));
  const versions = docsJson?.navigation?.versions || [];
  const entries = [];

  versions.forEach((versionNode) => {
    if (versionNode?.languages) {
      collectDocsPageEntries(versionNode.languages, entries);
    }
  });

  const keys = new Set();
  entries.forEach((entry) => {
    const key = normalizeDocsRouteKey(entry);
    if (key) keys.add(key);
  });

  return keys;
}

#!/usr/bin/env node
/**
 * @script            generate-localized-docs-json
 * @category          generator
 * @purpose           feature:translation
 * @scope             docs.json, tools/scripts/i18n
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement Locale docs.json generator — produces localised docs.json variants from route-map and source docs.json
 * @pipeline          P6 (on-demand, translation pipeline)
 * @usage             node tools/scripts/i18n/generate-localized-docs-json.js [flags]
 */

const fs = require('fs');
const path = require('path');
const { parseCommonCliArgs, loadI18nConfig, buildRuntimeOptions } = require('./lib/config');
const { getRepoRoot, readJson, writeJson, writeTextIfChanged } = require('./lib/common');
const { createTranslator } = require('./lib/providers');
const { generateLocalizedDocsJson } = require('./lib/docs-json-localizer');
const { collectExistingLocalizedRouteMapEntries } = require('./lib/docs-routes');

function printHelp() {
  console.log(
    [
      'Usage: node tools/scripts/i18n/generate-localized-docs-json.js [options]',
      '',
      'Options:',
      '  --languages <csv>            Target languages (default from config)',
      '  --route-map <path>           Route-map artifact from translate-docs.js',
      '  --provider <name>            openrouter | mock',
      '  --write                      Update docs.json in place',
      '  --dry-run                    Compute report only (no write)',
      '  --allow-mock-write           Allow mock provider in write mode (dangerous; testing only)',
      '  --report-json <path>         Write docs.json generation report',
      '  --config <path>              Alternate i18n config JSON',
      '  --help, -h                   Show this help'
    ].join('\n')
  );
}

function assertMockWriteAllowed({ translator, runtime, config, cliArgs }) {
  const writeMode = Boolean(cliArgs.write && !runtime.dryRun);
  if (!writeMode) return;
  if (translator?.name !== 'mock') return;
  if (runtime.allowMockWrite) return;
  if (config?.qualityGates?.blockMockProviderWrites === false) return;
  throw new Error(
    'Refusing to write docs.json with mock provider. Use --dry-run for mock testing or pass --allow-mock-write only for deliberate fixture generation.'
  );
}

function loadRouteMapEntries(repoRoot, routeMapPath, config, runtime) {
  if (routeMapPath) {
    const abs = path.resolve(repoRoot, routeMapPath);
    const parsed = readJson(abs);
    return {
      path: abs,
      entries: Array.isArray(parsed.entries) ? parsed.entries : [],
      metadata: {
        provider: parsed.provider || null,
        runtime: parsed.runtime || null,
        scope: parsed.scope || null,
        warnings: Array.isArray(parsed.warnings) ? parsed.warnings : []
      }
    };
  }
  return {
    path: '',
    entries: collectExistingLocalizedRouteMapEntries(repoRoot, config.generatedRoot, {
      generatedPathStyle: config.generatedPathStyle,
      sourceRoot: config.sourceRoot,
      knownLanguages: runtime.languages
    }),
    metadata: {
      provider: null,
      runtime: null,
      scope: null,
      warnings: []
    }
  };
}

async function run(argv = process.argv.slice(2)) {
  const cliArgs = parseCommonCliArgs(argv);
  if (cliArgs.help || argv.includes('--help') || argv.includes('-h')) {
    printHelp();
    return { help: true };
  }
  const { repoRoot, configPath, config } = loadI18nConfig({
    repoRoot: getRepoRoot(),
    configPath: cliArgs.configPath || undefined
  });
  const runtime = buildRuntimeOptions(cliArgs, config);
  const translator = createTranslator({ config, providerNameOverride: runtime.providerNameOverride });
  assertMockWriteAllowed({ translator, runtime, config, cliArgs });
  const docsJsonPath = path.join(repoRoot, 'docs.json');
  const docsJson = readJson(docsJsonPath);
  const routeMap = loadRouteMapEntries(repoRoot, cliArgs.routeMapPath, config, runtime);
  const result = await generateLocalizedDocsJson({
    docsJson,
    repoRoot,
    targetLanguages: runtime.languages,
    translator,
    translationRules: config.translationRules || {},
    routeMapEntries: routeMap.entries,
    routeMapMetadata: routeMap.metadata || {},
    qualityGates: config.qualityGates || {},
    reporting: config.reporting || {},
    runtime,
    languageCodeMap: config.languageCodeMap || {},
    writeMode: Boolean(cliArgs.write && !runtime.dryRun),
    allowMockWrite: runtime.allowMockWrite
  });

  const nextText = `${JSON.stringify(result.docsJson, null, 2)}\n`;
  let changed = false;
  if (cliArgs.write && !runtime.dryRun) {
    changed = writeTextIfChanged(docsJsonPath, nextText);
  }

  const report = {
    generatedAt: new Date().toISOString(),
    repoRoot,
    configPath,
    docsJsonPath,
    routeMapPath: routeMap.path,
    dryRun: runtime.dryRun || !cliArgs.write,
    wroteDocsJson: Boolean(cliArgs.write && !runtime.dryRun && changed),
    provider: {
      name: translator.name,
      mode: translator.name
    },
    warnings: result.report.warnings || [],
    perLanguage: result.report.perLanguage
  };

  if (runtime.reportJsonPath) {
    writeJson(path.resolve(repoRoot, runtime.reportJsonPath), report);
  }

  console.log(
    [
      'i18n generate-localized-docs-json summary',
      `- languages: ${runtime.languages.join(', ')}`,
      `- provider: ${translator.name}`,
      `- route-map entries: ${routeMap.entries.length}`,
      `- write mode: ${cliArgs.write && !runtime.dryRun ? 'enabled' : 'disabled'}`,
      `- docs.json changed: ${changed ? 'yes' : 'no'}`
    ].join('\n')
  );

  return report;
}

if (require.main === module) {
  run().catch((error) => {
    console.error(`❌ ${error.message}`);
    process.exit(1);
  });
}

module.exports = { run };

/**
 * @script            common
 * @category          utility
 * @purpose           feature:translation
 * @scope             tools/scripts
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement i18n shared utilities — common helper functions for translation pipeline
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/scripts/i18n/lib/common.js [flags]
 */
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

function toPosix(value) {
  return String(value || '').split(path.sep).join('/');
}

function normalizeRepoRel(repoRelPath) {
  return toPosix(String(repoRelPath || '').replace(/^\.\//, '').replace(/^\/+/, ''));
}

function ensureDir(dirPath) {
  fs.mkdirSync(dirPath, { recursive: true });
}

function ensureDirForFile(filePath) {
  ensureDir(path.dirname(filePath));
}

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, value) {
  ensureDirForFile(filePath);
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
}

function writeTextIfChanged(filePath, nextContent) {
  let prev = null;
  try {
    prev = fs.readFileSync(filePath, 'utf8');
  } catch (_err) {
    prev = null;
  }
  if (prev === nextContent) return false;
  ensureDirForFile(filePath);
  fs.writeFileSync(filePath, nextContent, 'utf8');
  return true;
}

function getRepoRoot(cwd = process.cwd()) {
  try {
    return execSync('git rev-parse --show-toplevel', { cwd, encoding: 'utf8' }).trim();
  } catch (_err) {
    return cwd;
  }
}

function chunkArray(items, maxItems, maxChars = Infinity, getSize = (item) => String(item || '').length) {
  const chunks = [];
  let current = [];
  let currentChars = 0;

  for (const item of items) {
    const size = getSize(item);
    const wouldOverflowItems = current.length >= maxItems;
    const wouldOverflowChars = current.length > 0 && currentChars + size > maxChars;
    if (wouldOverflowItems || wouldOverflowChars) {
      chunks.push(current);
      current = [];
      currentChars = 0;
    }
    current.push(item);
    currentChars += size;
  }
  if (current.length > 0) chunks.push(current);
  return chunks;
}

function parseCsv(value) {
  return String(value || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

function isExternalHref(href) {
  return /^(https?:\/\/|mailto:|#)/i.test(String(href || '').trim());
}

module.exports = {
  chunkArray,
  ensureDir,
  ensureDirForFile,
  getRepoRoot,
  isExternalHref,
  normalizeRepoRel,
  parseCsv,
  readJson,
  toPosix,
  writeJson,
  writeTextIfChanged
};

/**
 * @script            config
 * @category          utility
 * @purpose           feature:translation
 * @scope             tools/scripts
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement i18n configuration — language codes, locale paths, translation settings
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/scripts/i18n/lib/config.js [flags]
 */
const fs = require('fs');
const path = require('path');
const { getRepoRoot, parseCsv, readJson } = require('./common');

const DEFAULT_CONFIG_REPO_REL = 'tools/i18n/config.json';

function loadI18nConfig(options = {}) {
  const repoRoot = options.repoRoot || getRepoRoot();
  const configPath = options.configPath
    ? path.resolve(repoRoot, options.configPath)
    : path.join(repoRoot, DEFAULT_CONFIG_REPO_REL);

  if (!fs.existsSync(configPath)) {
    throw new Error(`i18n config not found: ${configPath}`);
  }

  const config = readJson(configPath);
  validateI18nConfig(config, { configPath });
  return { repoRoot, configPath, config };
}

function validateI18nConfig(config, context = {}) {
  const configPath = context.configPath || DEFAULT_CONFIG_REPO_REL;
  if (!config || typeof config !== 'object') {
    throw new Error(`Invalid i18n config at ${configPath}: expected object`);
  }

  const requiredStringKeys = ['sourceLanguage', 'sourceRoot', 'generatedRoot'];
  for (const key of requiredStringKeys) {
    if (typeof config[key] !== 'string' || !config[key].trim()) {
      throw new Error(`Invalid i18n config at ${configPath}: missing "${key}"`);
    }
  }

  if (!Array.isArray(config.targetLanguages) || config.targetLanguages.length === 0) {
    throw new Error(`Invalid i18n config at ${configPath}: targetLanguages must be a non-empty array`);
  }

  if (config.languageCodeMap != null && (typeof config.languageCodeMap !== 'object' || Array.isArray(config.languageCodeMap))) {
    throw new Error(`Invalid i18n config at ${configPath}: languageCodeMap must be an object when provided`);
  }

  if (config.generatedPathStyle != null) {
    const style = String(config.generatedPathStyle || '').trim();
    if (!['v2_i18n_legacy', 'v2_language_prefix'].includes(style)) {
      throw new Error(
        `Invalid i18n config at ${configPath}: generatedPathStyle must be "v2_i18n_legacy" or "v2_language_prefix"`
      );
    }
  }

  if (!config.provider || typeof config.provider !== 'object') {
    throw new Error(`Invalid i18n config at ${configPath}: missing provider`);
  }

  const models = config.provider.modelCandidates;
  if (!Array.isArray(models) || models.length === 0 || models.some((m) => !String(m || '').trim())) {
    throw new Error(`Invalid i18n config at ${configPath}: provider.modelCandidates must be a non-empty array`);
  }
}

function normalizeLanguageCode(language, config = {}) {
  const raw = String(language || '').trim();
  if (!raw) return '';
  const map = config.languageCodeMap || {};
  if (typeof map[raw] === 'string' && map[raw].trim()) return map[raw].trim();
  const lowerMap = new Map(Object.entries(map).map(([k, v]) => [String(k).toLowerCase(), String(v).trim()]));
  return lowerMap.get(raw.toLowerCase()) || raw;
}

function normalizeLanguageList(languages, config = {}) {
  const out = [];
  const seen = new Set();
  const aliasesApplied = [];
  for (const value of languages || []) {
    const requestedLanguage = String(value || '').trim();
    if (!requestedLanguage) continue;
    const effectiveLanguage = normalizeLanguageCode(requestedLanguage, config);
    if (!effectiveLanguage) continue;
    if (requestedLanguage !== effectiveLanguage) {
      aliasesApplied.push({ requestedLanguage, effectiveLanguage });
    }
    if (seen.has(effectiveLanguage)) continue;
    seen.add(effectiveLanguage);
    out.push(effectiveLanguage);
  }
  return { languages: out, aliasesApplied };
}

function buildRuntimeOptions(cliArgs = {}, config = {}) {
  const defaults = config.scopeDefaults || {};
  const requestedLanguages =
    cliArgs.languages && cliArgs.languages.length ? [...cliArgs.languages] : [...(config.targetLanguages || [])];
  const normalizedLanguages = normalizeLanguageList(requestedLanguages, config);
  const runtime = {
    requestedLanguages,
    languages: normalizedLanguages.languages,
    languageAliasesApplied: normalizedLanguages.aliasesApplied,
    scopeMode: cliArgs.scopeMode || defaults.defaultMode || 'changed_since_ref',
    baseRef: cliArgs.baseRef || defaults.defaultBaseRef || 'docs-v2',
    prefixes: cliArgs.prefixes || [],
    pathsFile: cliArgs.pathsFile || '',
    maxPages: Number.isFinite(cliArgs.maxPages) ? cliArgs.maxPages : Number(defaults.maxPagesPerRun) || 50,
    dryRun: Boolean(cliArgs.dryRun),
    force: Boolean(cliArgs.force),
    routeMapPath: cliArgs.routeMapPath || '',
    reportJsonPath: cliArgs.reportJsonPath || '',
    configPath: cliArgs.configPath || '',
    providerNameOverride: cliArgs.providerName || '',
    allowMockWrite: Boolean(cliArgs.allowMockWrite),
    failOnMockArtifacts: Boolean(cliArgs.failOnMockArtifacts),
    failOnMissingProvenance: Boolean(cliArgs.failOnMissingProvenance),
    cleanupOnly: Boolean(cliArgs.cleanupOnly),
    rewriteLinks: typeof cliArgs.rewriteLinks === 'boolean' ? cliArgs.rewriteLinks : null,
    rewriteScope: cliArgs.rewriteScope || '',
    help: Boolean(cliArgs.help)
  };
  return runtime;
}

function parseCommonCliArgs(argv) {
  const args = {
    languages: [],
    prefixes: [],
    dryRun: false,
    force: false,
    maxPages: null,
    scopeMode: '',
    baseRef: '',
    pathsFile: '',
    routeMapPath: '',
    reportJsonPath: '',
    configPath: '',
    providerName: '',
    write: false,
    allowMockWrite: false,
    failOnMockArtifacts: false,
    failOnMissingProvenance: false,
    cleanupOnly: false,
    rewriteLinks: null,
    rewriteScope: '',
    help: false
  };

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    const next = argv[i + 1];
    switch (token) {
      case '--languages':
        args.languages = parseCsv(next);
        i += 1;
        break;
      case '--prefixes':
        args.prefixes = parseCsv(next);
        i += 1;
        break;
      case '--scope-mode':
        args.scopeMode = String(next || '').trim();
        i += 1;
        break;
      case '--base-ref':
        args.baseRef = String(next || '').trim();
        i += 1;
        break;
      case '--paths-file':
        args.pathsFile = String(next || '').trim();
        i += 1;
        break;
      case '--max-pages': {
        const parsed = Number(next);
        if (Number.isFinite(parsed) && parsed > 0) args.maxPages = parsed;
        i += 1;
        break;
      }
      case '--route-map':
        args.routeMapPath = String(next || '').trim();
        i += 1;
        break;
      case '--report-json':
        args.reportJsonPath = String(next || '').trim();
        i += 1;
        break;
      case '--config':
        args.configPath = String(next || '').trim();
        i += 1;
        break;
      case '--provider':
        args.providerName = String(next || '').trim();
        i += 1;
        break;
      case '--dry-run':
        args.dryRun = true;
        break;
      case '--force':
      case '--force-retranslate':
        args.force = true;
        break;
      case '--write':
        args.write = true;
        break;
      case '--allow-mock-write':
        args.allowMockWrite = true;
        break;
      case '--cleanup-only':
        args.cleanupOnly = true;
        break;
      case '--rewrite-links':
        args.rewriteLinks = true;
        break;

/**
 * @script            docs-json-localizer
 * @category          utility
 * @purpose           feature:translation
 * @scope             tools/scripts
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement docs.json localiser engine — transforms docs.json navigation for locale variants
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/scripts/i18n/lib/docs-json-localizer.js [flags]
 */
const fs = require('fs');
const path = require('path');
const { chunkArray } = require('./common');
const { normalizeRouteKey } = require('./path-utils');
const { protectText, restoreProtectedText } = require('./mdx-translate');

const MOCK_LABEL_PREFIX_RE = /^\[[a-z]{2,5}(?:-[A-Z]{2})?\]\s+/;

function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}

function normalizeLanguageAlias(language, languageCodeMap = {}) {
  const raw = String(language || '').trim();
  if (!raw) return '';
  if (typeof languageCodeMap[raw] === 'string' && languageCodeMap[raw].trim()) return languageCodeMap[raw].trim();
  const lower = raw.toLowerCase();
  for (const [key, value] of Object.entries(languageCodeMap || {})) {
    if (String(key).toLowerCase() === lower && String(value || '').trim()) return String(value).trim();
  }
  return raw;
}

function collectLabelFields(node, labelKeys, out = []) {
  if (Array.isArray(node)) {
    node.forEach((item) => collectLabelFields(item, labelKeys, out));
    return out;
  }
  if (!node || typeof node !== 'object') return out;

  for (const key of Object.keys(node)) {
    if (labelKeys.has(key) && typeof node[key] === 'string' && node[key].trim() && node[key].trim() !== ' ') {
      out.push({ target: node, key, value: node[key] });
    }
    collectLabelFields(node[key], labelKeys, out);
  }
  return out;
}

function detectMockPrefixedLabels(node, labelKeys) {
  const labels = collectLabelFields(node, labelKeys);
  const matches = [];
  for (const label of labels) {
    const value = String(label.target?.[label.key] || '');
    if (MOCK_LABEL_PREFIX_RE.test(value)) {
      matches.push({
        key: label.key,
        value
      });
    }
  }
  return matches;
}

function normalizeArtifactClass(entry) {
  const explicit = String(entry?.artifactClass || '').trim();
  if (explicit) return explicit;
  const provider = String(entry?.provider || '').trim().toLowerCase();
  if (provider === 'mock') return 'translated_mock';
  if (provider) return 'translated_real';
  return 'existing_unknown';
}

function buildRouteMapIndex(routeMapEntries) {
  const index = new Map();
  for (const rawEntry of routeMapEntries || []) {
    const status = String(rawEntry.status || '').trim();
    if (status && !['translated', 'unchanged_write', 'skipped_up_to_date', 'existing', 'translated_dry_run'].includes(status)) {
      continue;
    }
    const sourceRoute = normalizeRouteKey(rawEntry.sourceRoute);
    const language = String(rawEntry.effectiveLanguage || rawEntry.language || '').trim();
    const localizedRoute = normalizeRouteKey(rawEntry.localizedRoute);
    if (!sourceRoute || !language || !localizedRoute) continue;
    const entry = {
      ...rawEntry,
      sourceRoute,
      language,
      localizedRoute,
      effectiveLanguage: String(rawEntry.effectiveLanguage || rawEntry.language || '').trim(),
      requestedLanguage: String(rawEntry.requestedLanguage || ''),
      localizedRouteStyle: String(rawEntry.localizedRouteStyle || ''),
      provider: String(rawEntry.provider || '').trim().toLowerCase(),
      modelUsed: String(rawEntry.modelUsed || ''),
      provenanceKind: String(rawEntry.provenanceKind || ''),
      artifactClass: normalizeArtifactClass(rawEntry)
    };
    if (!index.has(sourceRoute)) index.set(sourceRoute, new Map());
    index.get(sourceRoute).set(language, entry);
  }
  return index;
}

function shouldPreservePageEntry(value) {
  const trimmed = String(value || '').trim();
  if (!trimmed || trimmed === ' ') return true;
  if (/^(https?:\/\/|mailto:|#)/i.test(trimmed)) return true;
  return false;
}

function buildStats() {
  return {
    rewrittenRoutes: 0,
    fallbackRoutes: 0,
    fallbackRoutesWithinSelectedScope: 0,
    fallbackRoutesOutsideSelectedScope: 0,
    rewrittenRoutesFromMockArtifacts: 0,
    blockedMockArtifactRoutes: 0,
    fallbackByLocation: new Map()
  };
}

function trimLabel(value) {
  const text = String(value || '').trim();
  return text || '';
}

function locationKeyFromTrail(trail = {}) {
  const tab = trimLabel(trail.tab) || '(tab:unknown)';
  const anchor = trimLabel(trail.anchor) || '(anchor:unknown)';
  const group = trimLabel(trail.group) || '(group:ungrouped)';
  return `${tab} > ${anchor} > ${group}`;
}

function recordFallback(stats, context, trail, sourceRoute) {
  stats.fallbackRoutes += 1;
  const selectedSet = context.selectedScopeRoutes;
  if (selectedSet && selectedSet.size > 0) {
    if (selectedSet.has(sourceRoute)) stats.fallbackRoutesWithinSelectedScope += 1;
    else stats.fallbackRoutesOutsideSelectedScope += 1;
  } else {
    stats.fallbackRoutesOutsideSelectedScope += 1;
  }

  const key = locationKeyFromTrail(trail);
