/**
 * @script            provider-openrouter
 * @category          utility
 * @purpose           feature:translation
 * @scope             tools/scripts
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement OpenRouter translation provider — calls OpenRouter API for actual translations
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/scripts/i18n/lib/provider-openrouter.js [flags]
 */
const { chunkArray } = require('./common');

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function assertOpenRouterConfig(config) {
  if (!config || typeof config !== 'object') throw new Error('Missing OpenRouter config');
  const models = config.modelCandidates || [];
  if (!Array.isArray(models) || models.length === 0) {
    throw new Error('OpenRouter modelCandidates must be a non-empty array');
  }
}

function getOpenRouterAuthHeaders(config = {}) {
  const apiKey = process.env.OPENROUTER_API_KEY || '';
  if (!apiKey) {
    throw new Error('OPENROUTER_API_KEY is required');
  }
  const headers = {
    Authorization: `Bearer ${apiKey}`,
    'Content-Type': 'application/json'
  };
  const referer = process.env.OPENROUTER_HTTP_REFERER || process.env.GITHUB_SERVER_URL || '';
  if (referer) headers['HTTP-Referer'] = referer;
  const title = process.env.OPENROUTER_APP_NAME || 'livepeer-docs-i18n';
  if (title) headers['X-Title'] = title;
  return headers;
}

function buildPromptMessages({ language, kind, segments, rules }) {
  const preserveTerms = (rules?.preserveBrandTerms || []).join(', ');
  const system = [
    'You translate documentation text while preserving Markdown/MDX syntax and placeholders.',
    'Return strict JSON only.',
    'Do not translate URLs, routes, code syntax, placeholders, or brand/product names that must be preserved.',
    preserveTerms ? `Preserve these exact terms: ${preserveTerms}` : ''
  ]
    .filter(Boolean)
    .join(' ');

  const userPayload = {
    task: 'translate_segments',
    language,
    kind,
    instructions: [
      'Return a JSON object with key "segments".',
      'segments must be an array of objects with keys: id, text.',
      'Preserve ids exactly and keep segment count unchanged.',
      'Preserve placeholders like __I18N_PH_#__ exactly.'
    ],
    segments: segments.map((segment) => ({ id: segment.id, text: segment.text }))
  };

  return [
    { role: 'system', content: system },
    { role: 'user', content: JSON.stringify(userPayload) }
  ];
}

function parseJsonFromModelContent(content) {
  const raw = String(content || '').trim();
  if (!raw) throw new Error('OpenRouter response content was empty');
  try {
    return JSON.parse(raw);
  } catch (_err) {
    const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
    if (fenced) {
      return JSON.parse(fenced[1]);
    }
    const objectStart = raw.indexOf('{');
    const objectEnd = raw.lastIndexOf('}');
    if (objectStart >= 0 && objectEnd > objectStart) {
      return JSON.parse(raw.slice(objectStart, objectEnd + 1));
    }
    throw new Error('OpenRouter response was not valid JSON');
  }
}

function validateSegmentResponse(payload, requestSegments) {
  const responseSegments = payload?.segments;
  if (!Array.isArray(responseSegments)) {
    throw new Error('OpenRouter JSON response missing segments array');
  }
  if (responseSegments.length !== requestSegments.length) {
    throw new Error(`Segment count mismatch: expected ${requestSegments.length}, received ${responseSegments.length}`);
  }

  const byId = new Map();
  responseSegments.forEach((segment) => {
    byId.set(String(segment?.id), String(segment?.text ?? ''));
  });

  return requestSegments.map((segment) => {
    const key = String(segment.id);
    if (!byId.has(key)) {
      throw new Error(`Missing translated segment id "${key}"`);
    }
    return { id: segment.id, text: byId.get(key) };
  });
}

async function requestCompletion({ config, model, messages }) {
  const controller = new AbortController();
  const timeoutMs = Number(config.requestTimeoutMs) || 60000;
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${config.baseUrl || 'https://openrouter.ai/api/v1'}/chat/completions`, {
      method: 'POST',
      headers: getOpenRouterAuthHeaders(config),
      signal: controller.signal,
      body: JSON.stringify({
        model,
        temperature: Number.isFinite(config.temperature) ? config.temperature : 0.1,
        messages,
        response_format: { type: 'json_object' }
      })
    });

    if (!response.ok) {
      const body = await response.text();
      const error = new Error(`OpenRouter request failed (${response.status}): ${body.slice(0, 500)}`);
      error.status = response.status;
      error.headers =
        response.headers && typeof response.headers.entries === 'function'
          ? Object.fromEntries(response.headers.entries())
          : {};
      throw error;
    }

    const data = await response.json();
    const content = data?.choices?.[0]?.message?.content;
    return { data, content };
  } finally {
    clearTimeout(timer);
  }
}

function parseResetEpochMsFromError(error) {
  if (!error) return 0;
  const headers = error.headers || {};
  const headerReset = Number(headers['x-ratelimit-reset'] || headers['X-RateLimit-Reset'] || 0);
  if (Number.isFinite(headerReset) && headerReset > 0) {
    return headerReset > 1e12 ? headerReset : headerReset * 1000;
  }

  const message = String(error.message || '');
  const headerMatch = message.match(/X-RateLimit-Reset\\?":\\?"?(\d{10,13})"?/i);
  if (headerMatch) {
    const parsed = Number(headerMatch[1]);
    if (Number.isFinite(parsed) && parsed > 0) {
      return parsed > 1e12 ? parsed : parsed * 1000;
    }
  }
  return 0;
}

function getRetryDelayMs(error, attempt) {
  const status = Number(error?.status);
  const baseDelay = Math.min(30000, 2000 * 2 ** Math.max(0, attempt - 1));
  if (status !== 429) return baseDelay;

  const resetEpochMs = parseResetEpochMsFromError(error);
  if (resetEpochMs > 0) {
    const now = Date.now();
    const untilReset = resetEpochMs - now;
    if (untilReset > 0) {
      return Math.min(70000, untilReset + 750);
    }
  }
  return Math.min(60000, Math.max(baseDelay, 10000));
}

function isRetryableError(error) {
  if (!error) return false;
  if (error.name === 'AbortError') return true;
  const status = Number(error.status);
  const message = String(error.message || '');
  if (/OpenRouter response (content was empty|was not valid JSON)/i.test(message)) {
    return true;
  }
  if (/Segment count mismatch|Missing translated segment id/i.test(message)) {
    return true;
  }
  return status === 429 || (status >= 500 && status < 600);
}

function isModelFailoverError(error) {
  if (!error) return false;
  const status = Number(error.status);
  const message = String(error.message || '');
  if (/OpenRouter response (content was empty|was not valid JSON)/i.test(message)) {
    return true;
  }
  if (/Segment count mismatch|Missing translated segment id/i.test(message)) {
    return true;
  }
  if (
    status === 400 &&
    /(Developer instruction is not enabled|INVALID_ARGUMENT|response_format)/i.test(message)
  ) {
    return true;
  }
  // OpenRouter/provider-specific capacity or billing responses can be model/provider dependent.
  return status === 402 || status === 403 || status === 429 || (status >= 500 && status < 600);
}

function createOpenRouterTranslator(providerConfig, translationRules = {}) {
  assertOpenRouterConfig(providerConfig);

/**
 * @script            providers
 * @category          utility
 * @purpose           feature:translation
 * @scope             tools/scripts
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement Provider registry — selects translation provider (OpenRouter or mock) based on configuration
 * @pipeline          indirect — library module imported by other scripts, not invoked directly
 * @usage             node tools/scripts/i18n/lib/providers.js [flags]
 */
const { createOpenRouterTranslator } = require('./provider-openrouter');
const { createMockTranslator } = require('./provider-mock');

function createTranslator({ config, providerNameOverride = '' }) {
  const providerConfig = { ...(config.provider || {}) };
  const name = String(providerNameOverride || providerConfig.name || '').trim().toLowerCase();

  if (name === 'mock') {
    return createMockTranslator();
  }
  if (name === 'openrouter' || !name) {
    return createOpenRouterTranslator(providerConfig, config.translationRules || {});
  }

  throw new Error(`Unsupported i18n provider: ${name}`);
}

module.exports = { createTranslator };

#!/usr/bin/env node
/**
 * @script            test-mintlify-version-language-toggle
 * @category          enforcer
 * @purpose           feature:translation
 * @scope             tools/scripts/i18n, docs.json, v2
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement Mintlify language toggle checker — validates Mintlify version supports language toggle feature
 * @pipeline          manual — diagnostic/investigation tool, run on-demand only
 * @usage             node tools/scripts/i18n/test-mintlify-version-language-toggle.js [flags]
 */

const puppeteer = require('puppeteer');

function parseArgs(argv) {
  const args = {
    baseUrl: 'http://localhost:3000',
    timeoutMs: 120000,
    strictMenus: false
  };
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    const next = argv[i + 1];
    if (token === '--base-url') {
      args.baseUrl = String(next || args.baseUrl).trim();
      i += 1;
    } else if (token === '--timeout-ms') {
      const parsed = Number(next);
      if (Number.isFinite(parsed) && parsed > 0) args.timeoutMs = parsed;
      i += 1;
    } else if (token === '--strict-menus') {
      args.strictMenus = true;
    } else if (token === '--help' || token === '-h') {
      console.log(
        [
          'Usage: node tools/scripts/i18n/test-mintlify-version-language-toggle.js [options]',
          '',
          'Options:',
          '  --base-url <url>      Mint preview base URL (default http://localhost:3000)',
          '  --timeout-ms <n>      Navigation timeout (default 120000)',
          '  --strict-menus        Fail if menu contents cannot be confirmed in headless mode',
          '  --help, -h            Show help'
        ].join('\n')
      );
      process.exit(0);
    }
  }
  return args;
}

function buildTextMatchers(values) {
  return values.map((value) => String(value || '').trim()).filter(Boolean);
}

function textListContains(texts, expected) {
  const needle = String(expected || '').trim();
  if (!needle) return false;
  return texts.some((text) => {
    const value = String(text || '').trim();
    if (!value) return false;
    return value === needle || value.includes(needle) || value.startsWith(`${needle}\n`) || value.endsWith(`\n${needle}`);
  });
}

async function collectTexts(page, { visibleOnly = false } = {}) {
  return page.evaluate((opts) => {
    const els = Array.from(document.querySelectorAll('button,a,[role="menuitem"]'));
    const isVisible = (el) => {
      const rect = el.getBoundingClientRect();
      const styles = window.getComputedStyle(el);
      return rect.width > 0 && rect.height > 0 && styles.display !== 'none' && styles.visibility !== 'hidden';
    };
    return els
      .filter((el) => (opts.visibleOnly ? isVisible(el) : true))
      .map((el) => (el.innerText || el.textContent || '').trim())
      .filter(Boolean);
  }, { visibleOnly });
}

async function findVersionTriggerText(page) {
  return page.evaluate(() => {
    const btns = Array.from(document.querySelectorAll('button'));
    const isVisible = (el) => {
      const rect = el.getBoundingClientRect();
      const styles = window.getComputedStyle(el);
      return rect.width > 0 && rect.height > 0 && styles.display !== 'none' && styles.visibility !== 'hidden';
    };
    const trigger =
      btns.find((b) => isVisible(b) && /^(v1|v2)$/i.test((b.innerText || b.textContent || '').trim())) ||
      btns.find((b) => /^(v1|v2)$/i.test((b.innerText || b.textContent || '').trim()));
    return trigger ? (trigger.innerText || trigger.textContent || '').trim() : '';
  });
}

async function clickTrigger(page, patternSource) {
  return page.evaluate((source) => {
    const pattern = new RegExp(source, 'i');
    const btns = Array.from(document.querySelectorAll('button'));
    const isVisible = (el) => {
      const rect = el.getBoundingClientRect();
      const styles = window.getComputedStyle(el);
      return rect.width > 0 && rect.height > 0 && styles.display !== 'none' && styles.visibility !== 'hidden';
    };
    const btn =
      btns.find((b) => isVisible(b) && pattern.test((b.innerText || b.textContent || '').trim())) ||
      btns.find((b) => pattern.test((b.innerText || b.textContent || '').trim()));
    if (!btn) return { ok: false, text: '' };
    btn.click();
    return { ok: true, text: (btn.innerText || btn.textContent || '').trim() };
  }, patternSource);
}

async function clickVersionTrigger(page) {
  return clickTrigger(page, '^(v1|v2)$');
}

async function clickLanguageTrigger(page) {
  return clickTrigger(page, '(English|Espa\u00f1ol|Fran\u00e7ais|\u4e2d\u6587|Chinese|Spanish|French)');
}

function assertCondition(condition, message, failures) {
  if (!condition) failures.push(message);
}

function normalizeUrl(url) {
  return String(url || '').replace(/\/+$/, '');
}

function expectedTargetVersion(currentVersion) {
  return currentVersion === 'v2' ? 'v1' : 'v2';
}

async function maybeAssertMenuItems({ scenario, page, failures, warnings, strictMenus }) {
  const versionClick = await clickVersionTrigger(page);
  if (!versionClick.ok) {
    if (strictMenus) failures.push(`${scenario.name}: version trigger not found for menu check`);
    else warnings.push(`${scenario.name}: version trigger menu could not be opened in headless preview`);
    return;
  }
  await new Promise((r) => setTimeout(r, 500));
  const menuTexts = await collectTexts(page);
  const expectedItems = buildTextMatchers(scenario.requiredVersionMenuItems || []);
  for (const item of expectedItems) {
    if (!textListContains(menuTexts, item)) {
      if (strictMenus) failures.push(`${scenario.name}: version menu missing "${item}"`);
      else warnings.push(`${scenario.name}: could not confirm version menu item "${item}" in headless preview`);
    }
  }
}

async function maybeAssertLanguageItems({ scenario, page, failures, warnings, strictMenus }) {
  const languageClick = await clickLanguageTrigger(page);
  if (!languageClick.ok) {
    if (strictMenus) failures.push(`${scenario.name}: language trigger not found`);
    else warnings.push(`${scenario.name}: language trigger could not be opened in headless preview`);
    return;
  }
  await new Promise((r) => setTimeout(r, 500));
  const menuTexts = await collectTexts(page);
  const expectedItems = buildTextMatchers(scenario.requiredLanguageMenuItems || []);
  for (const item of expectedItems) {
    if (!textListContains(menuTexts, item)) {
      if (strictMenus) failures.push(`${scenario.name}: language menu missing "${item}"`);
      else warnings.push(`${scenario.name}: could not confirm language menu item "${item}" in headless preview`);
    }
  }
}

async function tryVersionSwitch(page, scenario, failures, warnings, timeoutMs, strictMenus) {
  const currentVersion = scenario.expectedVersionTrigger;
  const targetVersion = expectedTargetVersion(currentVersion);
  const versionClick = await clickVersionTrigger(page);
  if (!versionClick.ok) {
    if (strictMenus) failures.push(`${scenario.name}: version trigger not found for switch attempt`);
    else warnings.push(`${scenario.name}: version switch not attempted (trigger not found in headless preview)`);
    return null;
  }
  await new Promise((r) => setTimeout(r, 500));
  const targetClicked = await page.evaluate((target) => {
    const nodes = Array.from(document.querySelectorAll('button,a,[role="menuitem"]'));
    const isVisible = (el) => {
      const rect = el.getBoundingClientRect();
      const styles = window.getComputedStyle(el);
      return rect.width > 0 && rect.height > 0 && styles.display !== 'none' && styles.visibility !== 'hidden';
    };
    const pick =
      nodes.find((node) => isVisible(node) && new RegExp(`^${target}$`, 'i').test((node.innerText || node.textContent || '').trim())) ||
      nodes.find((node) => new RegExp(`^${target}$`, 'i').test((node.innerText || node.textContent || '').trim()));
    if (!pick) return false;
    pick.click();
    return true;
  }, targetVersion);

  if (!targetClicked) {
    if (strictMenus) failures.push(`${scenario.name}: could not click version menu item ${targetVersion}`);
    else warnings.push(`${scenario.name}: could not click version menu item ${targetVersion} in headless preview`);
    return null;
  }

  try {
    await page.waitForNavigation({ waitUntil: 'networkidle2', timeout: timeoutMs });
  } catch {
    await new Promise((r) => setTimeout(r, 1200));
  }

  const switchedUrl = page.url();
  if (!String(switchedUrl).includes(`/${targetVersion}/`)) {
    failures.push(`${scenario.name}: version switch did not navigate to /${targetVersion}/ (got ${switchedUrl})`);
  }
  return switchedUrl;
}

async function runScenario(page, scenario, failures, warnings, timeoutMs, strictMenus) {
  const pageErrors = [];
  page.removeAllListeners('pageerror');
  page.on('pageerror', (err) => pageErrors.push(err.message));

  await page.goto(scenario.url, { waitUntil: 'networkidle2', timeout: timeoutMs });
  await new Promise((r) => setTimeout(r, 800));

