test('createOpenRouterTranslator fails over across models and returns final modelUsed', async () => {
  const originalFetch = global.fetch;
  const originalApiKey = process.env.OPENROUTER_API_KEY;
  let callCount = 0;
  global.fetch = async (_url, options) => {
    callCount += 1;
    const body = JSON.parse(String(options.body || '{}'));
    if (body.model === 'bad/model:free') {
      return {
        ok: false,
        status: 400,
        text: async () => '{"error":{"message":"Developer instruction is not enabled"}}'
      };
    }
    return {
      ok: true,
      json: async () => ({
        choices: [
          {
            message: {
              content: JSON.stringify({
                segments: [{ id: 0, text: 'hola' }]
              })
            }
          }
        ]
      })
    };
  };

  process.env.OPENROUTER_API_KEY = process.env.OPENROUTER_API_KEY || 'test-key';

  try {
    const translator = createOpenRouterTranslator(
      {
        modelCandidates: ['bad/model:free', 'good/model:free'],
        baseUrl: 'https://example.invalid',
        maxRetriesPerRequest: 1,
        requestTimeoutMs: 1000,
        temperature: 0.1
      },
      {}
    );
    const result = await translator.translateStrings({ language: 'es', strings: ['hello'] });
    assert.deepEqual(result.strings, ['hola']);
    assert.equal(result.modelUsed, 'good/model:free');
    assert.equal(callCount, 2);
  } finally {
    global.fetch = originalFetch;
    if (originalApiKey === undefined) delete process.env.OPENROUTER_API_KEY;
    else process.env.OPENROUTER_API_KEY = originalApiKey;
  }
});

#!/usr/bin/env node
/**
 * @script            translate-docs
 * @category          generator
 * @purpose           feature:translation
 * @scope             tools/scripts/i18n, docs.json, v2
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement Translation generator — translates v2 MDX pages to target languages via OpenRouter API
 * @pipeline          P6 (on-demand, translation pipeline)
 * @usage             node tools/scripts/i18n/translate-docs.js [flags]
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { buildRuntimeOptions, loadI18nConfig, parseCommonCliArgs } = require('./lib/config');
const { buildV2EnglishRouteInventory, collectExistingLocalizedRouteMapEntries, selectScopeItems } = require('./lib/docs-routes');
const { parseMdxFileWithFrontmatter, translateFrontmatterFields } = require('./lib/frontmatter');
const { rewriteInternalLinksInBody, rewriteInternalLinksInJsx, translateMdxBody } = require('./lib/mdx-translate');
const { repoFileRelToLocalizedFileRel, normalizeRouteKey } = require('./lib/path-utils');
const {
  buildProvenanceComment,
  classifyLocalizedArtifactProvenance,
  injectOrReplaceProvenanceComment,
  parseProvenanceComment,
  sha256
} = require('./lib/provenance');
const { hasGeneratedNote, removeGeneratedNotes } = require('../../lib/generated-file-banners');
const { createTranslator } = require('./lib/providers');
const { getRepoRoot, normalizeRepoRel, writeJson, writeTextIfChanged } = require('./lib/common');

function printHelp() {
  console.log(
    [
      'Usage: node tools/scripts/i18n/translate-docs.js [options]',
      '',
      'Options:',
      '  --languages <csv>            Target languages (default from tools/i18n/config.json)',
      '  --scope-mode <mode>          changed_since_ref | prefixes | paths_file | full_v2_nav',
      '  --base-ref <ref>             Base ref for changed_since_ref mode',
      '  --prefixes <csv>             Repo prefixes for prefixes mode',
      '  --paths-file <path>          File containing explicit routes/files (paths_file mode)',
      '  --max-pages <n>              Max selected pages to process',
      '  --max-concurrency <n>        Max concurrent source files to translate (capped at 5)',
      '  --provider <name>            openrouter | mock',
      '  --dry-run                    Do not write localized files',
      '  --force                      Retranslate even when source hash matches',
      '  --allow-mock-write           Allow mock provider in non-dry runs (dangerous; testing only)',
      '  --route-map <path>           Write route-map artifact JSON',
      '  --report-json <path>         Write run report JSON',
      '  --cleanup-only               Skip translation and only run cleanup/link rewrite',
      '  --rewrite-links              Rewrite internal links for localized files (default true in cleanup-only)',
      '  --rewrite-scope <mode>       all | moved (default all for cleanup-only)',
      '  --config <path>              Alternate i18n config JSON',
      '  --help, -h                   Show this help'
    ].join('\n')
  );
}

function isMockWriteBlocked({ translator, runtime, config }) {
  if (translator?.name !== 'mock') return false;
  if (runtime.dryRun) return false;
  if (runtime.allowMockWrite) return false;
  if (config?.qualityGates?.blockMockProviderWrites === false) return false;
  return true;
}

function assertMockWriteAllowed({ translator, runtime, config, action }) {
  if (!isMockWriteBlocked({ translator, runtime, config })) return;
  throw new Error(
    [
      `Refusing to run ${action} with mock provider in write mode.`,
      'The mock provider prefixes content (for smoke tests) and can contaminate localized MDX/docs.json.',
      'Use --dry-run for mock provider smoke tests, or pass --allow-mock-write only for deliberate fixture generation.'
    ].join(' ')
  );
}

function artifactClassForProvider(providerName) {
  return String(providerName || '').trim().toLowerCase() === 'mock' ? 'translated_mock' : 'translated_real';
}

function requestedLanguageForEffective(runtime, effectiveLanguage) {
  const hit = (runtime.languageAliasesApplied || []).find((entry) => entry.effectiveLanguage === effectiveLanguage);
  return hit?.requestedLanguage || effectiveLanguage;
}

function buildRouteMapIndex(entries) {
  const index = new Map();
  for (const entry of entries) {
    const sourceRoute = normalizeRouteKey(entry.sourceRoute);
    const language = String(entry.effectiveLanguage || entry.language || '').trim();
    const localizedRoute = normalizeRouteKey(entry.localizedRoute);
    if (!sourceRoute || !language || !localizedRoute) continue;
    if (!index.has(sourceRoute)) index.set(sourceRoute, new Map());
    index.get(sourceRoute).set(language, localizedRoute);
  }
  return index;
}

function normalizeFileKey(value) {
  return normalizeRepoRel(String(value || '').replace(/\\/g, '/'));
}

function normalizeMaxConcurrency(value, fallback = 5) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
  return Math.min(parsed, fallback);
}

function chunkArray(items, size) {
  if (!Array.isArray(items) || items.length === 0) return [];
  const normalized = normalizeMaxConcurrency(size);
  const batches = [];
  for (let i = 0; i < items.length; i += normalized) {
    batches.push(items.slice(i, i + normalized));
  }
  return batches;
}

function isQuarantinedLocalizedFile(localizedFile) {
  const normalized = normalizeFileKey(localizedFile);
  return /^v2\/[^/]+\/group\/x-orphaned\//.test(normalized);
}

function resolveSolutionsEquivalent(localizedFile) {
  const normalized = normalizeFileKey(localizedFile);
  if (!normalized.includes('/platforms/')) return '';
  let next = normalized.replace('/platforms/', '/solutions/');
  if (next.endsWith('/ecosystem-products.mdx')) {
    next = next.replace('/ecosystem-products.mdx', '/solution-providers.mdx');
  }
  if (next.endsWith('/ecosystem-products.md')) {
    next = next.replace('/ecosystem-products.md', '/solution-providers.md');
  }
  return next;
}

function resolveOrphanQuarantinePath(localizedFile, language) {
  const normalized = normalizeFileKey(localizedFile);
  if (!normalized.startsWith('v2/')) return '';
  const parts = normalized.split('/');
  const lang = parts[1] || String(language || '').trim();
  const suffix = parts.slice(2).join('/');
  if (!lang || !suffix) return '';
  return `v2/${lang}/group/x-orphaned/${suffix}`;
}

function resolveQuarantineBasePath(localizedFile, language) {
  const normalized = normalizeFileKey(localizedFile);
  if (isQuarantinedLocalizedFile(normalized)) return normalized;
  return resolveOrphanQuarantinePath(normalized, language);
}

function moveLocalizedToQuarantine({ repoRoot, localizedFile, language, reason }) {
  const normalized = normalizeFileKey(localizedFile);
  const absPath = path.join(repoRoot, normalized);
  if (!fs.existsSync(absPath)) {
    return { movedTo: '', warning: `${reason} (missing file): ${localizedFile}` };
  }
  const basePath = resolveQuarantineBasePath(normalized, language);
  if (!basePath) {
    return { movedTo: '', warning: `${reason} (invalid quarantine path): ${localizedFile}` };
  }
  const raw = fs.readFileSync(absPath, 'utf8');
  const hash = sha256(`${normalized}:${raw}`).slice(0, 8);
  let target = basePath;
  const targetAbs = path.join(repoRoot, target);
  const hadCollision = fs.existsSync(targetAbs);
  fs.mkdirSync(path.dirname(targetAbs), { recursive: true });
  const forceFlag = hadCollision ? '-f ' : '';
  execSync(`git -C ${JSON.stringify(repoRoot)} mv ${forceFlag}${JSON.stringify(normalized)} ${JSON.stringify(target)}`, {
    stdio: 'ignore'
  });
  const collisionNote = hadCollision ? ` (replaced existing ${hash})` : '';
  return { movedTo: target, warning: `${reason}: ${localizedFile} -> ${target}${collisionNote}` };
}

function findRenameTarget(repoRoot, sourcePath) {
  if (!sourcePath) return '';
  try {
    const output = execSync(
      `git -C ${JSON.stringify(repoRoot)} log --follow --name-status --diff-filter=R -- ${JSON.stringify(sourcePath)}`,
      { encoding: 'utf8' }
    );
    for (const line of output.split('\n')) {
      if (!line.startsWith('R')) continue;
      const parts = line.split('\t');
      if (parts.length >= 3) {
        return normalizeRepoRel(parts[2]);
      }
    }
  } catch (_err) {
    return '';
  }
  return '';
}

const STATIC_RENAME_MAP = new Map(
  [
    [
      'v2/gateways/run-a-gateway/quickstart/get-AI-to-setup-the-gateway.mdx',
      'v2/gateways/quickstart/AI-prompt.mdx'
    ],
    [
      'v2/gateways/run-a-gateway/quickstart/quickstart-a-gateway.mdx',
      'v2/gateways/quickstart/gateway-setup.mdx'
    ],
    [
      'v2/gateways/references/artibtrum-exchanges.mdx',
      'v2/gateways/references/arbitrum-exchanges.mdx'
    ],
    [
      'v2/developers/livepeer-real-time-video/video-streaming-on-livepeer/README.mdx',
      'v2/developers/quickstart/video/video-streaming.mdx'
    ]
  ].map(([from, to]) => [normalizeRepoRel(from), normalizeRepoRel(to)])
);

#!/usr/bin/env node
/**
 * @script            validate-generated
 * @category          validator
 * @purpose           feature:translation
 * @scope             tools/scripts/i18n, v2
 * @owner             docs
 * @needs             F-R6, F-R7
 * @purpose-statement Generated localisation validator — checks generated translated MDX files and route-map outputs for integrity
 * @pipeline          P6
 * @usage             node tools/scripts/i18n/validate-generated.js [flags]
 */

const fs = require('fs');
const path = require('path');
const { parseCommonCliArgs, loadI18nConfig, buildRuntimeOptions } = require('./lib/config');
const { getRepoRoot, readJson, writeJson } = require('./lib/common');
const { collectExistingLocalizedRouteMapEntries } = require('./lib/docs-routes');
const { parseMdxFileWithFrontmatter } = require('./lib/frontmatter');
const { parseMdx } = require('./lib/mdx-parser');
const { parseProvenanceComment, classifyLocalizedArtifactProvenance } = require('./lib/provenance');

function printHelp() {
  console.log(
    [
      'Usage: node tools/scripts/i18n/validate-generated.js [options]',
      '',
      'Options:',
      '  --languages <csv>              Languages to validate (default from config)',
      '  --route-map <path>             Validate only entries from route-map artifact',
      '  --report-json <path>           Write validation report JSON',
      '  --fail-on-mock-artifacts       Exit non-zero if generated files contain mock provenance',
      '  --fail-on-missing-provenance   Exit non-zero if generated files are missing codex-i18n provenance',
      '  --config <path>                Alternate i18n config JSON',
      '  --help, -h                     Show this help'
    ].join('\n')
  );
}

function loadEntries(repoRoot, routeMapPath, config, runtime) {
  if (routeMapPath) {
    const abs = path.resolve(repoRoot, routeMapPath);
    const parsed = readJson(abs);
    return { path: abs, entries: Array.isArray(parsed.entries) ? parsed.entries : [] };
  }
  return {
    path: '',
    entries: collectExistingLocalizedRouteMapEntries(repoRoot, config.generatedRoot, {
      generatedPathStyle: config.generatedPathStyle,
      sourceRoot: config.sourceRoot,
      knownLanguages: runtime.languages
    })
  };
}

async function run(argv = process.argv.slice(2)) {
  const cliArgs = parseCommonCliArgs(argv);
  if (cliArgs.help || argv.includes('--help') || argv.includes('-h')) {
    printHelp();
    return { help: true };
  }
  const { repoRoot, config } = loadI18nConfig({
    repoRoot: getRepoRoot(),
    configPath: cliArgs.configPath || undefined
  });
  const runtime = buildRuntimeOptions(cliArgs, config);
  const routeMap = loadEntries(repoRoot, cliArgs.routeMapPath, config, runtime);
  const languageSet = new Set(runtime.languages.length ? runtime.languages : config.targetLanguages);

  const entries = routeMap.entries.filter(
    (entry) =>
      languageSet.has(entry.language) &&
      ['translated', 'unchanged_write', 'skipped_up_to_date', 'existing'].includes(entry.status)
  );

  const report = {
    generatedAt: new Date().toISOString(),
    checked: 0,
    failures: [],
    mockArtifactsDetected: 0,
    artifactsMissingProvenance: 0,
    provenanceParseFailures: 0,
    samples: []
  };

  function pushSample(type, payload) {
    if (report.samples.length >= 20) return;
    report.samples.push({ type, ...payload });
  }

  for (const entry of entries) {
    const rel = entry.localizedFile || `${entry.localizedRoute}.mdx`;
    const abs = path.join(repoRoot, rel);
    report.checked += 1;
    try {
      const raw = fs.readFileSync(abs, 'utf8');
      const provenance = parseProvenanceComment(raw);
      const hasProvenanceMarker = raw.includes('codex-i18n:');
      if (!provenance) {
        if (hasProvenanceMarker) {
          report.provenanceParseFailures += 1;
          pushSample('provenance_parse_failure', { localizedFile: rel, language: entry.language });
        } else {
          report.artifactsMissingProvenance += 1;
          pushSample('missing_provenance', { localizedFile: rel, language: entry.language });
        }
      } else {
        const meta = classifyLocalizedArtifactProvenance(provenance);
        if (meta.artifactClass === 'translated_mock') {
          report.mockArtifactsDetected += 1;
          pushSample('mock_artifact', { localizedFile: rel, language: entry.language, provider: meta.provider });
        }
      }
      const parsed = parseMdxFileWithFrontmatter(raw);
      await parseMdx(parsed.body);
    } catch (error) {
      report.failures.push({
        localizedFile: rel,
        language: entry.language,
        sourceRoute: entry.sourceRoute,
        error: error.message
      });
    }
  }

  if (runtime.reportJsonPath) {
    writeJson(path.resolve(repoRoot, runtime.reportJsonPath), report);
  }

  console.log(
    [
      'i18n validate-generated summary',
      `- checked: ${report.checked}`,
      `- failures: ${report.failures.length}`,
      `- mock artifacts: ${report.mockArtifactsDetected}`,
      `- missing provenance: ${report.artifactsMissingProvenance}`,
      `- provenance parse failures: ${report.provenanceParseFailures}`
    ].join('\n')
  );

  if (report.failures.length > 0) {
    throw new Error(`Generated MDX validation failed for ${report.failures.length} file(s)`);
  }
  if (runtime.failOnMockArtifacts && report.mockArtifactsDetected > 0) {
    throw new Error(`Generated validation found ${report.mockArtifactsDetected} mock artifact(s)`);
  }
  if (runtime.failOnMissingProvenance && report.artifactsMissingProvenance > 0) {
    throw new Error(`Generated validation found ${report.artifactsMissingProvenance} file(s) missing provenance`);
  }

  return report;
}

if (require.main === module) {
  run().catch((error) => {
    console.error(`❌ ${error.message}`);
    process.exit(1);
  });
}

module.exports = { run };

#!/usr/bin/env node
/**
 * @script            new-script
 * @category          generator
 * @purpose           qa:repo-health
 * @scope             tools/scripts, tests/unit/script-docs.test.js
 * @owner             docs
 * @needs             E-C1, R-R14
 * @purpose-statement Script scaffolder — creates a new script file prefilled with the required docs header template
 * @pipeline          manual — interactive developer tool, not suited for automated pipelines
 * @usage             node tools/scripts/new-script.js [flags]
 */

const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const ROOT = process.cwd();

function argValue(name) {
  const idx = args.indexOf(name);
  if (idx === -1) return '';
  return args[idx + 1] || '';
}

function usage() {
  console.log('Usage: node tools/scripts/new-script.js --path <repo-relative-path> [--owner <value>] [--summary <value>] [--scope <value>]');
}

function usageDefault(filePath) {
  if (filePath.endsWith('.sh') || filePath.endsWith('.bash')) return `bash ${filePath}`;
  if (filePath.endsWith('.py')) return `python3 ${filePath}`;
  return `node ${filePath}`;
}

function hashTemplate(params) {
  const cmd = usageDefault(params.filePath);
  const lines = [
    '# @script ' + params.scriptName,
    '# @summary ' + params.summary,
    '# @owner ' + params.owner,
    '# @scope ' + params.scope,
    '#',
    '# @usage',
    '#   ' + cmd,
    '#',
    '# @inputs',
    '#   TODO: --flag <description> (default: ...)',
    '#',
    '# @outputs',
    '#   - TODO: output file/path/side effect',
    '#',
    '# @exit-codes',
    '#   0 = success',
    '#   1 = failure',
    '#',
    '# @examples',
    '#   ' + cmd,
    '#',
    '# @notes',
    '#   TODO: caveats, constraints, safety notes',
    ''
  ];
  return lines.join('\n');
}

function blockTemplate(params) {
  const cmd = usageDefault(params.filePath);
  const lines = [
    '/**',
    ` * @script ${params.scriptName}`,
    ` * @summary ${params.summary}`,
    ` * @owner ${params.owner}`,
    ` * @scope ${params.scope}`,
    ' *',
    ' * @usage',
    ` *   ${cmd}`,
    ' *',
    ' * @inputs',
    ' *   TODO: --flag <description> (default: ...)',
    ' *',
    ' * @outputs',
    ' *   - TODO: output file/path/side effect',
    ' *',
    ' * @exit-codes',
    ' *   0 = success',
    ' *   1 = failure',
    ' *',
    ' * @examples',
    ` *   ${cmd}`,
    ' *',
    ' * @notes',
    ' *   TODO: caveats, constraints, safety notes',
    ' */',
    ''
  ];
  return lines.join('\n');
}

function createContent(filePath, owner, summary, scope) {
  const ext = path.extname(filePath).toLowerCase();
  const scriptName = path.basename(filePath, ext);
  const params = { filePath, owner, summary, scope, scriptName };
  const hashStyle = ext === '.sh' || ext === '.bash' || ext === '.py';

  let shebang = '';
  if (ext === '.sh' || ext === '.bash') shebang = '#!/usr/bin/env bash\n';
  if (ext === '.py') shebang = '#!/usr/bin/env python3\n';
  if (ext === '.js' || ext === '.mjs' || ext === '.cjs') shebang = '#!/usr/bin/env node\n';

  const template = hashStyle ? hashTemplate(params) : blockTemplate(params);
  return `${shebang}${template}`;
}

function main() {
  const filePath = argValue('--path');
  if (!filePath) {
    usage();
    process.exit(1);
  }

  const normalized = filePath.split(path.sep).join('/');
  const fullPath = path.join(ROOT, normalized);
  if (fs.existsSync(fullPath)) {
    console.error(`❌ File already exists: ${normalized}`);
    process.exit(1);
  }

  const owner = argValue('--owner') || 'docs';
  const summary = argValue('--summary') || 'TODO: one-line purpose';
  const scope = argValue('--scope') || path.dirname(normalized);
  const content = createContent(normalized, owner, summary, scope);

  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, content, 'utf8');

  console.log(`✅ Created ${normalized}`);
  console.log('Fill all TODO values before committing.');
}

main();

