    if (token === '--strict') {
      out.strict = true;
      continue;
    }
    if (token === '--category') {
      const raw = String(argv[i + 1] || '').trim();
      if (!raw) {
        throw new Error('Missing --category value');
      }
      out.categories = new Set(
        raw
          .split(',')
          .map((part) => part.trim())
          .filter(Boolean)
      );
      i += 1;
      continue;
    }
    if (token.startsWith('--category=')) {
      const raw = token.slice('--category='.length).trim();
      out.categories = new Set(
        raw
          .split(',')
          .map((part) => part.trim())
          .filter(Boolean)
      );
      continue;
    }
