function getTagValue(header, tagName) {
  const pattern = new RegExp(`\\${tagName}\\s+(.+)`);
  const match = header.match(pattern);
  return match ? match[1].trim() : '';
}

function getSectionLines(header, tagName) {
  const lines = String(header || '').split('\n');
  const tagToken = tagName.replace('@', '');
  const start = lines.findIndex((line) => line.includes(`@${tagToken}`));
  if (start === -1) return [];

  const values = [];
  for (let index = start + 1; index < lines.length; index += 1) {
    const line = lines[index].trim();
    if (!line) continue;
    const stripped = line.replace(/^\*\s?/, '').replace(/^#\s?/, '').trim();
    if (!stripped) continue;
    if (stripped.startsWith('@')) break;
    if (stripped === '/**' || stripped === '*/') continue;
    values.push(stripped);
  }
  return values;
}

