async function verifyPage(paths, name) {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  const page = await browser.newPage();
  const errors = [];
  const warnings = [];

  page.on('console', msg => {
    const text = msg.text();
    if (msg.type() === 'error') {
      errors.push(text);
    } else if (msg.type() === 'warning') {
      warnings.push(text);
    }
  });

  page.on('pageerror', error => {
    errors.push(error.toString());
  });

  try {
    console.log(`\n🔍 Verifying: ${name}`);
    const pathCandidates = Array.isArray(paths) ? paths : [paths];
    let lastErrors = [];

    for (const pathCandidate of pathCandidates) {
      const url = `${BASE_URL}${pathCandidate}`;
      console.log(`   URL: ${url}`);

      const response = await page.goto(url, { waitUntil: 'networkidle2', timeout: 30000 });
      await new Promise(resolve => setTimeout(resolve, 5000));

      const title = await page.title().catch(() => '');
      const bodyText = await page.evaluate(() => {
        const body = document.body;
        if (!body) return '';
        return body.innerText || '';
      }).catch(() => '');

      const hasH1 = await page.$('h1') !== null;
      const hasContent = bodyText.length > 500;
      const is404 = title.includes('Page Not Found') || bodyText.includes('Page Not Found');
      const httpStatus = response.status();

      const realErrors = errors.filter(err => {
        const lower = err.toLowerCase();
        return !lower.includes('require is not defined') &&
               !lower.includes('puppeteer') &&
               !lower.includes('fs has already been declared') &&
               !lower.includes('unexpected token \'export\'') &&
               !lower.includes('identifier \'') &&
               !lower.includes('appendchild') &&
               !lower.includes('failed to execute') &&
               !lower.includes('403') &&
               !lower.includes('500') &&
               !lower.includes('favicon');
      });

      console.log(`   HTTP Status: ${httpStatus}`);
      console.log(`   Title: ${title.substring(0, 60)}`);
      console.log(`   Body Text Length: ${bodyText.length} chars`);
      console.log(`   Has H1: ${hasH1}`);
      console.log(`   Has Content: ${hasContent}`);
      console.log(`   Is 404: ${is404}`);
      console.log(`   Real Errors: ${realErrors.length}`);

      if (is404 || !hasContent || !hasH1 || httpStatus >= 400) {
        lastErrors = realErrors;
        continue;
      }

      if (realErrors.length > 0) {
        console.log(`   ⚠️  PAGE RENDERS BUT HAS ERRORS`);
        return { success: false, errors: realErrors, path: pathCandidate };
      }

      console.log(`   ✅ PAGE RENDERS CORRECTLY`);
      return { success: true, errors: [], path: pathCandidate };
    }

    console.log(`   ❌ PAGE NOT RENDERING`);
    return { success: false, errors: lastErrors };

  } catch (error) {
    console.log(`   ❌ ERROR: ${error.message}`);
    return { success: false, errors: [error.message] };
  } finally {
    await page.close();
    await browser.close();
  }
}

async function main() {
  console.log('🔍 Verifying ALL component library pages in browser...\n');

  const results = [];
  for (const pageSpec of PAGES) {
    const result = await verifyPage(pageSpec.paths, pageSpec.name);
    results.push({ ...pageSpec, ...result });
  }

  console.log('\n📊 Summary:');
  const passed = results.filter(r => r.success).length;
  const failed = results.filter(r => !r.success).length;
  console.log(`   ✅ Passed: ${passed}/${PAGES.length}`);
  console.log(`   ❌ Failed: ${failed}/${PAGES.length}`);

  if (failed > 0) {
    console.log('\n❌ Failed Pages:');
    results.filter(r => !r.success).forEach(r => {
      console.log(`   - ${r.name}: ${r.path || r.paths.join(' | ')}`);
      if (r.errors.length > 0) {
        console.log(`     Errors: ${r.errors.length}`);
        r.errors.slice(0, 2).forEach(err => {
          console.log(`       - ${err.substring(0, 150)}`);
        });
      }
    });
    process.exit(1);
  } else {
    console.log('\n✅ ALL PAGES RENDER CORRECTLY!');
    process.exit(0);
  }
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * @script            wcag-repair-common
 * @category          remediator
 * @purpose           qa:content-quality
 * @scope             tools/scripts, tests/integration, tasks/reports, v2
 * @owner             docs
 * @needs             E-R1, R-R11
 * @purpose-statement WCAG repair shared logic — common repair functions used by WCAG audit fix mode
 * @pipeline          manual — interactive developer tool, not suited for automated pipelines
 * @usage             node tools/scripts/wcag-repair-common.js [flags]
 */

const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const DEFAULT_REPORT_MD = path.join(REPO_ROOT, 'tasks', 'reports', 'quality-accessibility', 'v2-wcag-repair-common-report.md');
const DEFAULT_REPORT_JSON = path.join(REPO_ROOT, 'tasks', 'reports', 'quality-accessibility', 'v2-wcag-repair-common-report.json');

function parseWrapperArgs(argv) {
  const passThrough = [];
  let reportProvided = false;
  let reportJsonProvided = false;
  let modeSet = false;

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === '--help' || token === '-h') {
      return { help: true, argv: [] };
    }
    if (token === '--full' || token === '--staged') {
      modeSet = true;
      passThrough.push(token);
      continue;
    }
    if (token === '--files' || token === '--file') {
      passThrough.push(token);
      if (i + 1 < argv.length) {
        passThrough.push(argv[i + 1]);
        i += 1;
      }
      continue;
    }
    if (token === '--report') {
      reportProvided = true;
      passThrough.push(token);
      if (i + 1 < argv.length) {
        passThrough.push(argv[i + 1]);
        i += 1;
      }
      continue;
    }
    if (token === '--report-json') {
      reportJsonProvided = true;
      passThrough.push(token);
      if (i + 1 < argv.length) {
        passThrough.push(argv[i + 1]);
        i += 1;
      }
      continue;
    }
    // Pass through supported/shared flags transparently.
    passThrough.push(token);
  }

  const out = [];
  if (!modeSet) out.push('--full');
  out.push(...passThrough);

  // Default to applying safe fixes unless the caller explicitly disabled them.
  if (!out.includes('--fix') && !out.includes('--no-fix')) {
    out.push('--fix');
  }

  // Disable browser auditing; this is the common-repair wrapper.
  if (!out.includes('--max-pages')) {
    out.push('--max-pages', '0');
  }

  if (!reportProvided) {
    out.push('--report', DEFAULT_REPORT_MD);
  }
  if (!reportJsonProvided) {
    out.push('--report-json', DEFAULT_REPORT_JSON);
  }

  return { help: false, argv: out };
}

function printHelp() {
  console.log(`Usage: node tools/scripts/wcag-repair-common.js [--full|--staged|--files <path[,path...]>] [--fix|--no-fix] [--stage] [--fail-impact <level>] [--report <path>] [--report-json <path>]`);
  console.log('');
  console.log('Applies conservative WCAG-related source autofixes only (no browser audit) using the shared tests/integration WCAG engine.');
  console.log('Usable via lpd script runner: lpd tools wcag-repair-common -- --staged --stage');
}

async function main() {
  const parsed = parseWrapperArgs(process.argv.slice(2));
  if (parsed.help) {
    printHelp();
    process.exit(0);
  }

  process.chdir(REPO_ROOT);
  const wcagAudit = require(path.join(REPO_ROOT, 'tests', 'integration', 'v2-wcag-audit.js'));
  const result = await wcagAudit.runAudit({ argv: parsed.argv });
  process.exit(result.exitCode || 0);
}

main().catch((error) => {
  console.error(`wcag-repair-common failed: ${error.message}`);
  process.exit(1);
});
